import type { CRDocument } from '../types';

export const docs: CRDocument[] = [
  {
    id: "synax-baouna-1",
    title: { en: "Baouna 1", ar: "1 بؤونه" },
    blocks: [
      { kind: 'heading', text: { en: "The Consecration of the church of St. Abe-Fam (Epipham) the soldier.", ar: "استشهاد القديس أبي فام الجندي" } },
      { kind: 'reading', text: { en: "Today also, the church commemorates the great saint . This Saint was born in the city of Oseem (Giza). His father's name was Anastasius, who had a high ranking position, and his mother was a holy woman whose name was Susanna.", ar: "في هذا اليوم تعيد الكنيسة بتذكار القديس العظيم أبي فام الجندي . ولد هذا القديس ببلدة أوسيم ( الجيزة ) من أب يدعي أنسطاسيوس وكان ذا مركز رفيع وكانت أمه قديسة تدعي سوسنة، فرق أمواله علي أعمال البر وتقدم للاستشهاد في عهد دقلديانوس أمام أرمانيوس والي الإسكندرية فعذبه كثيرا ثم أرسله إلى إريانوس والي أنصنا ( ملوي ) وقد غالي في تعذيبه ولكن ملاك الرب كان يظهر له ويقويه وكان القديس أبو فام يشخص نحو السماء وأخيرا قطعوا رأسه ثم أخذ المؤمنون جسده ودفنوه بإكرام في تل من الرمال غرب طما ( سوهاج ) وقد أكمل جهاده في السابع والعشرين من شهر طوبه في إحدى سنوات حكم دقلديانوس في القرن الرابع وقد بنيت علي اسمه كنيسة بطما وأخري بأوسيم صلاته تكون معنا ولربنا المجد دائما آمين" } },
      { kind: 'reading', text: { en: "He distributed his money on the works of righteousness and went before Armanius, governor of Alexandria, during the reign of Diocletian, to be martyred. Armanius tortured him much, then sent him to , governor of Ansena (Mallawy), who tortured him, excessively. However, the angel of the Lord appeared to him, and strengthened him. Saint Abe-Fam always lifted his eyes up toward heaven and finally they beheaded him. The believers then took the body and buried him with veneration in a hill of sand west of Tema (Souhag). This Saint completed his strife on the during the reign of Diocletian, in the Fourth century. A church was built after his name in Tema and another in Oseem.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us and Glory be to God forever. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Martyrdom of St. Qozman El-Tahawy and his companions.", ar: "استشهاد القديس قزمان الطحاوي ورفقته" } },
      { kind: 'reading', text: { en: "On this day also, St. Qozman (Cosmas) El-Tahawy and his companions were martyred.", ar: "مثل هذا اليوم استشهد القديس قزمان الطحاوي ورفقته صلاتهم تكون معنا. آمين" } },
      { kind: 'reading', text: { en: "May their prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Consecration of the church of St. Leontius of Tripoli.", ar: "تكريس كنيسة القديس لاونديوس الشامي" } },
      { kind: 'reading', text: { en: "This day marks the commemoration of the consecration of the church of St. Leontius (Laventius) the Syrian. This Saint was martyred in the city of Tripoli on the A Christian woman, the wife of a great nobleman and prominent army commander, gave much money to the soldiers, and took his holy body. She wrapped it in expensive cloth and laid it in a coffer inside her house. She made a picture of him and she hung a lighted lamp before it.", ar: "في هذا اليوم تذكار تكريس كنيسة القديس لاونديوس الشامي وذلك أنه لما استشهد هذا القديس بمدينة طرابلس في الثاني والعشرين من أبيب أنفقت امرأة مسيحية زوجة أحد كبار القواد أموالا كثيرة وأخذت جسده المقدس وكفنته في ثياب غالية ووضعته في تابوت داخل بيتها وصنعت له صورة وعلقت أمامها قنديلا وحدث أن دقلديانوس غضب علي زوجها القائد ووضعه في سجن إنطاكية فحزنت وصلت إلى الله متوسلة بقديسه لاونديوس أن يخلص زوجها من السجن فقبل الله صلاتها حيث ظهر القديس لاونديوس لهذا القائد وهو في السجن وقال له : &quot; لا تحزن ولا تكتئب فأنك غدا ستخلص وتأكل مع الملك وأيقظه من نومه فأرتعب فزعا فقال له القديس : &quot; أيها الملك أنني جئت إليك لتأمر بإطلاق سراح القائد وتدعه يذهب إلى بيته لئلا تهلك &quot; فأجابه وهو يرتعد &quot; كل ما تأمرني به يا سيدي أفعله &quot; وفي الغد أستحضر الملك القائد من السجن وأكرمه وطيب خاطره وتناول معه الطعام علي مائدته وأعلمه بأمر الفارس الذي ظهر له ثم صرفه إلى بلده ولما وصل طرابلس موطنه وقص الخبر علي زوجته وأهله قالت له زوجته &quot; ان الذي تم لك من الخير إنما هو ببركة القديس لاونديوس ثم كشفت له عن الجسد فتبارك منه . ولما رأي وجهه عرف أنه هو الذي ظهر له في السجن وبعد هلاك دقلديانوس بنوا كنيسة علي اسمه ونقلوا جسده إليها باحتفال عظيم وكرست في هذا اليوم صلاته تكون معنا .آمين" } },
      { kind: 'reading', text: { en: "It happened that Diocletian became angry with her husband and shut him up in prison in the city of Antioch. She became sad, and prayed to God, interceding with His saint Leontius, to save her husband from prison. God accepted her prayers. St. Leontius appeared to her husband in prison and told him, \"Do not grieve or be sorrowful, for you shall be delivered tomorrow, and you shall eat with the Emperor at his table, and you shall return safely to your house.\" The Saint, then, went to the Emperor, and woke him up. When the Emperor saw the Saint, he became terrified. The Saint told the Emperor, \"I have come to you, O Emperor, to order the release of the army commander. Honor him, and let him go to his house, lest you be destroyed.\" The Emperor, who was trembling, replied saying, \"Whatever you command me, O my lord, I will do.\" The next morning, the Emperor brought the commander out of prison, honored him, and dined with him at his own table. The Emperor told him about the horseman that appeared to him, then dismissed him to return to his home town.", ar: "" } },
      { kind: 'reading', text: { en: "When he arrived in Tripoli, his home town, he told his wife and his family what had happened to him. His wife told him, \"The good that happened to you was through the blessings of St. Leontius.\" Then she uncovered the body of the Saint, and he took the blessing of the Saint. When he saw his face, he realized that he was the one that had appeared to him in prison.", ar: "" } },
      { kind: 'reading', text: { en: "After the perishing of Diocletian, they built a church in his name, relocated the body to it with great veneration, and the church was consecrated on this day.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "", ar: "نياحة القديس كاربوس أحد السبعين رسولا" } },
      { kind: 'reading', text: { en: "", ar: "نياحة القديس كربوس أحد السبعين رسولا. صلاته تكون معنا و لربنا المجد دائما ابديا امين ." } }
    ],
  },
  {
    id: "synax-baouna-2",
    title: { en: "Baouna 2", ar: "2 بؤونه" },
    blocks: [
      { kind: 'heading', text: { en: "The Commemoration of the Appearance of the Bodies of St. John the Baptist and Elisha the Prophet.", ar: "ظهور جسد يوحنا المعمدان وإليشع النبى" } },
      { kind: 'reading', text: { en: "On this day, the church celebrates the appearance of the bodies of and , the disciple of , in the city of Alexandria.", ar: "في هذا اليوم نعيد بتذكار ظهور جسدي القديسين يوحنا المعمدان وأليشع النبي تلميذ ايليا النبي بمدينة الإسكندرية . وذلك أنه لما قصد يوليانوس الكافر أن يبني هيكل أورشليم بعدما هدمه وسباسيانوس وابنه تيطس قاصدا بسوء رأيه أن يبطل قول الرب في الإنجيل : &quot; أنه لا يترك ههنا حجر علي حجر لا ينقض &quot; (مت 34 : 3) لذلك أمد اليهود بالمال لكي يعيدوا بناءه وأوكل ذلك إلى اليبيوس الذي دعا اليهود سرا إلى معاونته فاجتمع كثير من الرجال والنساء والشيوخ والشبان وبدأوا يحفرون الأساس بهمة وينقلون الأتربة والأحجار بعضهم بالمقاطف والبعض الأخر بأطراف أرديتهم وكان القديس كيرلس أسقف أورشليم يهزأ بعملهم هذا ." } },
      { kind: 'reading', text: { en: "Julian the Infidel wished to rebuild the Temple of Jerusalem, having been destroyed by Emperor Vespasian and his son Titus. He intended with malice to prove the invalidity of the saying of the Lord in the Holy Gospel: \"Assuredly, I say to you, not one stone shall be left her upon another, that shall not be thrown down\" ( 24:2). He supplied the Jewish people with money to rebuild it. He put Elebius, who asked the Jews to assist him secretly, in charge.", ar: "ولما انتهوا من رفع حجارة الأساس القديم وهموا بوضع الأساس الجديد حدثت زلزلة عظيمة ملأت الحفر ترابا وبددت أدوات البناء وقتلت بعض الفعلة فلم يرتدعوا اليهود بهذا وعادوا إلى العمل مرة ثانية . حينئذ خرجت من جوف الأرض كرات نارية ورشقت الفعلة بالحجارة التي عزموا علي وضعها في الأساس فكفوا عن البناء فآمن كثيرون بسبب ذلك خصوصا وقد تمت نبوة السيد المسيح بأيديهم عن نقض بناء الهيكل من أساسه وقد أورد هذه القصة غريغوريوس الثيؤلوغوس ويوحنا ذهبي الفم . كما ذكرها عرضا المؤرخ اليهودي اميان في القرن الخامس ." } },
      { kind: 'reading', text: { en: "Many of the Jews, men, women, old and young, gathered. They started digging the foundation with eagerness, transferring the dirt and rocks away, some with baskets and the others in the tails of their dresses. St. Kyrillos (Cyril), bishop of Jerusalem, ridiculed what they were doing.", ar: "ولكن اليهود قالوا للملك : &quot; ان السبب في ذلك هو وجود أجساد أئمة النصارى في هذا المكان . ويجب رفعها منه . وإلا فلن يبني الهيكل &quot; فأمر يوليانوس بإخراج أجساد القديسين من المكان وإحراقها . ولما أخرجوا جسدي القديسين يوحنا المعمدان وأليشع النبي لحرقهما تقدم بعض المؤمنين من الجند وأعطوهم مبلغا من الفضة وأخذوا الجسدين وأتوا بهما إلى القديس أثناسيوس بابا الإسكندرية فسر بذلك ووضعهما في مكان خاص إلى أن يبني لهما كنيسة ." } },
      { kind: 'reading', text: { en: "When they finished raising the rocks of the old foundation, they started to put down the new one. A severe earthquake took place, filled the excavation with dirt, dispersed the building material and killed many of the workers. The Jews were not terrified of that, and returned to the work again. Out of the depths of the earth, fiery balls came, showering the workers with rocks and hitting them so they stopped building. Many of them believed because of that and especially because they had fulfilled the prophesy of the Lord Christ, with their hands, about the destruction of the building of the temple from its foundation.", ar: "وفي أحد الأيام كان جالسا في البستان ومعه كاتبه البابا ثاؤفيلس الذي خلفه علي الكرسي فقال له &quot; ان أطال الرب أجلي بنيت في هذا الموضع كنيسة علي اسم هذين القديسين يوحنا المعمدان واليشع النبي وأضع جسديهما فيها &quot; . ولما جلس البابا ثاؤفيلس علي كرسي الكرازة المرقسية تذكر الكلام الذي قاله البابا أثناسيوس ونقل إليها الجسدين الطاهرين وقد حدث وهم سائرون بالجسدين أن عبروا أمام بيت امرأة وثنية لها أربعة أيام متعسرة في الولادة فسمعت ضجة الاحتفال ولما علمت السبب نذرت قائلة : يا قديس الله يوحنا إذا نجوت من هذه الشدة صرت نصرانية ولم تتم كلمتها حتى وضعت ولدا فأسمته يوحنا ثم تعمدت هي وأهل بيتها أما الجسدان فقد وضعوهما في الكنيسة وقد ظهرت منهما عجائب كثيرة ، أما يوليانوس الكافر فكانت نهايته كما يأتي :" } },
      { kind: 'reading', text: { en: "St. Gregory the Theologian and had mentioned this incident. The Jewish historian Emian, in the fifth century, had mentioned this account also incidentally in his writings.", ar: "عزم عل بالقيام بحرب ضد سابور ملك الفرس فقابله القديس باسيليوس الكبير واضع القداس ، وبعض الأساقفة فقال لهم لماذا حضرتم ؟ أجابه باسيليوس &quot; أتينا نطلب راعيا &quot; فقال له بتهكم &quot; وأين تركت ابن النجار &quot; فأجابه بشهامة وكبرياء &quot; تركناه يصنع لك تابوتا لأنك فقدت كل علم ومعرفة &quot; قال له يوليانوس &quot; قد قرأتها وحفظتها &quot; فرد عليه باسيليوس &quot; ولكنك لم تفهمها &quot; فاغتاظ يوليانوس وأمر بالقبض عليهم ليقدمهم للموت بعد رجوعه فقال له &quot; لن تعود ، وإلا فلم ينطق الله علي فمي &quot; ثم أمر بسجنهم . وبعد أن ذهب للحرب صلي القديس أمام أيقونة مرقوريوس أبو سيفين طالبا تأديبه علي أهانته لسيده يسوع فغاب مرقوريوس عن الصورة ثم رجع وسيفه يقطر دما . وفي الحرب أصاب يوليانوس سهم في كبده وقال ثلودوريتس في تاريخه الكنسي لما طعن ذلك الملك الكافر تلقي في كفيه الدم المتدفق من جنبه ونثره نحو السماء قائلا : &quot; لقد قهرتني يا ابن مريم &quot; فتمت فيه نبوة القديس باسيليوس ، ونجت الكنيسة من شره ولما استشهد القديس مقاريوس أسقف أدكو وضعوا جسده مع جسدي يوحنا المعمدان وأليشع النبي . صلاتهم تكون معنا ولربنا المجد دائما . آمين" } },
      { kind: 'reading', text: { en: "Nevertheless, the Jews told the Emperor, \"The reason for what happened is the presence of the bodies of Christian leaders in that place. They must be removed from it, otherwise the temple will not be built.\" Julian ordered that the bodies of the saints be removed from the place and burned. When they took the bodies of St. John the Baptist and Elisha the Prophet to burn them, some believers came forward to the soldiers, gave them a sum of silver and took the two bodies. They brought them to St. Athanasius, Pope of Alexandria. He was pleased and placed them in a special place until he could build a church for them.", ar: "" } },
      { kind: 'reading', text: { en: "One day St. Athanasius was sitting in the garden with his scribe, the one to be Pope Theophilos (23rd Pope) who succeeded him on the Chair, and told him, \"If God gives me long days, I will build in this place a church in the names of St. John the Baptist and Elisha the Prophet, and I will lay their bodies in it.\"", ar: "" } },
      { kind: 'reading', text: { en: "When Pope Theophilos was enthroned on the Chair of the See of , he remembered what Pope Athanasius had told him. He built the church and relocated the pure bodies to it. On their way to the church carrying the holy bodies, they passed by a house of a pagan woman. This woman was in labor for the last four days. She had a difficult labor and she was in severe pain. When she heard the singing and the chanting of the people as they passed by, and when she knew what was happening, she vowed, saying, \"O John, the saint of God, if you deliver me from this tribulation, I will become a Christian.\" Before she had finished what she was saying, she gave birth to a boy, and she called him John. Then, her family and she were baptized. They laid the bodies with great honor in the church. Many miracles and wonders were manifested through them.", ar: "" } },
      { kind: 'reading', text: { en: "As of the end of Julian the infidel was as follows: He decided to declare a war against Sapor, King of Persia.", ar: "" } },
      { kind: 'reading', text: { en: "St. Basilius the Great, the author of the liturgy, and some bishops went to meet him. Emperor Julian asked them, \"Why have you come.\" St. Basilius replied, \"We came asking for a shepherd\" He mocked them saying, \"Where did you leave the son of the carpenter?\" The Saint answered with courage and pride, \"We left him making a coffin for you, for you have lost all wisdom and knowledge.\" Julian told him, \"I have read and memorized it.\" St. Basilius replied, \"But you did not comprehend it.\" Julian became angry and ordered them seized, to be slain after his return from the war with Sapor. St. Basilius told him, \"You will not come back, for God has spoken by my mouth.\" The Emperor ordered them imprisoned.", ar: "" } },
      { kind: 'reading', text: { en: "The Emperor went to the war. St. Basilius prayed before the icon of St. Marcurius Abu-saifain, asking for the chastisement of the Emperor because he insulted his Lord Christ. St. Marcurius disappeared from the icon, and when he returned, his sword was dripping blood.", ar: "" } },
      { kind: 'reading', text: { en: "During the war, Julian was shot by an arrow in his liver. Thlodoritius said in his history of the church: \"When this infidel Emperor was stabbed, he took a handful of the blood that was pouring out of his side and scattered it toward the heaven, saying, 'You have defeated me O Son of Mary.'\" The prophesy of St. Basilius was fulfilled in him and the church was saved from his evil.", ar: "" } },
      { kind: 'reading', text: { en: "When , was martyred, they placed his body with the bodies of St. John the Baptist and Elisha the Prophet.", ar: "" } },
      { kind: 'reading', text: { en: "May their prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of Pope Yoannis the Eighteenth, the 107th. Pope of Alexandria.", ar: "نياحة البابا يوأنس الثامن عشر البطريرك" } },
      { kind: 'reading', text: { en: "On this day also, the church celebrates the departure of Pope Yoannis (John) the Eighteenth, the 107th Pope of Alexandria. He was of the people of El-Fayyoum and his name was Joseph. He became a monk in the monastery of the great St. Antonios on the mount of El-Araba. When Pope Marcus the seventh, his predecessor, departed, the bishops, priests, and the notables of the people unanimously agreed on choosing him a Patriarch. They brought him and ordained him a Patriarch in the church of the martyr St. Marcurius in Old Cairo. That was on Sunday, , 1486 A.M. (October 23, 1769 A.D.). He was called Yoannis the Eighteenth, the 107th Pope of Alexandria.", ar: "في هذا اليوم تعيد الكنيسة بتذكار البابا يوأنس الثامن عشر البطريرك ( 107 ) . وكان من أهالي الفيوم وكان يدعي أولا باسم يوسف وترهبن بدير القديس العظيم الأنبا أنطونيوس بجبل العربة فلما تنيح البابا مرقس السابع سلفه أجمع رأي الأساقفة والكهنة وأراخنة الشعب علي اختياره بطريركا فأحضروه ورسموه بطريركا في كنيسة القديس مرقوريوس أبي سيفين بمصر القديمة في يوم الأحد المبارك 15 بابه سنة 1486 ش ( 23 أكتوبر سنة 1769 م ) ودعي باسم يوأنس الثامن عشر البطريرك (107) . وفي أيامه سعي بابا روميه لاجتذاب الكنائس الشرقية وخاصة كنيسة مصر الأرثوذكسية إلى المذهب الكاثوليكي وقام بنشر كتاب أعمال مجمع خلقيدونية ووزعوه علي جميع البلاد الشرقية فكان ذلك سببا في انشقاق الكنيسة ورفض الاعتراف بأمانته البابا القديس ديسقورس البطريرك (25) . ثم أرسل بابا رومية مندوبا من قبله للبابا يوأنس يحمل رسالة يدعوه فيها إلى الاتحاد معه فسلم البابا هذه الرسالة إلى الأنبا يوساب الأبح أسقف جرجا وكلفه بدراستها والرد عليها فقام هذا العلامة الكبير واللاهوتي العظيم بالرد عليها وتفنيد دعوى روما فدافع عن كنيسته وأمانتها ومعتقداتها دفاعا مجيدا خلد به ذكراه أما كتاب أعمال مجمع خلقيدونية فقد أتي علي عكس ما كانت تنتظره روما من نشره إذ جاء مثبتا لصحة معتقدات الكنيسة القبطية الأرثوذكسية فندم أسقف روما علي نشره في الشرق وقام بجمع نسخه وأحرقها . وقد نالت البابا يوأنس في مدة رئاسته شدائد وضيقات كثيرة من حكام البلاد والولاة العثمانيين وقام القائد التركي بمصادرة الخزينة البطريركية وأخذ أموالها الأمر الذي اضطر البابا إلى أن يختفي من ظلم هؤلاء الحاكمين الذين أرهقوا المسيحيين بأحكامهم الجائرة وبزيادة الضرائب المقررة عليهم واشترك البابا يوأنس مع المعلم إبراهيم الجوهري رئيس كتاب مصر في ذلك العهد في تعمير الأديرة والكنائس كما قام بعمل الميرون المقدس وتنيح في اليوم الثاني من شهر بؤونه المبارك سنة 1512 للشهداء الأبرار ( الموافق 7 يونيو سنة 1796 م ) بعد أن قام علي الكرسي البطريركي 26 سنة و 7 أشهر و 16 يوما ودفن بمقبرة البطاركة الأبرار في كنيسة القديس مرقوريوس أبي سيفين وظل الكرسي بعده خاليا مدة ثلاثة أشهر وستة وعشرين يوم ." } },
      { kind: 'reading', text: { en: "During his days, the Pope of Rome attempted to attract the Eastern Churches and especially the Orthodox Church of Egypt (The Coptic Church) to the Catholic rite. He published the proceedings of the Council of Chalcedone in a book and distributed it in all the countries of the East. This council had caused the schism of the church, and the had refused to recognize the legitimacy of this council.", ar: "صلاة هذا القديس تكون معنا . ولربنا المجد دائما . آمين" } },
      { kind: 'reading', text: { en: "The Pope of Rome then sent an envoy to Pope Yoannis carrying a message inviting him to be united with him. Pope Yoannis gave this message to Anba Yusab El-Abbah, bishop of Girga. He asked him to study it and to respond to it. This great scholar and distinguished theologian replied, refuting all the claims of Rome. He defended his church, its faith, and its doctrines, a splendid defense that immortalized his memory. However, the book of the proceedings of the Council of Chalcedone brought the opposite results of what Rome expected from publishing it. The book was a proof of the sound teachings and doctrines of the Coptic Orthodox church. The Bishop of Rome was sorry for publishing the book in the East, and he gathered its copies and burned them.", ar: "" } },
      { kind: 'reading', text: { en: "During the papacy of Pope Yoannis (John) many tribulations and hardships befell him from the rulers of the country and the Ottoman governors. The Turkish commander of the army seized the patriarchate treasury and took all its funds. That forced the Pope to disappear from the oppression and the injustice of those rulers who over tasked the Christians with their unjust rules and the enormous increase of taxes stipulated from them.", ar: "" } },
      { kind: 'reading', text: { en: "Pope Yoannis participated with , the head scribe at that time, in restoring the monasteries and the churches. He also made the Holy Myron. He departed on the second day of the blessed month of Baounah, 1512 A.M. (June 7, 1797 A.D.). He remained on the patriarchal chair for twenty-six years, seven months, and sixteen days. He was buried in the tomb of the patriarchs in the church of St. Marcurius Abu-Saifain. The chair remained vacant three months and twenty-six days after his departure.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us and Glory be to God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baouna-3",
    title: { en: "Baouna 3", ar: "3 بؤونه" },
    blocks: [
      { kind: 'heading', text: { en: "The Departure of St. Abraam, bishop of El-Fayyoum.", ar: "نياحة الانبا ابرام أسقف الفيوم" } },
      { kind: 'reading', text: { en: "Today also, the saint Anba Abraam, Bishop of El-fayyoum and El-Giza, departed. This was in the year 1630 A.M. (June 10, 1914 A.D.). This saint, whose name was Paul (Boulos), was born in 1545 A.M. (1829 A.D.) in the Estate of \"Gilda\", district of Mallawi, governate of Miniah, to righteous parents. They brought him up in a Christian manner. They sent him to the church school, where he learned religious subjects and the church hymns. As he was a very bright student, Anba Yousab, the Bishop of Sunabbo ordained him a deacon for the church of Gilda. His heart longed for the monastic life, so he went to El-Muharrak monastery where he was ordained a monk by the name of Paul Gabriel El-Muharraki. He was nineteen years old.", ar: "في مثل هذا اليوم تنيح القديس الأنبا أبرآم أسقف الفيوم والجيزة وذلك في سنة 1630 للشهداء الأبرار ( 10 يونيو سنة 1914 م ) . ولد هذا القديس وكان اسمه بولس في سنة 1545 ش ( 1829 ) بعزبة جلدة مركز ملوي مديرية المنيا من والدين تقيين فربياه تربية مسيحية وأدخلاه الكتاب فتلقي فيه العلوم الدينية التراتيل الكنيسة . ولما أظهر نبوغا بين أقرانه رسمه الأنبا يوساب أسقف صنبو شماسا علي كنيسة بلدته ومال قلبه إلى الرهبنة فقصد دير المحرق ورسم راهبا باسم بولس غبريال المحرقي في التاسعة عشر من عمره ." } },
      { kind: 'reading', text: { en: "He was meek, humble, had a pure life, and he prayed much in seclusion. Accordingly, the monks loved him exceedingly. When Anba Yakoubos, bishop of El-Meniah, heard of him, he summoned him. He retained him in the episcopate for a period of time during which he promoted him to a priest. When he returned to his monastery, the monks with a consensus decided to make him the abbot over the monastery after the death of their Abbot. He was then promoted to archpriest (hegumen) in the days of Abba Demitrius the second (111th Patriarch). He remained Abbot of the monastery for five years, during which the monastery was the refuge for thousands of the poor. So he was called the father of the poor and the destitute. During his time as abbot, he did not spare an effort to improve the condition of the monastery spiritually and physically. He improved its finances by developing its agricultural land. As he increased his charity toward the poor, the orphans and the widows, some of the monks became more resentful of him, for they considered these charitable works as squandering and extravagant acts. They complained against him to Anba Morcos, Metropolitan of El-Behira, who was the acting Patriarch after the death of Pope Demitrius. Anba Morcos accepted their complaints and deposed him as the abbot of their monastery. Shortly after his dismissal, he left El-Muharrak monastery and went to the monastery of El-Baramous. Several monks from the El-Muharrak monastery went to the monastery of El-Baramous, with archpriest Bolous (Abba Abraam), because they did not like the attitudes of the complaining monks. He stayed there for some time studying the Bible and teaching the monks.", ar: "وكان وديعا متواضعا طاهر السيرة كثير الانفراد للصلاة فأحبه الرهبان حبا جما وسمع به وقتئذ الأنبا ياكوبوس أسقف المنيا فاستدعاه إليه واستبقاه مدة بالأسقفية رقاه في أثنائها إلى رتبة قس ، ولما عاد إلى ديره الذي كان عامرا وقتئذ بالرهبان الأتقياء اتفقت كلمتهم علي أن يختاروه رئيسا لهم بعد وفاة رئيسهم . ورقي قمصا في أيام البابا ديمتريوس الثاني البطريرك (111) ولبث خمس سنوات رئيسا للدير كان فيها الدير ملجأ لآلاف الفقراء حتى أطلق عليه لقب أب الفقراء والمساكين . ولم يأل جهدا في مدة رئاسته نحو تحسين حالة الدير روحيا وماديا وإنماء ثروته وإصلاح أراضيه الزراعية وكان كلما ازداد برا بالفقراء وإحسانا لليتامى والأرامل ازداد حقد بعض الرهبان عليه لأنهم كانوا يعتبرون هذه الأعمال الخيرية إسرافا وتبذيرا فتذمروا عليه وشكوه إلى الأنبا مرقس مطران البحيرة الذي كان قائما وقتئذ بالنيابة البطريركية لوفاة البابا ديمتريوس فقبل شكايتهم وعزله من رئاسة الدير وبعد زمن يسير من اعتزاله الرئاسة ترك دير المحرق وذهب إلى دير البرموس وأقام به مدة لا عمل له إلا درس الكتاب وتعليم الرهبان وكان رئيس الدير وقتئذ القمص يوحنا الناسخ الذي صار فيما بعد البابا كيرلس الخامس البطريرك (112) . كما ذهب إلى دير البرموس مع القمص بولس رهط من رهبان دير المحرق الذين لم يعجبهم حال إخوانهم المتذمرين به وفي سنة 1597 ش ( سنة 1881م ) اختاره البابا كيرلس الخامس أسقفا لأبرشية الفيوم والجيزة بدلا من أسقفها المتنيح الأنبا إيساك فتمت رسامته باسم الأنبا أبرآم وقد اشتهر في مدة أسقفيته بأمرين :" } },
      { kind: 'reading', text: { en: "The abbot of the monastery of El-Baramous at that time was archpriest Youhanna the Scribe, who became later on . In the year 1597 A.M. (1881 A.D.), Pope Kyrillos the Fifth chose and ordained him a bishop for the parish of El-Fayyoum and El-Giza. He replaced its reposed bishop, Anba Eisak, and was ordained with the name of Abba Abraam.", ar: "عطاياه للفقراء الكثيرين الذين كانوا يقصدون دار الأسقفية فيهبهم كل ما يكون لديه من المال . وقد جعل دار الأسقفية مأوي لكثيرين منهم . وكان يقدم ثيابا للعريانين وطعاما لجائعين ولم يسمح مطلقا بأن يقدم إليه طعام أفخر مما يقدم للفقراء واتفق مرة أن نزل ليتفقد الفقراء وهم يتناولون الطعام فلاحظ أن الطعام الذي قدم إليه في ذلك اليوم كان أفخر مما وجده أمامهم فساوره الحزن وفي الحال أقال الراهبة التي كانت موكلة بخدمة الفقراء من عملها ." } },
      { kind: 'reading', text: { en: "During his episcopate, he became famous for two attributes:", ar: "أما الأمر الثاني" } },
      { kind: 'reading', text: { en: "The First: His charity to the multitude of poor that came to the bishopric residence. He gave them all what he had of money. He made the bishopric residence a shelter for many of them. He offered clothing for those who had no clothes and food for those who were hungry. He never allowed anyone to offer him food that was better than that offered to the poor. Once he went down to visit the poor while they were eating, and found that the food he was offered that day was better than that offered to them. He became very sad, and immediately relieved the nun supervising the feeding service of the poor from her duties.", ar: "الذي أشتهر به فهو الأيمان التي جرت بواسطتها علي يديه آيات شفاء عديدة حتى ذاع اسمه في أنحاء القطر وبعض بلدان أوربا أيضا وكان يقصده المرضي أفواجا علي تباين أديانهم فيتباركون بصلاته وينالون الشفاء ." } },
      { kind: 'reading', text: { en: "The Second: He was famous for his prayer of faith. Many miracles were performed, through his prayers, on his hands. His fame was spread to all parts of Egypt and also to some parts of Europe. Many patients, of different religions, came to him, seeking the blessing of his prayers and were healed. Anba Abraam was well read of the holy books. He always gave to his visitors advice, instructions and sermons which showed the great depth of his knowledge. More important was that he possessed a pure nature and many virtues. Particularly, his severe denial of himself, and his true renouncement of the pleasures of life and its vain glory. His food and clothing were just bare necessities. His ambition never looked up to the glory of higher ranks or positions. When the Patriarch wanted to promote him to the rank of metropolitan he apologized saying that the Holy Bible did not mention any ranks in the priesthood except the ranks of the priest and the bishop.", ar: "وكان الأنبا أبرآم واسع الإطلاع علي الكتب المقدسة يلقي علي زائريه دائما نصائح وتعاليم وعظات تدل علي وفرة علمه بأسرار الكتاب المقدس ولكن الأهم من ذلك أنه كان ذا صفات نقية وفضائل جمة . ومن أخص تلك الصفات إنكاره لذاته إنكارا شديدا وزهده الحقيقي في ملاذ الحياة وأمجادها فطعامه ولباسه لم يتجاوزا قط حد الضرورة ونفسه لم تكن تطمح إلى أبهة المناصب والرتب حتى أن البطريرك لما أراد أن يرفعه إلى رتبة المطرانية اعتذر عن قبولها بقوله أن الكتاب المقدس لا يذكر من رتب الكنيسة إلا القسيسية والأسقفية . ومن صفاته أيضا أنه كان صريحا إلى أقصي حدود الصراحة في إبداء رأيه . ولا ينظر فيما يقول إلا إلى الحق لذاته ، فتتضاءل أمامه هيبة العظماء ومراكز الكبراء أمام هيبة الحق وجلاله . ولذلك كان مطارنة الكنيسة وأساقفتها يتقون غضبه ويتمنون رضاه." } },
      { kind: 'reading', text: { en: "He was also straightforward in revealing his own opinion, looking only for the truth. He never gave any attention to the rank and greatness of people in higher places, for their greatness was far less than the greatness of the truth. For this reason, all the metropolitans and bishops of the church avoided his anger and sought to please him.", ar: "وانتقل الأنبا ابرآم إلى النعيم في 3 بؤونة سنة 1630 ش ( 10 يونية 1914م ) فشيعه إلى القبر أكثر من عشرة آلاف نفس من المسلمين والمسيحيين ووضع جثمانه الطاهر في المقبرة المعدة له في دير العذراء بالعزب . وقد ظهرت منه آيات كثير بعد وفاته حيث لم تزل مقبرته كعبة يزورها ذوو الحاجات والأوجاع .بركة صلاته تكون معنا ولربنا المجد دائما . آمين" } },
      { kind: 'reading', text: { en: "Abba Abraam departed to the heavenly bless on the 3rd day of Baouna, 1630 A.M. (June 10, 1914 A.D.).", ar: "" } },
      { kind: 'reading', text: { en: "More than ten thousand Christian and Moslems walked in his funeral precession. His pure body was laid in the tomb, which was prepared for him in the monastery of the in El-Ezab. Many miracles were manifested through him after his departure, and his tomb became and still is a pilgrimage for many who have special needs or infirmities.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us and Glory be to God forever. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Martyrdom of St. Alladius the Bishop.", ar: "استشهاد القديس اللاديوس الأسقف" } },
      { kind: 'reading', text: { en: "Today also marks the martyrdom of St. Alladius (Hilarius or Hilarion), bishop of one of the countries of the East. One day, he rebuked for worshipping the idols. The Emperor replied, \"If I am, in your opinion infidel, because I do not worship that whom was crucified, I shall make you also forsake worshipping him.\" Then the Emperor handed him to one of his officers and commanded him to torture Alladius without mercy for one year. When he did not turn away from his firm intention, he lit a fire in a pit and threw him in it, but no harm came upon him. Many believed, and the Emperor ordered their heads to be cut off. Finally, they brought the saint out of the pit, and ordered to cut off his head. He delivered up his soul in the hand of the Lord Christ and received the crown of martyrdom.", ar: "في مثل هذا اليوم استشهد القديس اللاديوس أسقف إحدى بلاد المشرق وذلك أنه كان في يوم من الأيام يوبخ الوالي يوليكوس علي عبادته الأصنام فقال له الوالي إذا كنت في نظرك كافرا لأني لا أعبد المصلوب فها أنا أجعلك أنت أيضا تترك عبادته . ثم سلمه لأحد نوابه وأمره أن يعذه بلا رحمة مدة سنة ، ولما لم ينثن عن عزمه الصادق أوقد نارا في حفرة وطرحه فيها فلم تمسه بأذى . فآمن جمع كثير وأمر الوالي بقطع رؤوسهم وأخيرا أخرجوا القديس من الحفرة وآمر بضرب عنقه فاستودع روحه بيد السيد المسيح ونال إكليل الشهادة صلاته تكون معنا . آمين" } },
      { kind: 'reading', text: { en: "May his prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Construction of the first church of St. George in the cities of Birma and Beer Maa (Water Well) in the Oases.", ar: "بناء أول كنيسة لمار جرجس ببلدتي برما وبئر ماء بالواحات" } },
      { kind: 'reading', text: { en: "On this day, the first church in the name of was built in Egypt in the city of Beer Maa in the Oasis. As was consecrated also on this day a church in his name in the city of Birma, district of Tanta. For after the perishing of Diocletian, and the reign of the righteous , all the temples of the idols were destroyed. Churches were built after the name of the heroic martyrs, who strived with their blood to defend the faith.", ar: "في مثل هذا اليوم بنيت أول كنيسة علي اسم الشهيد العظيم مار جورجيوس بالديار المصرية ببلدة بئر ماء بالواحات كما كرست باسمه في مثل هذا اليوم أيضا كنيسة في بلدة برما مركز طنطا ، وذلك أنه بعد هلاك دقلديانوس وملك الملك البار قسطنطين هدمت هياكل الأوثان وبنيت الكنائس علي أسماء الشهداء الأبطال الذين جادوا بدمائهم في الدفاع عن الأيمان ." } },
      { kind: 'reading', text: { en: "Some Christian soldiers in the land of Egypt, had donated a piece of the land where the city of Birma is now located. One of them was a righteous and meek young man, who lived on a piece of this land with some of the farmers. In this area there was a well of water. This young man heard of the wonders of the great among the martyrs, St. George. He searched until he found his biography. He wrote it, and it comforted him to read it, which he did without boredom.", ar: "وكان بالديار المصرية قوم من الجنود المسيحيين وهبوا جزءا من الأرض المقامة عليها برما الآن ، وكان من بينهم شاب تقي وديع يقيم بقطعة منها مع بعض المزارعين وكان بتلك الجهة بئر للشرب فسمع هذا الشاب بعجائب العظيم في الشهداء جورجيوس فسعي حتى حصل علي سيرته وكتبها وصار بتعزي بقراءتها بغير ملل وحدث في ليلة اليوم الرابع والعشرين من شهر بشنس وهو قائم يصلي أن رأي جماعة من القديسين وقد نزلوا بجوار هذه البئر يسبحون الله ويرتلون بأصوات ملائكية وهم محاطون بنور سماوي فاستولت عليه الدهشة . وعندئذ تقدم إليه واحد منهم في زي جندي وعرفه أنه جورجيوس الذي استشهد علي يد دقلديانوس وأمره أن يبني له كنيسة في هذا الموضع لان هذه مشيئة الرب ، ثم ارتفعت عنه الجماعة إلى السماء وهم يمجدون العلي وقضي الشاب ليلته متيقظا حتى الصباح ومرت عليه عدة أيام وهو يفكر كيف يبني هذه الكنيسة وهو لا يملك ما يقوم بنفقات جزء بسيط منها وفي إحدى الليالي وهو واقف يصلي ظهر له الشهيد العظيم جورجيوس وحدد له مكان الكنيسة ثم أرشده إلى مكان وقال له احفر هنا وستجد ما تبني به الكنيسة . ولما استيقظ في الصباح ذهب إلى حيث أرشده الشهيد الجليل وحفر فوجد إناء مملوءا ذهبا وفضة فسبح الله وعظم قديسة وبني الكنيسة ثم استدعي الأب البطريرك وكرسها في مثل هذا اليوم وبنيت المنازل بجوار هذه الكنيسة وسميت هذه الجهة ( بئر ماء ) نسبة إلى بئر الماء التي بنيت بجوارها الكنيسة ويجري الاحتفال بهذا التذكار المجيد في هذه البلدة سنويا وهناك تظهر الآيات الباهرة من إخراج الشياطين وشفاء المرضي بشفاعة هذا الشهيد العظيم . صلاته تكون معنا آمين ." } },
      { kind: 'reading', text: { en: "While he stood praying, on the evening of the , he saw that an assembly of the saints had come down beside the well. They were praising God and chanting with angelic voices. They were surrounded by heavenly light, and he was astounded. One of them, who was in the uniform of a soldier, came forward and informed him that he was Gawargios (George) who was martyred at the hands of Diocletian. He ordered him to build a church for him on that site, for that was the Will of God. The assembly left him, and raised up to heaven while they were glorifying the Most High.", ar: "ونقلت أعضاء القديس جورجيوس التي كانت محفوظة في بيعته من مدينة بئر ماء بالواحات إلى دير أنبا صموئيل بمعرفة رهبانه وذلك في أيام الأب القديس متاؤس البطريرك (87) ورئاسة الأب القس زكري ابن القمص والأب الراهب سليمان القلموني ، وفي عهد رئاسة البابا غبريال البطريرك (88) نقلت أعضاء القديس إلى الكنيسة المعروفة باسمه بمصر القديمة وكان ذلك في يوم 16 أبيب سنة 1240 ش ( 10 يوليه سنة 1524 م ) ." } },
      { kind: 'reading', text: { en: "The young man spent that night awake till morning. Few days passed during which he was thinking about how he could build this church, knowing that he did not have the money for a small piece of it. One night, while he stood praying, the great martyr St. George appeared to him. The Saint pointed out to him the place to build the church. Then he directed the young man to another place and told him, \"Dig here and you shall find what you need to build the church.\" When he woke up in the morning, he went where the honorable martyr had directed him. He dug there and found a vessel filled with gold and silver. He praised God, and glorified his patron saint. He built the church and called the father the Patriarch who consecrated it on this day.", ar: "صلاته وشفاعته تكون معنا ولربنا المجد الدائم إلي الأبد آمين ." } },
      { kind: 'reading', text: { en: "The relics of St. George, that were kept in his church in the city of Beer Maa in the Oasis, were relocated to the monastery of Anba Samuel by its monks. That was during the days of the Saint Abba Mattheos (87th Patriarch), and the monastery was under the direction of Fr. Zachary Ebn-Elkomos and Fr. Soliman El-Qualamony.", ar: "" } },
      { kind: 'reading', text: { en: "During the Papacy of Pope Gabriel (88th Patriarch) the relics of the saint were relocated to his well-known church in Old Cairo. That was on the , 1240 A.M. (July 10, 1024 A.D.).", ar: "" } },
      { kind: 'reading', text: { en: "A great celebration takes place annually, where the church was built beside the water well, to commemorate this venerable event. There, many signs of casting out of evil spirits and healing of the sick take place with the intercession of this great martyr.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of St. Martha of Egypt.", ar: "نياحة القديسة مرتا المصرية" } },
      { kind: 'reading', text: { en: "On this day also, the ascetic and fighter St. Martha, departed. She was born in the city of Mesr (Cairo) to wealthy Christian parents. She loved fornication and unchastity in her youth and her works became known. However, the mercy of God from above encompassed her, and moved her to go to the church. That was on the Nativity of Our Lord. When she came to its door and wished to go inside, the servant delegated to watch the door told her, \"It is not meet for you to go into the holy church, for you know what you are?\" A confrontation took place between them, and when the Bishop heard the clamor, he came to the door of the church to see what had happened. When he saw the girl, he said to her, \"Do you not know that the house of God is holy, and only the pure enter it.\" She wept and said, \"Accept me O father, for I am repentant from this instant, and have decided not to go back to my sin.\" The bishop replied, \"If it is true what you have said, go and bring back here all your silk clothes and gold ornaments.\"", ar: "في مثل هذا اليوم استشهدت المجاهدة الناسكة القديسة مرتا . ولدت بمصر من أبوين مسيحيين غنيين ولما شبت اندفعت وراء الأميال الشريرة فهوت في نجاسة السيرة ولكن رحمة الله تداركتها من العلاء فحركتها للذهاب إلى الكنيسة في يوم عيد الميلاد . فلما وصلت إلى بابها وهمت بالدخول منعها الخادم الموكل بالباب قائلا &quot; أنك غير مستحقة أن تدخلي بيت الله المقدس وأنت كما تعلمين &quot; وحصلت بينهما ضجة سمعها الأسقف فأتي إلى الباب ليري ما الخبر . فلما رأي الفتاة قال لها &quot; أما تعلمين أن بيت الله مقدس ولا يدخله غير الطاهر ؟‍ &quot; فبكت وقالت : &quot; أقبلنى أيها الأب فأنني تائبة من هذه اللحظة ومصممة علي عدم العودة إلى الخطية &quot; فقال لها : &quot; أن كان الآمر حقا كما تقولين فاحضري لي ملابسك الحريرية وزينتك الذهبية وتعالي إلى هنا &quot; فمضت بسرعة وأحضرت كل ما كان لها من حلي وملابس وقدمتها إلى الأب الأسقف فأمر بحرقها في الحال ثم حلق شعر رأسها وألبسها ثياب الرهبنة ، وأرسلها إلى أحد أديرة الراهبات وهناك جاهدت جهادا عظيما وكانت تقول في صلاتها : &quot; يارب ان كنت لم أحتمل الفضيحة من خادم بيتك فلا تفضحني أمام قديسيك وملائكتك &quot; ولبثت مدة خمس وعشرين سنة في الجهاد لم تخرج في أثنائها من باب الدير حتى تنيحت بسلام ." } },
      { kind: 'reading', text: { en: "She went quickly and brought back all of her clothes and ornaments and gave them to the Bishop. He ordered that they be burned immediately, then he shaved off the hair of her head. He put on her the monastic garb and sent her to one of the convents. She fought a great spiritual fight, and she frequently said in her prayers: \"O Lord, if I could not bear the disgrace from the servant of Your house, so please do not put me to shame before Your angels and saints.\" She continued the spiritual fight for twenty-five years, during which she did not go out of the door of the convent, then departed in peace.", ar: "صلاتها تكون معنا . آمين" } },
      { kind: 'reading', text: { en: "May her prayers be with us. Amen", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of Pope Cosmas, the 44th Patriarch.", ar: "نياحة البابا قسما البطريرك" } },
      { kind: 'reading', text: { en: "This day also marks the departure of Pope Cosmas the First (44th Patriarch), in the year 446 A.M. (June 24, 730 A.D.). He was from the village of Abi-Sair. He became a monk in the monastery of St. Macarius. He was ordained against his will a patriarch on Sunday the , 445 A.M. (March 729 A.D.). He did not cease, since his enthronement, from asking God to repose his soul speedily. God responded to his request after one year and three months of his enthronement.", ar: "في مثل هذا اليوم تنيح البابا قسما الأول سنة 446 ش ( 24 يونية سنة 730 م ) وأصله من أبي صير وترهب بدير أبي مقار، ورسم بطريركا رغما عنه يوم الأحد 30 برمهات سنة 445 ش ( مارس 729 م) ولم يبرح منذ توليه الكرسي عن السؤال كي ينيح الله نفسه سريعا فأجاب الله طلبته بعد أن تولي علي الكرسي مدة سنة واحدة وثلاثة شهور صلاته تكون معنا . آمين" } },
      { kind: 'reading', text: { en: "May his prayers be with us. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baouna-4",
    title: { en: "Baouna 4", ar: "4 بؤونه" },
    blocks: [
      { kind: 'heading', text: { en: "The Martyrdom of St. Shenousi (Sanusi).", ar: "استشهاد القديس سينوسيوس" } },
      { kind: 'reading', text: { en: "On this day, St. Sanusi (Shenousi), who was from Balkim, was martyred. When he was a young man, he tended the sheep. He used to give his food to the young shepherds, and spend his day fasting. He visited the sick and those who were in prison.", ar: "في مثل هذا اليوم استشهاد القديس سينوسيوس. صلاته تكون معنا و لربنا المجد دائما ابديا امين ." } },
      { kind: 'reading', text: { en: "One night, the angel of the Lord appeared to him in a vision and told him, \"Rise up, and go before the governor and confess your God to receive the crown of martyrdom.\" When he woke up from his sleep, he told that to his mother. She was sorry and wept for she was unable to prevent him. He had heard about a righteous holy woman, in the city of Shoubra, whose name was Mariam. She received the poor and the sojourners and did many good deeds. He went to her, and both agreed on receiving the crown of martyrdom. They went to Arsanos, the governor, who was residing in a ship anchored on the bank of the river Nile. They cried out before him saying, \"We are Christians.\" He ordered that they be tortured. While they were torturing them, St. Mariam delivered up her soul in the hand of the Lord. The Lord Christ comforted and strengthened St. Sanusi. When the Governor failed to change his conviction, he sent him with many others to the Governor of Ansena (Antinoe), who tortured him severely. Then, he brought a sorcerer from Akhmeem, who gave the Saint a drink mixed with poison. The Saint having made over it the sign of the Cross, drank it, and no harm came to him. When the governor was tired of torturing him, he ordered him put to death. They cut off his head with the sword.", ar: "" } },
      { kind: 'reading', text: { en: "The sorcerer believed when he saw that, so they cut off his head also. Both received the crown of martyrdom.", ar: "" } },
      { kind: 'reading', text: { en: "May their prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Martyrdom of Saint Anba Amoun and the Righteous Sophia.", ar: "" } },
      { kind: 'reading', text: { en: "On this day also, Saint Anba Amoun and St. Sophia were martyred.", ar: "" } },
      { kind: 'reading', text: { en: "May their prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Martyrdom of John of Herakleia.", ar: "" } },
      { kind: 'reading', text: { en: "This day also, marks the martyrdom of St. John of Herakleia.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayer be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of St. Aba-Hour.", ar: "" } },
      { kind: 'reading', text: { en: "Today also, marks the departure of the Saint Aba-Hour in the mount of El-Amoud in the East.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayer be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of Pope Yoannis the Eighth (80th Patriarch).", ar: "" } },
      { kind: 'reading', text: { en: "On this day also, of the year 1036 A.M. (May 29th, 1320 A.D.) Pope Yoannis the Eighth (80th Patriarch), departed. He was from Meniat Bani-Khosaim, and was known as El Mo'ataman Ebn El-Kedees, and his name was Yohanna Ben-Ebsal. He became a monk in the monastery of El-Shahran, and was ordained Patriarch on the , 1016 A.M. (February 14th, 1300 A.D.).", ar: "" } },
      { kind: 'reading', text: { en: "During his days severe tribulations befell the Christians. They forced them to tinge their turbans with the color blue. Churches were closed in old Cairo, Cairo, and then in different parts of the country except the monasteries in Alexandria, and some churches in other cities. An envoy from the king of Spain came to intercede on behalf of the Christians. Two churches were opened, one of them was the Coptic church of the Virgin Lady in Haret Zeewailah and the other was the Malachite church of St. Nicholas in Elhamzawe. He was a contemporary of the Saint Anba Barsouma known as El-Erian Ebn-Eltaban, who departed during his days. The Patriarch prayed over him on the 1021 A.M.", ar: "" } },
      { kind: 'reading', text: { en: "This Patriarch was the last to reside in the church of in Cairo. He was the first to relocate the patriarchal chair to the church of the Virgin Lady in Haret Zeewailah. He was residing there in the year 1303 A.D. when a severe earthquake took place that destroyed a large part of Syria and Egypt. Ebn-kabre indicated that this Patriarch had made some changes in the Liturgy. He departed after remaining on the chair for twenty years, three months, and fifteen days and was buried in the monastery of El-Shahran.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us and Glory be to God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baouna-5",
    title: { en: "Baouna 5", ar: "5 بؤونه" },
    blocks: [
      { kind: 'heading', text: { en: "The Departure of St. James of the East.", ar: "استشهاد القديس يعقوب المشرقى" } },
      { kind: 'reading', text: { en: "On this day, St. James of the East (Oriental), the confessor, departed. He lived and worshipped in one of the monasteries of the East. He was a contemporary of the Great, , and Jovianus the Believer. When the latter was killed, Valens, his brother, reigned in his stead. He was an arian and he closed the Orthodox churches and allowed the Arians to open their churches. The grace of God moved this Saint and he went to the city of Constantinia. He met the Emperor on his way to war. He stood before the Emperor and said, \"I ask you to open the churches of the believers, that they may pray for you, so may God make you victorious against your enemies, otherwise God will forsake you and you will be defeated before your enemies.\" The Emperor became angry at what St. James said and commanded to beat and imprison him. The Saint told him; \"Know that you shall be defeated before your enemies, and you shall die by burning.\" The Emperor became enraged and ordered to keep him under guard until he should return from war. The Saint told him, \"If you return safely, then God has not spoken by my mouth.\"", ar: "في مثل هذا اليوم تنيح القديس يعقوب المشرقي المعترف . كان يتعبد في أحد ديارات المشرق وقد عاصر قسطينوس بن قسطنطين الكبير ويوليانس المعاند ويوبيانوس المؤمن الذي لما قتل تملك أخوه فالنز وكان أريوسي المذهب فأذن للاريوسيين بفتح كنائسهم وإغلاق كنائس الأرثوذكسيين فتحرك هذا القديس بالنعمة الإلهية وأتي إلى القسطنطينية فالتقي بالملك وهو خارج للحرب فوقف أمامه وقال له أنا أسألك أن تفتح كنائس المؤمنين للصلاة عنك لينصرك الله علي أعدائك وان لم تفعل ذلك فان الله سيتخلى عنك فتهزم أمام أعدائك فغضب الملك من ذلك وأمر بضربه وحبسه . فقال له القديس اعلم أنك ستهزم أمام أعدائك وتموت حرقا . فازداد الملك غضبا وأمر باعتقاله إلى أن يعود من الحرب فقال له القديس ان عدت سالما فلا يكون الرب قد تكلم علي فمي وسار الملك لمحاربة أعدائه ولما التقي الجيشان تخلي الرب عنه فانهزم أمام أعدائه وتتبعوه إلى أن دخل إحدى القرى فأشعلوا النيران حولها فهرب أهلها وبقي هو وبعض خاصته فأحرقوهم وعاد من بقي حيا من جنده إلى مدينة القسطنطينية وأخبروا المؤمنين بما حدث ز وبذلك تمت نبوة القديس فاجتمع المؤمنون وأخرجوه من السجن بإكرام جزيل وتحقق الأريوسيون بأن روح الله كانت عليه كما صدقوا صحة إيمانه فرجعوا عن ضلالهم معترفين بمساواة ابن الله مع أبيه في الجوهر وقضي هذا القديس بقية أيامه مجاهدا ناسكا حتى تنيح بسلام ." } },
      { kind: 'reading', text: { en: "The Emperor went on to fight his enemies. When the two armies faced each other, the Lord forsake him, so he was defeated before his enemies. They pursued him until he came to a certain village to which they set fire. Its people escaped, but he and some of his men remained and they were burned. Those of his soldiers who returned to the city of Constantinia told the believers what had happened. Thus the prophecy of the holy man was fulfilled. The believers assembled, and brought him out of prison with great honor. The Arians knew that the divine grace and the spirit of prophecy dwelt in him, as they believed in the accuracy of his faith. Many turned from their error, confessing that the Son of God is equal with the Father in essence.", ar: "صلاته تكون معنا . آمين" } },
      { kind: 'reading', text: { en: "This saint spent the rest of the days of his life in devotion to the ascetic life, and in fighting the spiritual fight until he departed in peace.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Martyrdom of Sts. Anba Bshay (Ebsoy) and Anba Botros (Peter).", ar: "استشهاد القديسين الأنبا بشاي والأنبا بطرس" } },
      { kind: 'reading', text: { en: "On this day also, the two great Sts. Anba Bshay (Ebsoy) and Anba Botros (Peter) were martyred. Their relics are located in Sedfah, the governorate of Asyut.", ar: "في مثل هذا اليوم استشهد القديسان العظيمان الأنبا بشاي والأنبا بطرس وأعضاؤهما موجودة بصدفا محافظة أسيوط . صلاته تكون معنا . آمين" } },
      { kind: 'reading', text: { en: "May their prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Commemoration of the Consecration of the church of St. Boctor (Victor) in the region of Sho.", ar: "تذكار تكريس كنيسة القديس بقطر بناحية شو" } },
      { kind: 'reading', text: { en: "This day also, marks the commemoration of the consecration of the church of the great in the region of Sho, east of El-Khesous.", ar: "في مثل هذا اليوم تذكار تكريس كنيسة القديس العظيم الأنبا بقطر بناحية شو شرق الخصوص مكان مولده ." } },
      { kind: 'reading', text: { en: "May his prayers be with us and Glory be to God forever. Amen.", ar: "صلاته تكون معنا . ولربنا المجد دائما . آمين" } }
    ],
  },
  {
    id: "synax-baouna-6",
    title: { en: "Baouna 6", ar: "6 بؤونه" },
    blocks: [
      { kind: 'heading', text: { en: "", ar: "استشهاد ثاؤذورس الراهب" } },
      { kind: 'reading', text: { en: "", ar: "في مثل هذا اليوم استشهد القديس ثاؤذورس الراهب . وقد ولد بمدينة الإسكندرية وترهب بأحد الأديرة القريبة منها فاشتهر بالسيرة الطاهرة والنسك الزائد ، ولما مال قسطنديوس ابن الملك البار قسطنطين الكبير إلى الأريوسين أرسل بطريركا أريوسيا إلى الإسكندرية يسمي جورجيوس مصحوبا بعدد من الجنود . فنفي القديس أثناسيوس بابا الإسكندرية وجلس مكانه بعد ان قتل كثيرين من المؤمنين فغار هذا القديس غيرة مسيحية وأخذ يجادل الأريوسين ويكشف ضلالهم . فقبض عليه البطريرك الدخيل وعذبه كثيرا ثم أمر بربطه في أرجل حصان جموح وإطلاقه في الميدان فتقطعت أعضاؤه وتهشم رأسه وأسلم روحه في يدي الرب ونال إكليل الشهادة ، فجمع المؤمنون أعضاءه المقدسة ووضعوها في تابوت ورتبوا له عيدا في مثل هذا اليوم ." } },
      { kind: 'reading', text: { en: "", ar: "صلاته تكون معنا. ولربنا المجد دائما . آمين" } },
      { kind: 'heading', text: { en: "", ar: "استشهاد أربعة أراخنة من أسنا" } },
      { kind: 'reading', text: { en: "", ar: "في مثل هذا اليوم استشهاد أربعة أراخنة من أسنا ( اوسافيوس وباخوش وهرواج وسامان ). صلاتهم تكون معنا و لربنا المجد دائما ابديا امين ." } },
      { kind: 'heading', text: { en: "The Departure of Pope Yoannis the Nineteenth, 113th Patriarch of Alexandria.", ar: "" } },
      { kind: 'reading', text: { en: "On this day, of the year 1658 A.M. (1942 A.D.) Pope Yoannis the Nineteenth, 113th Patriarch of Alexandria, departed. He was born in the village of Dair Tasa, Asyiut governorate in the year 1571 A.M. (1855 A.D.). His parents were righteous, therefore he was raised on piety and godliness. He drank the love of virtuous life and loved, since his young age, to read the biographies of saints. He longed to follow their example, accordingly he went to the monastery of the Virgin Lady known as El-Baramous in Wadi El-Natroun, in the month of Baramoudah, 1591 A.M. He became a monk on the third of Kiahk, 1592 A.M. (1876 A.D.). Because of his fervent worship, intelligence, and intellect, the fathers unanimously agreed to nominate him to be a priest. , ordained him a priest in the year 1593 A.M., then hegumen in Baramhat, 1594 A.M., and appointed him on the same day to be the head of the monastery. He remained the head of the monastery for ten years, during which he was an example of, ambition, honesty, purity of conduct, firmness, godliness, and good management.", ar: "" } },
      { kind: 'reading', text: { en: "When the Chair of the diocese of El-Biharah became vacant, the people chose Yoannis a metropolitan for that Chair. He was ordained on the , 1603 A.M. (1887 A.D.) and also was appointed as a deputy of the See of . After the departure of Anba Yoannis, metropolitan of El-Menofaya at that time, the people of the diocese nominated him to care for them. The diocese of El-Menofaya was added to his duties in the year 1610 A.M. (1894 A.D.), and he became the metropolitan of El-Biharah, El-Menofaya, and the deputy of the See of St. Mark.", ar: "" } },
      { kind: 'reading', text: { en: "Since his official seat was in Alexandria, he established there a theological school to educate the monks. He sent from its students a mission to Athens for higher theological studies.", ar: "" } },
      { kind: 'reading', text: { en: "The revenue of the church properties was inconsiderable. By his good judgement, the revenue increased year after year. Because of the highrise buildings that he built and the renovation of the old ones. He also gave great care for the Coptic schools, elementary and high, until their standard became equivalent to the best schools. He built and renovated most of the churches in his parish. He also gave special attention to the monasteries in his jurisdiction, which were improved greatly because of his good care and close supervision.", ar: "" } },
      { kind: 'reading', text: { en: "Because of his foresight, and prudence, the government chose him as a representative for the Copts in many councils and committees at the general assembly, the committee for formulating the constitution and many others.", ar: "" } },
      { kind: 'reading', text: { en: "He spent forty-two years as a metropolitan, which were full of splendid works. When the blessed Pope Kyrillos the fifth, departed, on the 1st day of Misra, 1643 A.M. (August 7th, 1927 A.D.) the Holy Synod convened on the fourth of Misra. They unanimously agreed to chose him Acting Pope to run the affairs of the church until ordaining a patriarch. As a result of that, the Holy Synod had received many nominations from the parishes approving that choice.", ar: "" } },
      { kind: 'reading', text: { en: "He performed his duties as Acting Patriarch for one year, four months, and ten days. During this period he administered the affairs of the See of St. Mark very well, during which also the Holy Synod, with Anba Yoannis presiding, issued a canon to regulate the affairs of the monasteries and the monks. He organized a committee to oversee the church properties and those of the monasteries and to review their accounts.", ar: "" } },
      { kind: 'reading', text: { en: "From what everyone knew of his purity, virtuous life, good character, asceticism, and piety, they all unanimously agreed to chose him a patriarch with nominations from the bishops, priests and lay leaders. He was enthroned a patriarch on Sunday the 1645 A.M. (December 16th, 1928 A.D.) in the great St. Mark cathedral in Cairo (Azbakiah). That took place with a great celebration attended by the representatives of the King, princes, ministers, important Egyptian personalities, the metropolitans of different denominations eastern and western, and ambassadors of foreign countries.", ar: "" } },
      { kind: 'reading', text: { en: "After his ordination, Pope Yoannis directed his attention to caring for the affairs of the Coptic People and the church. He established a higher theological institution for the education of the monks in the city of Helwan. He ordained for the kingdom of Ethiopia, a Coptic Metropolitan and four well-learned Ethiopian bishops. He travelled to Ethiopia to reaffirm the unity between the Coptic and Ethiopian churches. He stayed there for thirteen days where they received him with great honor and respect. In Addis Ababa, he ordained the head of the Ethiopian monks (the successor of St. Takla Haymanot) a bishop.", ar: "" } },
      { kind: 'reading', text: { en: "With the will of God, he made the Holy Oil (Myron) in the year 1648 A.M. (1930 A.D.). The last time the oil was made was one hundred and ten years earlier during the papacy of Pope Peter, 109th Pope of Alexandria. Pope Yoannis made the Holy Oil a second time, specially for the kingdom of Ethiopia, attended by Anba Kyrillos, metropolitan of Ethiopia, and Anba Peter, an Ethiopian bishop.", ar: "" } },
      { kind: 'reading', text: { en: "His contributions, too numerous to be mentioned completely, include watching over the welfare of the church, kindness to the needy, support for charitable organizations, moral and financial support for the Coptic teaching institutions, and assistance on valuable projects that financially and spiritually benefitted the Copts.", ar: "" } },
      { kind: 'reading', text: { en: "During Pope Yoannis' papacy, a war broke out between Ethiopia and Italy, during which most of the Ethiopian bishops died except Anba Abraam and another bishop. When Italy occupied Ethiopia, the Emperor departed from his country. Anba Kyrillos, the metropolitan of Ethiopia, was exiled to Egypt, for he refused to agree with Italy on separating the Ethiopian church from the Coptic Orthodox church. In November, 1937 A.D., the Italian governor of Ethiopia decided the independence of the Ethiopian church and its separation from the Alexandrian See. He appointed Anba Abraam, the Ethiopian bishop, a patriarch for Ethiopia. Nevertheless, God punished him for his betrayal. He became blind and died shortly after. The Alexandrian Holy Synod decided to excommunicate him, not recognizing him nor the bishops that he ordained. This situation in Ethiopia did not last long; during the Second World War the Emperor of Ethiopia regained his kingdom from Italy. Anba Kyrillos returned to his church with great honor, in May 1942 A.D.", ar: "" } },
      { kind: 'reading', text: { en: "When Pope Yoannis had realized the return of the Ethiopian church to its mother church, the Coptic Church, he was stricken with the ailments of old age. He departed in peace on Sunday 14th day of Baounah, 1658 A.M. (June 21st, 1942 A.D.).", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us. Amen", ar: "" } },
      { kind: 'heading', text: { en: "The Martyrdom of Sts. Apakir, John, Ptolemy and Philip.", ar: "" } },
      { kind: 'reading', text: { en: "On this day also, Sts. Apakir, John, Ptolemy and Philip, were martyred. St. Apakir was born in the city of Damanhur, and had a rich brother called Philip. They had agreed with two priests, one called John and the other called Ptolemy, to receive the crown of martyrdom. They went to the city of Kartsa (Kartes), and confessed the name of the Lord Christ before the Governor. The governor ordered to shoot them to death with arrows, but the arrows did not touch them. They were then cast into red hot fire, but the angel of the lord delivered them from it. Then the governor commanded to tie them to the tails of horses, and to drag them from Kartes to the city of Damanhur, but the Lord guarded them from any harm. The governor commanded that their heads be cut off outside the city of Damanhur. They received the crown of martyrdom. People from the city of Sa came and took the body of St. Apakir, built for him a church, and laid his body inside it. Many signs and wonders took place through him. The people of Damanhur came and took the bodies of John, Ptolemy, and Philip, wrapped them in expensive shrouds and buried them there.", ar: "" } },
      { kind: 'reading', text: { en: "May their prayers be with us and Glory be to God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baouna-7",
    title: { en: "Baouna 7", ar: "7 بؤونه" },
    blocks: [
      { kind: 'heading', text: { en: "The Martyrdom of St. Abaskhiroun the Soldier.", ar: "استشهاد القديس ابسخيرون الجندى القلينى" } },
      { kind: 'reading', text: { en: "On this day, the honorable St. Abaskhiroun, who was from the city of Qalin, was martyred. He was one of the soldiers of , governor of Ansena (Antinoe). When the Edict of Diocletian to worship the idols was issued, this Saint arose in the middle of the people present, exposed the infidelity of the Emperor, and cursed his idols. They seized him and shut him up in the prison, which was in the palace of the Governor, in Asyut. Five other soldiers agreed with him to shed their blood in the Name of Christ. Their names were: Alfius, Armanius, Arkias, Peter, and Cranius. When they came before the Governor, he cut off their girdles, tortured them, crucified some and cut off the heads of the others.", ar: "في مثل هذا اليوم استشهد القديس الجليل أبسخيرون الجندي الذي من قلين . وكانت من جند أريانا والي أنصنا . ولما صدرت أوامر دقلديانوس بعبادة الأوثان برز هذا القديس في وسط الجمع الحاضر مبينا ضلال الملك لاعنا أوثانه فقبضوا عليه وأودعوه السجن الذي كان في قصر الوالي بأسيوط فاتفق معه خمسة من الجنود ( ألفيوس وأرمانيوس وأركياس وبطرس وقيرايون ) علي أن يسفكوا دمهم علي اسم المسيح فلما مثلوا أمام الوالي أمر بتقطيع مناطقهم وتعذيبهم وصلب بعضهم وقطع رؤوس الآخرين ، وأما القديس أبسخيرون فقد عذبه الوالي بمختلف العذابات ولكن الرب كان يقويه ويصبره ويشفيه من جراحاته ، و استحضر ساحرا يسمي اسكندر ، ليقدم للقديس شيئا من السم القاتل ، قائلا يا رئيس الشياطين اظهر في هذا المسيحي قوتك ، فتناول القديس السم ورسم عليه علامة الصليب وشربه فلم ينله أي آذى , فتعجب الساحر وآمن بإله القديس أبسخيرون فقطع الوالي رأس الساحر ونال إكليل الشهادة . أما القديس فقد ازداد الوالي غضبا عليه وبعد أن عذبه كثيرا أمر بقطع رأسه أيضا فنال إكليل الشهادة" } },
      { kind: 'reading', text: { en: "As for St. Abaskhiroun, the Governor tortured him with different kinds of tortures, but the Lord comforted him, strengthened him, and healed his wounds. The Governor brought a sorcerer, whose name was Alexander. He gave the Saint some deadly poison, saying; \"O master of the powers of darkness, manifest in this Christian your powers.\" The Saint took the poison, made the sign of the cross over it, and drank it, but no harm came upon him. The sorcerer marvelled, and he believed in the God of St. Abaskhiroun. The Governor cut off the head of the sorcerer, and he received the crown of martyrdom. The Governor became more enraged with the Saint. He tortured him extensively, then he ordered to cut off his head, and he received the crown of martyrdom.", ar: "صلاته تكون معنا . ولربنا المجد دائما . آمين" } },
      { kind: 'reading', text: { en: "May his prayers be with us and Glory be to God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baouna-8",
    title: { en: "Baouna 8", ar: "8 بؤونه" },
    blocks: [
      { kind: 'heading', text: { en: "The Commemoration of the Consecration of the Church of the Virgin Lady known as El-Mahammah.", ar: "تذكار كنيسة السيدة العذراء بالمحمية" } },
      { kind: 'reading', text: { en: "On this day, of the year 901 A.M., is the commemoration of the consecration of the church of the Virgin Lady, the Mother of God. This church is in the city known as El-Mahammah (Mostorod) which means \"bath\" because of the fountain of water flowing from the spring. This spring the Mother of God had sprung out upon her return from her visit to the land of Egypt. When Joseph went to Egypt as the Angel had said, he went to Upper Egypt. On his way back, he came to El-Mataryah, and then to El-Mahammah. A church was built in that place in the name of the Virgin Lady.", ar: "في مثل هذا اليوم من سنة 901 ش تذكار تكريس كنيسة السيدة العذراء والدة الإله في البلدة المعروفة بالمحمة ( مسطرد ) حيث ينبوع الماء الفائض من العين التي استخدمتها والدة الإله عند عودتها من أرض مصر ، وذلك أنه لما ذهب يوسف إلى مصر كقول الملاك وصل إلى أوائل الصعيد وفي عودته وصل إلى المطرية ومنها إلى المحمة وقد بنيت في هذا المكان كنيسة علي اسم السيدة العذراء شفاعتها تكون معنا . آمين" } },
      { kind: 'reading', text: { en: "May her intercession be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Martyrdom of George (Girgis) the new martyr.", ar: "استشهاد القديس جرجس الجديد" } },
      { kind: 'reading', text: { en: "This day also marks the martyrdom of George (Girgis), the new martyr. He was an Ishmealite as was his father. He believed in the Lord Christ and became a monk. They seized, and punished him severely. They took him before the Governor El-Zaher, where he confessed his faith in the Lord Christ. The Governor attempted to make him forsake his faith by offering him expensive gifts, but he refused. The Governor ordered to cut his neck off, and he received the crown of martyrdom in the year 1103 A.M. (1387 A.D.).", ar: "في مثل هذا اليوم استشهد القديس جرجس الجديد الذي كان إسماعيليا تابعا لأبيه ، لكنه آمن بالسيد المسيح وانتظم في سلك الرهبنة فامسكوه وعاقبوه عقاباً شديدا وأوقفوه أمام الملك الظاهر فأعترف بالسيد المسيح فأراد أن يثنيه عن أيمانه بعطايا جزيلة ولكنه رفض فأمر بقطع عنقه ونال إكليل الشهادة سنة 1103 ش 1387 م . شفاعته تكون معنا . ولربنا المجد دائما . آمين" } },
      { kind: 'reading', text: { en: "May his intercession be with us and Glory be to God forever. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Commemoration of St. Tamada and her children, and Armenius and his mother.", ar: "تذكار القديسة تمادا وأولادها وأرمانوس وأمه" } },
      { kind: 'reading', text: { en: "On this day also, is the commemoration of St. Tamada and her children, and Armenius and his mother.", ar: "في مثل هذا اليوم تذكار القديسة تمادا وأولادها ارمانوس وأمه شفاعتهم تكون معنا . آمين" } },
      { kind: 'reading', text: { en: "May their intercession be with us. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baouna-9",
    title: { en: "Baouna 9", ar: "9 بؤونه" },
    blocks: [
      { kind: 'heading', text: { en: "", ar: "نقل اعضاء ابى سيفين" } },
      { kind: 'reading', text: { en: "", ar: "في مثل هذا اليوم نعيد بتذكار نقل أعضاء القديس مرقوريوس أبي السيفين إلى كنيسته في مصر . وذلك في عهد رئاسة البابا يوأنس الرابع والتسعين من باباوات الإسكندرية (ذكرت سيرته تحت اليوم الخامس والعشرون من شهر هاتور)" } },
      { kind: 'heading', text: { en: "", ar: "نياحة صموئيل النبى" } },
      { kind: 'reading', text: { en: "", ar: "في مثل هذا اليوم من سنة 2947 للعالم تنيح الصديق العظيم صموئيل النبي . وقد ولد هذا البار في رامتايم صوفيم من جيل أفرايم واسم أبيه ألقانا وأمه حنة . وكانت عاقرا ، وبمداومتها الطلبة رزقها الله صموئيل . فربته في بيتها ثلاث سنوات ثم قدمته إلى هيكل الله كما سبق أن نذرت قبل الحبل به . فخدم عالي الكاهن إلى أن كبر ، وكان ولدا عالي قد سلكا سلوكا رديا فدعا الرب صموئيل في إحدى الليالي هو نائم فظن أن عالي هو الذي يدعوه فذهب إليه وقال له هل دعوتني يا سيدي فأجابه لا ارجع أضطجع . فلما مضي دعاه الرب ثانية وثالثة وهو في كل مرة يقوم ويذهب إلى عالي . فعلم عالي أن الرب هو الذي يدعوه فقال له . ارجع اضطجع وإذا دعاك تقول تكلم يارب لأن عبدك سامع . ولما دعاه الرب وأجابه كما علمه عالي قال له الرب : &quot; هوذا أنا فاعل أمرا كل من سمع به تطن أذناه . في ذلك اليوم أقيم علي عالي كل ما تكلمت به علي بيته . ابتدئ وأكمل وقد أخبرته بأني أقضي علي بيته إلى الأبد من أجل الشر الذي يعلم أن بنيه قد أوجبوا به اللعنة علي أنفسهم ولم يردعهم . ولذلك أقسمت لبيت عالي أنه لا يكفر عن شر بيت عالي بذبيحة أو بتقدمه إلى الأبد &quot; (1 صم 3 : 1 – 14)" } },
      { kind: 'reading', text: { en: "", ar: "وبعد هذا أمر الرب أن يمسح شاول بن قيس ملكا علي إسرائيل . ولما خالف شاول أوامر الرب مسح صموئيل داود بن يسى ملكا بأمر الرب وتنبأ وحكم بني إسرائيل عشرين سنة ." } },
      { kind: 'reading', text: { en: "", ar: "صلاته تكون معنا . آمين" } },
      { kind: 'heading', text: { en: "", ar: "استشهاد القديس لوكيليانوس وأربعة آخرين معه" } },
      { kind: 'reading', text: { en: "", ar: "في مثل هذا اليوم استشهد القديس لوكيليانوس وأربعة آخرون معه . وكان كاهنا للأوثان في عهد الملك أوريليانوس قيصر . وأبصر تعذيب الشهداء بالضرب والحرق وتقطيع الأعضاء كما شاهد كثيرين يلقون في النار ولم تمسسهم بأذى فتعجب وتحقق أنه ليس لأوثانه قوة علي فعل مثل هذا وأن الإله الذي يفعل هذه الآيات هو الإله الحق . وللحال صرخ قائلا إني أؤمن بإله المسيحيين فوبخه علي ذلك ووعده ثم توعده : وإذ لم يرجع عن عزمه عذبه كثيرا ثم طرحه في السجن وعاد الملك فاستحضره مع أربعة من المسيحيين والقوهم في النار فأرسل الله مطرا غزيرا أطفأ النار . أخيرا علقوه علي خشبه وسمروا جسده بمسامير كبيرة فأسلم الروح في يد الرب . أما الأربعة الآخرون فقد قطعت رقابهم . ونال الجميع إكليل الشهادة ." } },
      { kind: 'reading', text: { en: "", ar: "صلاته تكون معنا . آمين" } },
      { kind: 'heading', text: { en: "The Martyrdom of St. Claudius.", ar: "" } },
      { kind: 'reading', text: { en: "On this day, the honorable St. Claudius, was martyred. He was the son of Ptolemy (Abtelmawos), who was Emperor Numerianus'\n(1) brother. He was loved by the people of Antioch for his courage and good appearance. Because they loved him so greatly, they painted a picture of him on the doors of the city of Antioch.", ar: "" } },
      { kind: 'reading', text: { en: "When Diocletian reneged the faith and incited the persecution against the Christians, this Saint agreed with to be martyred for the sake of the Name of Christ.", ar: "" } },
      { kind: 'reading', text: { en: "Satan appeared to them in the form of an old man and told them, \"O my sons, you are young men, the sons of nobility, and I am afraid for you from this infidel Emperor; so if he asked you to worship the idols, accept his command, and in your houses you can worship Christ in secret.\" They realized that he was satan disguised as an old man and told him, \"O you who are filled with all evil, go away from us.\" Straightway the old man changed his appearance and became like a black slave and told them, \"Behold, I will go before you to the Emperor and instigate him to shed your blood.\"", ar: "" } },
      { kind: 'reading', text: { en: "The Emperor brought St. Claudius and proposed to him the worship of the idols, and promised to give him his father's position. Claudius neither accepted his promise, nor submitted to his order. He spoke to him boldly and fearlessly reviling him for worshipping the idols. The Emperor did not dare to harm him for the people of Antioch loved him. Romanus, St. Victor's father, advised the Emperor to send him to Egypt to be killed there. He sent him with a letter to the Governor of Ansena (Antinoe) stating in it: \"Claudius neither obeyed our orders, nor hearkened our words. Persuade him with all your power first, and if he does not return on his counsel, cut off his head.\" When the Saint heard that, he called Sidrakhos, his sister's husband, asked him to care for his sister, his possessions and bid him farewell. The Saint went with the soldiers to Egypt. When he arrived to , the governor of Ansena, he received him standing, kissed his hand, and said, \"O my master Claudius, do not transgress the command of the Emperor.\" The Saint replied, \"I was not sent to you for you to lead me astray by your words, but that you might fulfil what the emperor commanded.\" They argued with each other till Arianus became enraged with the answers of the Saint, and he drove the spear into the Saint. He delivered up his pure spirit and received the crown of martyrdom. Some of the believers, took his body and shrouded it. They placed it with the body of St. Victor who was martyred shortly before that. After the end of the time of persecution, Victor's mother came, and took their bodies to Antioch.", ar: "" } },
      { kind: 'reading', text: { en: "May their prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Commemoration of the Consecration of the Altar of the Forty Martyrs in Alexandria.", ar: "" } },
      { kind: 'reading', text: { en: "On this day also, the church celebrates the commemoration of the consecration of the altar of the of Sebastia, in the church of the Savior, in Alexandria.", ar: "" } },
      { kind: 'reading', text: { en: "May their intercession be with us and Glory be to God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baouna-10",
    title: { en: "Baouna 10", ar: "10 بؤونه" },
    blocks: [
      { kind: 'heading', text: { en: "The Martyrdom of St. Dabamon.", ar: "استشهاد القديس دابامون والسياف" } },
      { kind: 'reading', text: { en: "On this day, St. Dabamon, was martyred. A man named was called upon to be a bishop, but he fled to \"kahmoun\" (Tahmoun), diocese of Bana. There, he found a lodging\nwith two brothers called Dabamon (Eudaeman) and Bastamon (Episteman). That night, the angel of the Lord appeared to him and said, \"Why are you asleep while the fight is on, and the crowns are prepared? Arise and go to the governor and confess Christ to receive the crown of martyrdom.\" When he rose up, he told the two brothers about his vision. They all agreed to receiving the crowns. They went to the governor and professed the Name of the Lord Christ before him. The Governor tortured them, and put them in prison. Then, he took them with him from Benchileel to Sanhour. He asked them to raise incense for the idols, but they refused. The Governor tortured them again and the Lord sent his angel to comfort them.", ar: "في مثل هذا اليوم استشهدت القديسة دابامون وأمها صوفيه ، وذلك أن أنسانا يدعي ورشنوفة قد طلب للأسقفية فهرب إلى طحمون من كرسي بنا ، فاستضافه أخوان يدعيان بصطامون ودابامون . وفي تلك الليلة ظهر له ملاك الرب قائلا لماذا أنت نائم والجهاد قائم والأكاليل معدة قم انطلق إلى الوالي واعترف بالمسيح لتنال إكليل الشهادة . ولما استيقظ قص الرؤيا علي الأخوين . فاتفقوا جميعا علي نوال الإكليل وذهبوا إلى الوالي واعترفوا أمامه باسم السيد المسيح . فعذبهم وألقاهم في السجن ثم أخذهم معه من بنشليل إلى سنهور وعرض عليهم التبخير للأوثان فأبوا ، فعذبهم وكان الرب يرسل ملاكه يعزيهم . ومن هناك توجه بهم إلى صا حيث أعلمه كهنة الأصنام عن امرأة بناحية دجوة تدعي دابامون تسب الآلهة وهذه كانت امرأة صالحة محسنة ولها ابنة تدعي يونا وكانتا تنسجان الأقمشة وترسمان عليها الرسوم الجميلة . وتتصدقان بما يفضل عنهما . فأرسل إليها الوالي سيافا يدعي أولوجي . وهذا إذا رأي منها حسن السيرة وجمال الطباع . أمتنع عن قتلها وأخذها معه إلى الوالي وهناك تقابلت بالقديس ورشنوفة ورفيقاه . فعذبها الوالي كثيرا وأمر بعصرها بالمعصرة وكان الرب يقويها ويعيدها صحيحة . وفي أثناء ذلك اعترف أولوجي – السياف الذي كان قد أحضرها – بالسيد المسيح فقطعوا رأسه ونال إكليل الشهادة . وقد أمر الوالي أن تقطع رقبتها خارج المدينة فخرجوا بها والنساء حولها باكيات أما هي فكانت فرحة مسرورة فقطعوا رأسها ونالت إكليل الشهادة" } },
      { kind: 'reading', text: { en: "Then he took them to Sa, where the priest of the idols told the governor that a woman named Dabamon from Degwah had cursed the gods. She was a righteous and charitable woman who had a daughter named Youna. They weaved fabrics and painted beautiful drawings on them. They sold it and gave whatever was left as alms. The governor sent an executioner named Eulogi. When he saw her righteousness and her good nature, he refrained from killing her, and took her with him to the governor. There she met St. Warshenoufa and his two companions. The governor tortured her excessively and ordered to squeeze her with the press. The Lord strengthened her and raised her whole again. Meanwhile, Eulogi, the executioner that brought her, professed the Lord Christ. He was beheaded, and received the crown of martyrdom. The governor also ordered Dabamon to be beheaded outside the city. They took her out, and the women were around her weeping, but she was rejoicing. They cut her head off and she received the crown of martyrdom.", ar: "صلاتها تكون معنا . آمين" } },
      { kind: 'reading', text: { en: "May her prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "", ar: "استشهاد القديسة الأم دولاجى ومن معها" } },
      { kind: 'reading', text: { en: "", ar: "في مثل هذا اليوم استشهاد القديسة الأم دولاجى ومن معها ( بسطامون ، أرطامون و صوفيا أمهم ) بالقرن الثالث الميلادى. صلاته تكون معنا و لربنا المجد دائما ابديا امين ." } },
      { kind: 'heading', text: { en: "The Commemoration of the Closing of the Pagan Temples and Opening of the Churches.", ar: "تذكار إغلاق هياكل الأوثان وفتح الكنائس" } },
      { kind: 'reading', text: { en: "On this day also, of the year 312 A.D., the righteous the great, issued his Edict to close all the pagan temples, and open all the churches throughout the whole Roman Empire. The news of the Edict arrived to Alexandria on this day, and all the people rejoiced exceedingly along with the heavenly hosts. All the Christians made this day a great feast day. This was at the beginning of the enthronement of Pope Alexandros the first, the 19th Patriarch of Alexandria.", ar: "في مثل هذا اليوم من سنة 312 م صدرت أوامر الملك البار قسطنطين الكبير إلى جميع البلاد الخاضعة لسلطانه بإغلاق هياكل الأوثان وفتح الكنائس . وكان وصول تلك الأوامر إلى مدينة الإسكندرية في مثل هذا اليوم ، فشمل الفرح المسكونة كلها واشترك السمائيون مع الأرضيين في ذلك الفرح العظيم . وقد جعل المسيحيون من هذا اليوم عيدا عظيما . وكان ذلك في أوائل بطريركية الأنبا الكسندروس الأول بابا الإسكندرية التاسع عشر." } },
      { kind: 'reading', text: { en: "May his prayers be with us. Amen.", ar: "صلاته تكون معنا . آمين" } },
      { kind: 'heading', text: { en: "The Departure of St. Yoannis the 16th, the 103rd Pope of Alexandria.", ar: "نياحة القديس البابا يوأنس أل 103 من باباوات الإسكندرية" } },
      { kind: 'reading', text: { en: "Today also, of the year 1434 A.M. (June 15, 1718 A.D.), Pope Yoannis the Sixteenth, the 103rd Patriarch of Alexandria, departed. This Pope was known by the name \"Yoannis El-Tokhi\". His parents were Christians from Tokh El-Nasara, the diocese of El-Menoufia. They brought their son, whose name was Ibrahim, with the best of care. They provided him with the best of education. God blessed him from his youth, thus he grew up in virtue and in a chaste life.", ar: "في مثل هذا اليوم من سنة 1434 للشهداء الأبرار ( 15 يونية سنة 1718 م ) تنيح البابا يوأنس السادس عشر البطريرك الثالث بعد المائة . وبعرف هذا البابا باسم يوأنس الطوخي وكان والداه مسيحيين من طوخ النصارى بكرسي المنوفية ، فربيا نجلهما وكان يدعي ابراهيم أحسن تربية وزوداه بكل معرفة وأدب وعلماه أحسن تعليم وكانت نعمة الله حالة عليه منذ صباه فنشأ وترعرع في الفضيلة والحياة الطاهرة . ولما تنيح والده زهد العالم واشتاق لحياة الرهبنة فمضي إلى دير القديس أنطونيوس ببرية العربة وترهب فيه ولبس الزي الرهباني واتشح بالاسكيم المقدس . فلما تفاضل في العبادة والنسك اختاره الآباء الرهبان فرسمه البابا متاوس الرابع بكنيسة السيدة العذراء بحارة زويله قسا علي الدير المذكور فازداد في رتبته الجديدة فضلا وزهدا حتى شاع ذكر ورعه واتضاعه ودعته . ولما تنيح البابا البطريرك مناوش وخلا الكرسي بعده اجتمع الأباء الأساقفة والكهنة والأراخنه لاختيار الراعي الصالح فأنتخبوا عددا من الكهنة والرهبان وكان هذا الأب من جملتهم وعملوا قرعة هيكلية بعد أن أقاموا القداسات ثلاثة أيام وهم يطلبون من الله سبحانه وتعالي أن يرشدهم إلى من يصلح لرعاية شعبه ولما سحب اسم هذا الأب في القرعة علموا وتحققوا أن الله هو الذي اختاره إليه هذه الرتبة . وتمت رسامته في يوم الأحد المبارك الموافق 9 برمهات سنة 1392 ش ( 5 مايو سنة 1676 م ) ودعي يوأنس السادس عشر ، وكان الاحتفال برسامته فخما عظيما عم فيه الفرح جميع الأقطار المصرية ." } },
      { kind: 'reading', text: { en: "When his father departed, he forsake the world and desired the monastic life. He went to the monastery of St. Antony in the wilderness of Araba, and became a monk there. He put on the garb of the monk and attired with the holy Eskeem. When he showed his dedication in worship and asceticism, the fathers the monks chose him to be a priest. Pope Mattheos, the Fourth, ordained him a priest for the monastery, in the church of the Virgin Lady in Haret Zeewailah. He became more righteous in his new priestly rank, and increased his worship, until his godliness, humility and meekness became well known.", ar: "وقد اهتم بتعمير الأديرة والكنائس فقد قام بتعمير المحلات الكائنة بالقدس الشريف وسدد ما كان عليها من الديون الكثيرة وجدد مباني الكنائس والأديرة وكرسها بيده المباركة ، وأهتم خصيصا بدير القديس أنبا بولا أول السواح وكان خربا مدة تزيد علي المائة سنة فجدده وفتحه وعمره وأعاده إلى أحسن مما كان عليه وجهز له أواني وكتبا وستورا وذخائر ومضي اليه بنفسه وكرسه بيده المقدسة ورسم له قسوسا وشمامسة ورهبانا في يوم الأحد 19 بشنس سنة 1421 ش ( 25 مايو سنة 1705 م ) . وقد زار دير القديس العظيم أنطونيوس أب الرهبان المعروف بالعرب بجبل القلزم أربع دفعات الأولي في شهر كيهك سنة 1395 ش ( 1678 م ) وكان بصحبته رئيس الدير وكاتب القلاية السابق وبعض الرهبان ، والثانية في 20 برمودة سنة 1411 ش ( 1695 م ) في ختام الصوم المقدس وكان معه القس يوحنا البتول خادم بيعة كنيسة العذراء بحارة الروم والشماس المكرم والأرخن المبجل المعلم جرجس الطوخي أبو منصور والمعلم سليمان الصراف الشنراوي ، والثالثة في مسرى سنة 1417 ش ( 1701م ) ، والرابعة في سنة 1421 ش ( 1705 م ) لتكريس دير القديس أنبا بولا." } },
      { kind: 'reading', text: { en: "When Pope Mattheos departed, the bishops, priests and lay leaders, met to choose a good shepherd. They elected a number of priests and monks, among whom was this father. They casted an altar lot after they had celebrated the holy liturgy for three consecutive days, asking God to guide them to the one who is fit to shepherd His people. When the lot was made, it fell on this father. They knew and realized that God had chosen him for this office. He was ordained on Sunday, , 1392 A.M. (May 5th, 1676 A.D.). He was called Yoannis the 16th. The celebration of his enthronement was splendid and the joy prevailed everywhere in Egypt.", ar: "وفي شهر أبيب المبارك سنة 1417 ش وقع اضطهاد علي الشعب الأرثوذكسي بمصر المحروسة في زمن الوالي محمد باشا بسبب وشاية وصلته بأن طائفة النصارى الأقباط أحدثوا مباني جديدة في كنائسهم فعين علي الكنائس أغا من قبله ورجال المعمار وقضاة الشرع للقيام بالكشف علي الكنائس فنزلوا وكشفوا وأثبتوا أن في الكنائس بناء جديدا ولكن عناية الله تعالي لم تتخل عن شعبه بصلوات البابا الطاهر فحنن علي أمته القبطية قلوب جماعة من أمراء مصر وأكابر الدولة وتشفعوا عند الوالي فقرر عليهم غرامة فاجتمع البابا بالسادة الأراخنه المعلم يوحنا أبو مصري والمعلم جرجس أبو منصور والمعلم إبراهيم أبو عوض واتفق الرأي بينهم علي أن يطوف البابا المكرم حارات النصارى ويزور البيوت ويحصل منها ما يمكن تحصيل هذه الغرامة قام السادة الأراخنه بتسديدها لأربابها وحصل فرح عظيم في البيعة المقدسة وفتحت الكنائس ورفرف الهدوء السلام في سائر البيع الطاهرة ولكن البابا تأثر من طوافه علي المنازل فتوجه إلى دير القديس أنطونيوس في 7 مسرى سنة 1417 ش للترويح عن نفسه ." } },
      { kind: 'reading', text: { en: "He gave his attention to the restoration of the monasteries and the churches. He restored the holy places in Jerusalem and paid off its debts. He renovated many churches and monasteries which he consecrated by his blessed hands. He gave special attention to the monastery of St. Paul, the first hermit, in mount Nemra. The monastery was desolate for a period of more than one hundred years. He opened it, restored it, reestablished the monastic life in it, and made it better than before. He prepared books, veils, altar accessories, and relics of saints for it, and consecrated it himself. He ordained many priests, deacons and monks for it on Sunday the , 1421 A.M. (May 25, 1705 A.D.).", ar: "وفي سنة 1419 ش اشتاق البابا أن يعمل الميرون المقدس فأجاب الرب طلبته وحرك أنسانا مسيحيا هو الأرخن الكبير المعلم جرجس أبو منصور ناظر كنيستي المعلقة وحارة الروم وكان محبا للفقراء والمساكين ، مهتما بمواضع الشهداء والقديسين ، وكان مشتركا مع البابا في كل عمل صالح فجهز مع قداسة البابا ما يحتاج إليه عمل الميرون وتم طبخه وكرسه البابا بيده الكريمة في بيعة السيدة العذراء بحارة الروم واشترك في هذا الاحتفال العظيم الأباء الأساقفة والرهبان والشيوخ لأن الميرون لم يكن قد طبخ منذ مائتين وسبع وأربعين سنة تولي فيها الكرسي ثمانية عشر بطريركا . وهو أول من قام ببناء القلاية البطريركية بحارة الروم وخصص لها إيرادات وأوقافا ." } },
      { kind: 'reading', text: { en: "He visited the monastery of the great St. Antony, the father of the monks, in mount El-Kalzam, four times: the first was in the month of Kiahk, 1395 A.M. (1678 A.D.), accompanied by the head of the monastery, and some monks. The second was in the , 1411 A.M. (1695 A.D.) at the end of the holy fast. He was accompanied by Fr. John the Virgin, the priest of the church of the Virgin in Haret El-Room and the honorable deacon El-Moallem Girgis El-Toukhy Abu Mansour, and El-Moallem Soliman El-Sarraf El-Shenrawi. The third time was in Misra 1417 A.M. (1701 A.D.), and the fourth time was in 1421 A.M. (1705 A.D.) to consecrate the monastery of St. Paul.", ar: "وفي سنة 1425 ش ( سنة 1709 م ) قام هذا البابا بزيارة القدس الشريف ومعه بعض الأساقفة وكثير من القمامصة والقسوس والأراخنه عن طريق البر السلطاني وقد قام بنفقة هذه الزيارة المقدسة الشماس المكرم والأرخن المبجل الشيخ المكين المعلم جرجس أبو منصور الطوخي بعد أن تكفل بنفقة ترميم وصيانة بيعة السيدة العذراء الشهيرة بالمعلقة بمصر." } },
      { kind: 'reading', text: { en: "In the blessed month of Abib, 1417 A.M., a great tribulation befell the Orthodox Christians of Egypt, during the reign of the governor Mohammed Pasha. An accusation had reached him that the Coptic Christians had built new buildings in their churches. The Governor appointed an Agha, architects, and judges to go and investigate the accusation. They came back with the evidence that there were many new constructions in the churches. However, God did not forsake His people by the prayers of this godly Pope. Many honorable people in Egypt went to the Governor to intercede on behalf of the Christians. The Governor ordered that a fine be paid as a penalty. The Pope met with the lay leaders El-Moallem Youhanna Abu Masri, El-Moallem Girgis Abu Mansour, and El-Moallem Ibrahim Abu Awad. They agreed unanimously that the Pope would visit the Christians in their homes, and collect what needed to be collected. The penalty was collected and paid to the Governor. The lay leaders were able to pay it back to the people and every one rejoiced. The churches were opened, and there was peace. The Pope took it hard going to the homes of the believers asking for money, so he went to the monastery of St. Antony on the 7th of the month of Misra, 1417 A.M. for a retreat.", ar: "وكان البابا يفتقد الكنائس ويزور الديارات والبيع كما زار بيعة مار مرقس الإنجيلي بالإسكندرية وطاف الوجهين البحري والقبلي وأديرتهما وكنائسهما وكان يهتم بأحوالهما ويشجعهما ورتب في مدة رئاسته الذخيرة المقدسة في الكنيسة وهي جسد المسيح ودمه لأجل المرضي والمطروحين الذين لا يقدرون علي الحضور إلى الكنائس ." } },
      { kind: 'reading', text: { en: "In 1419 A.M., the Pope desired to make the Holy Oil (Myron). The Lord answered his request, and moved the heart of a Christian, the great lay leader, El-Moallem Girgis Abu Mansour, the administrator of the churches of El-Muallakah and Haret El-Roum. He was charitable to the poor and the needy, cared for the places of the saints and martyrs. He participated in every good deed with the Pope. He prepared what was needed (oil, spices, perfumes), and the Holy Myron was cooked and consecrated by the Pope in the Church of the Virgin in Haret El-Roum. The Myron had not been made for a period of two hundred and forty seven years, during which, 18 Popes sat on the throne of . He was also the first to build the Patriarchate residence in Haret El-Roum, and dedicated properties and revenue for it.", ar: "وكان البابا محبوبا من جميع الناس وكانت الطوائف تأتي اليه وتتبارك منه كما كان موضع تكريمهم واحترامهم لأنه كان متواضعا وديعا محبا رحوما علي المساكين وكان بابه مفتوحا للزائرين وملجأ للقاصدين والمترددين وكانت جميع أيام رئاسته هادئة وكان الله معه فخلصه من جميع أحزانه وأجاب طلباته وقبل دعواته وعاش في شيخوخة صالحة مرضية ." } },
      { kind: 'reading', text: { en: "In 1425 A.M. (1709 A.D.), this Pope visited Jerusalem, with some of the bishops, many archpriests, priests, and laymen. The honored deacon El-Moallem Girgis Abu Mansour El-Toukhy, paid all the expenses of this trip. He also paid all the expenses for the renovation of the church of the Virgin known as El-Muallakah in Old Cairo.", ar: "ولما اكمل سعيه مرض قليلا وتنيح بسلام هو وحبيبه الأرخن الكريم جرجس أبو منصور في أسبوع واحد فحزن عليه الجميع وحضر جماعة الأساقفة والكهنة والأراخنه وحملوا جسده بكرامة عظيمة وصلوا عليه ودفنوه في مقبرة البطاركة بكنيسة مرقوريوس أبي سيفين بمصر القديمة في 10 بؤونه سنة 1434 ش بعد أن جلس علي الكرسي أثنين وأربعين سنة وثلاثة أشهر" } },
      { kind: 'reading', text: { en: "The Pope visited the churches, and monasteries. He also visited St. Mark church in Alexandria. He traveled everywhere in both Lower and Upper Egypt. In his time, he allowed the Holy Elements (the Body and the Blood of Christ) to be taken to the sick and those who could not come to the church.", ar: "صلاته تكون معنا . آمين" } },
      { kind: 'reading', text: { en: "This Pope was loved by everyone, and he was honored and respected for his humility, meekness, and his love for the poor. His door was always open to everyone who would call upon him. The days of his papacy were quiet. The Lord was with him, and delivered him from all his sorrows. He accepted his prayers and supplications and he lived to a good old age.", ar: "" } },
      { kind: 'reading', text: { en: "When he completed his course, he became sick for a short time. Then he departed in peace, with his friend the honorable lay leader Girgis Abu Mansour within one week. Many mourned him, and the bishops, the priests, and the lay leaders attended the prayers on his body. They carried him with great honor, and placed the body in the tomb of the Patriarchs in the church of in Old Cairo, in the 10th of Baounah, 1434 A.M., after he had been on the throne of St. Mark for forty two years and three months.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Enthronement of Pope Demitrius the Second, the 111th Patriarch of Alexandria.", ar: "جلوس البابا ديمتريوس الثاني البطريرك ال 111" } },
      { kind: 'reading', text: { en: "On this day also, of the year 1578 A.M. (15th of June, 1862 A.D.), is the commemoration of the enthronement of Pope Demitrius the second, the 111th Patriarch.", ar: "في مثل هذا اليوم من سنة 1578 ش ( 15 يونيو سنة 1862 م ) تذكار جلوس البابا ديمتريوس الثاني البطريرك ال 111 علي كرسي الكرازة المرقسية . ولد هذا الأب ببلدة جلدة محافظة المنيا وترهب بدير القديس مقاريوس ولما تنيح رئيس الدير اختاروه للرئاسة فأحسن الإدارة . ونظرا لما اتصف به من حسن الصفات رسموه بطريركا خلفا للبابا العظيم الأنبا كيرلس الرابع البطريرك ال 110 وقد أكمل بناء الكنيسة المرقسية الكبرى كما شيد جملة مبان في البطريركية وفي ديره بناحي اتريس . وفي سنة 1869 م حضر الاحتفال بفتح قناة السويس وقابل أعظم الملوك ونال حسن الالتفات من السلطان عبد العزيز ، انه عندما تقدم منه هذا البابا للسلام عليه ، قبله علي صدره ففزع السلطان من ذلك . فوثب الحجاب عليه ثم سألوه قائلين : لماذا فعلت هكذا ؟ فقال : ان كتاب الله يقول : قلب الملك في يد الرب (ام 21 : 1) . فأنا بتقبيلي هذا قد قبلت يد الله . فسر السلطان من حسن جواب البابا وأنعم عليه بكثير من الأراضي الزراعية لمساعدة الفقراء والمدارس وقد طاف البطريرك في باخرة حكومية متفقدا كنائس الوجه القبلي فرد الضالين وثبت المؤمنين وبعد ان أكمل في الرئاسة سبع سنين وسبعة أشهر وسبعة أيام تنيح بسلام ليلة عيد الغطاس 11 طوبة سنة 1586 ش ( 18 يناير سنة 1870 م )" } },
      { kind: 'reading', text: { en: "This father was born in the village of Galda, the governorate of El-Menia. He became a monk in the monastery of St. Macarius. When the abbot of the monastery departed, he was chosen to become the new abbot. He did well in managing the monastery. For his good virtues, he was ordained a Pope to succeed the great .", ar: "صلاته تكون معنا . ولربنا المجد دائما . آمين" } },
      { kind: 'reading', text: { en: "He completed the construction of St. Mark Cathedral, built many buildings in the patriarchate, and in his monastery in the area of Atrees. In 1869 A.D., he attended the celebration for the opening of the Suez Canal, and met many kings. He was well respected by Sultan Abdel-Aziz. When this Pope came before him to greet him, the Pope kissed the sultan on his chest. The Sultan was troubled, and the guards asked the Pope why he did that. The Pope said, \"The book of God says: 'The king's heart in the hand of the Lord' (Proverbs 21:1), when I kissed his heart, I have kissed the hand of God.\" The Sultan was pleased with his answer, and gave him many farm lands to help the poor and the schools. The Pope traveled on a governmental boat to visit the churches in Upper Egypt. He regained those who were lost and strengthened the faithful.", ar: "" } },
      { kind: 'reading', text: { en: "After he had completed in the papacy seven years, seven months, and seven days, he departed in peace on the eve of , 1586 A.M. (Jan. 18th, 1870 A.D.).", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us and Glory be to God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baouna-11",
    title: { en: "Baouna 11", ar: "11 بؤونه" },
    blocks: [
      { kind: 'heading', text: { en: "The Martyrdom of St. Claudius.", ar: "استشهاد القديس اقلاديوس" } },
      { kind: 'reading', text: { en: "On this day, the honorable St. Claudius, was martyred. He was the son of Ptolemy (Abtelmawos), who was Emperor Numerianus'\n(1) brother. He was loved by the people of Antioch for his courage and good appearance. Because they loved him so greatly, they painted a picture of him on the doors of the city of Antioch.", ar: "في مثل هذا اليوم استشهد القديس الجليل أقلوديوس بن أبطلماوس أخي الملك نوماريوس (ابن ذوماريوس هو الشهيد يسطس ، وقد وردت سيرته تحت اليوم العاشر من شهر أمشير )." } },
      { kind: 'reading', text: { en: "When Diocletian reneged the faith and incited the persecution against the Christians, this Saint agreed with to be martyred for the sake of the Name of Christ.", ar: "كان محبوبا من جميع أهل إنطاكية لحسن صورته وشجاعته ولمحبتهم له عملوا له صورة وعلقوها علي باب مدينة إنطاكية ولما كفر دقلديانوس وأثار الاضطهاد علي المسيحيين اتفق هذا القديس مع القديس بقطر بن رومانوس علي الاستشهاد من أجل اسم المسيح فظهر لهما الشيطان في شبه شيخ وقال لهما : يا ولدي أنتما في سن الشباب بعد ، ومن أولاده الأكابر وأخاف عليكما من هذا الملك الكافر . فان قال لكما اسجدا للأوثان فوافقاه . وفي منزلكما يمكنكما أن تعبدا المسيح خفية . ففطن الاثنان إلى أنه شيطان في زي شيخ وقالا له يا ممتلئا من كل شر اذهب عنا . وللوقت تبدل شخصه وصار كعبد أسود وقال لهما : هوذا أنا أسبقكما إلى الملك وأحرضه علي سفك دمكما ." } },
      { kind: 'reading', text: { en: "Satan appeared to them in the form of an old man and told them, \"O my sons, you are young men, the sons of nobility, and I am afraid for you from this infidel Emperor; so if he asked you to worship the idols, accept his command, and in your houses you can worship Christ in secret.\" They realized that he was satan disguised as an old man and told him, \"O you who are filled with all evil, go away from us.\" Straightway the old man changed his appearance and became like a black slave and told them, \"Behold, I will go before you to the Emperor and instigate him to shed your blood.\"", ar: "واستحضر الملك القديس أقلوديوس وعرض عليه عبادة الأوثان ووعده أن يجعله مكان أبيه . فلم يلتفت إلى وعوده وخاطبه بكل جرأة موبخا إياه علي عبادته الأوثان فلم يجسر الملك علي أن يمسه بأذى لمحبة الانطاكيين له فأشار عليه رومانس الوزير والد القديس بقطر بإرساله إلى مصر ليقتل هناك فأرسله مصحوبا بكتاب إلى والي أنصنا يقول له فيه ان أقلوديوس لم يخضع لآمرنا ولا أذعن لقولنا فلاطفه بكل جهدك أولا فان لم يرجع عن رأيه فاقطع رأسه ." } },
      { kind: 'reading', text: { en: "The Emperor brought St. Claudius and proposed to him the worship of the idols, and promised to give him his father's position. Claudius neither accepted his promise, nor submitted to his order. He spoke to him boldly and fearlessly reviling him for worshipping the idols. The Emperor did not dare to harm him for the people of Antioch loved him. Romanus, St. Victor's father, advised the Emperor to send him to Egypt to be killed there. He sent him with a letter to the Governor of Ansena (Antinoe) stating in it: \"Claudius neither obeyed our orders, nor hearkened our words. Persuade him with all your power first, and if he does not return on his counsel, cut off his head.\" When the Saint heard that, he called Sidrakhos, his sister's husband, asked him to care for his sister, his possessions and bid him farewell. The Saint went with the soldiers to Egypt. When he arrived to , the governor of Ansena, he received him standing, kissed his hand, and said, \"O my master Claudius, do not transgress the command of the Emperor.\" The Saint replied, \"I was not sent to you for you to lead me astray by your words, but that you might fulfil what the emperor commanded.\" They argued with each other till Arianus became enraged with the answers of the Saint, and he drove the spear into the Saint. He delivered up his pure spirit and received the crown of martyrdom. Some of the believers, took his body and shrouded it. They placed it with the body of St. Victor who was martyred shortly before that. After the end of the time of persecution, Victor's mother came, and took their bodies to Antioch.", ar: "فلما علم القديس بذلك استدعي صدريخس زوج أخته وأوصاه علي ماله ثم ودعه ومضي مع الجند إلى مصر . ولما وصل إلى أريانا والي أنصنا استقبله واقفا وقبل يديه قائلا : يا سيدي أقلوديوس لا تخالف أمر الملك فأجابه القديس لم أرسل إليك لتطغيني بكلامك ، بل لتتم ما أمرك به الملك . وظل الاثنان بين أخذ ورد إلى أن اغتاظ أريانا من أجوبة القديس وطعنه بحربه فاسلم الروح ونال إكليل الشهادة . وأتي قوم من المؤمنين وأخذوا جسده وكفنوه ووضعوه مع جسد القديس بقطر الذي كان قد استشهد قبل ذلك بقليل حتى انقضي الاضطهاد فأتت أم بقطر وأخذتهما إلى إنطاكية ." } },
      { kind: 'reading', text: { en: "May their prayers be with us. Amen.", ar: "صلاتهما تكون معنا . آمين" } },
      { kind: 'heading', text: { en: "", ar: "نوة النقطة : شرقية ساخنة يومين" } },
      { kind: 'reading', text: { en: "", ar: "في اشهر الشتاء تتعرض الأجزاء المطلة علي البحر المتوسط لظاهرة تولد الانخفاضات الجوية الإعصارية التي تميز الأحوال المناخية في إقليم البحر المتوسط وتعرف في الإسكندرية باسم النوات." } },
      { kind: 'reading', text: { en: "", ar: "هي اضطرابات جوية تنشأ عنها دوامة هوائية دائرية أو بيضاوية ذات ضغط منخفض وسط مساحة ضغطها مرتفع وتندفع فيها الرياح علي شكل حلزوني نحو مركز منخفض بحيث يكون سيرها ضد اتجاه عقارب الساعة، وقد ينتج عنها ما يسمى بالعواصف أو الأعاصير." } },
      { kind: 'reading', text: { en: "", ar: "العواصف والأعاصير:" } },
      { kind: 'reading', text: { en: "", ar: "وهي تتكون عند التقاء الكتل الهوائية الباردة بمثيلتها الدافئة، ويؤدي الصراع بينهما إلي التفاف الهواء البارد حول الدافئ مكوناً الانخفاض الجوي وتندفع الرياح في حركتها من الغرب إلي الشرق بسرعة من 45 - 60 كم / س. ويصاحب ذلك عدم استقرار في الأحوال المناخية وازدياد سرعة الرياح وغزارة الأمطار وهبوط شديد في درجات الحرارة، وفي الأحوال الشديدة تؤدي إلي اقتلاع الأشجار من جذورها، أو تغطي مياه البحر أجزاء ساحلية من اليابس. وتعرف العواصف المدارية في منطقة بحر العرب باسم الأعاصير، وباسم التيفون في بحر الصين، وباسم الهاريكين في منطقة البحر الكاريبي، والترنادو في أواسط الولايات المتحدة، والولي ولي في شرق استراليا." } },
      { kind: 'reading', text: { en: "", ar: "نوة النقطة :" } },
      { kind: 'reading', text: { en: "", ar: "أي زيادة النيل وكان المصريين القدماء يعتقدون أن زيادة النيل تبتدئ في الليلة الثانية عشرة من شهر بؤونة ( نزول النقطة ) بسبب دمعة إيزيس آلهة الخصب والنماء وهي الدمعة التي أراقتها حزنا علي زوجها &quot; اوزيريس اله الخير الذي قتله &quot; تيفون &quot; اله الشر" } },
      { kind: 'heading', text: { en: "The Commemoration of the Consecration of the Altar of the Forty Martyrs in Alexandria.", ar: "تذكار تشييد هيكل الأربعين شهيدا بكنيسة المخلص" } },
      { kind: 'reading', text: { en: "On this day also, the church celebrates the commemoration of the consecration of the altar of the of Sebastia, in the church of the Savior, in Alexandria.", ar: "في هذا اليوم تعيد الكنيسة بتذكار تكريس هيكل الأربعين شهيدا بكنيسة المخلص بثغر الإسكندرية شفاعتهم تكون معنا . ولربنا المجد دائما . آمين" } },
      { kind: 'reading', text: { en: "May their intercession be with us and Glory be to God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baouna-12",
    title: { en: "Baouna 12", ar: "12 بؤونه" },
    blocks: [
      { kind: 'heading', text: { en: "The Commemoration of Archangel Michael.", ar: "عيد رئيس الملائكة الجليل ميخائيل" } },
      { kind: 'reading', text: { en: "On this day, the church celebrates of the honorable . The one who appeared to , encouraged him, and told him, \"Nay, but as captain of the hosts of the Lord am I now come.\" He made the city of Jericho to fall into his hands, and he stopped the sun for him.", ar: "فى مثل هذا اليوم تحتفل الكنيسة بتذكار رئيس جند السماء الملاك الجليل ميخائيل الشفيع في جنس البشر الذي ظهر ليشوع بن نون وقال له &quot; أنا رئيس جند الله &quot; . وعضده وحطم العمالقة وأسقط مدينة أريحا في يده وأوقف له الشمس. شفاعته تكون معنا . أمين" } },
      { kind: 'reading', text: { en: "May his intercession be with us. Amen.", ar: "كان الوثنيون بالإسكندرية يعبدون الصنم زحل صاحب التمثال الذي بنته كليوباترا في اليوم الثاني عشر من شهر بؤونه ، وفي أيام الملك قسطنطين أخذ البابا الكسندروس في وعظ الجميع مظهرا لهم خطأ عبادة الأوثان التي لا تعقل ولا تتحرك وخطأ تقديم الذبائح لها . ثم حول هيكل هذا الصنم إلى كنيسة باسم الملاك ميخائيل بعد أن حطم التمثال وطلب منهم أن يذبحوا الذبائح لله الحي ويوزعوها علي الفقراء الذين دعاهم أخوته حتى يكسبوا بذلك شفاعة الملاك ميخائيل . وكانت هذه الكنيسة تسمي وقتئذ بكنيسة القيسارية (عن مخطوط بشبين الكوم) ." } },
      { kind: 'reading', text: { en: "", ar: "وقد قيل ان هذا العيد أيضا أخذ عن المصريين القدماء الذين كانوا يعتقدون أن زيادة النيل تبتدئ في الليلة الثانية عشرة من شهر بؤونة ( نزول النقطة ) أي دمعة إيزيس آلهة الخصب والنماء وهي الدمعة التي أراقتها حزنا علي زوجها &quot; اوزيريس اله الخير الذي قتله &quot; تيفون &quot; اله الشر" } },
      { kind: 'reading', text: { en: "", ar: "وقد استبدل هذا العيد في المسيحية بعيد رئيس الملائكة ميخائيل (تاريخ الأمة القبطية )" } },
      { kind: 'reading', text: { en: "", ar: "شفاعته تكون معنا . ولربنا المجد دائما . آمين" } },
      { kind: 'heading', text: { en: "The Departure of St. Euphemia.", ar: "نياحة القديسة اوفومية" } },
      { kind: 'reading', text: { en: "This day also, marks the martyrdom of St. Euphemia. She was the wife of a man who feared God, and gave much alms. He kept three festivals each month: the", ar: "فى مثل هذا اليوم تنيحت القديسة أوفيمية وكانت زوجة لرجل يتقي الله ويعمل صدقات كثيرة. وكان يهتم بثلاثة أعياد كل شهر وهي تذكار الملاك ميخائيل في الثاني عشر ، وتذكار والدة الإله في الحادي والعشرين ، وتذكار الميلاد المجيد في التاسع والعشرين . ولما دنت ساعة وفاته أوصي زوجته بحفظ هذه العادة وأن لا تقطع عمل الصدقات خصوصا في الأعياد الثلاثة فأحضرت صورة الملاك ميخائيل ، وبعد وفاة زوجها ثابرت علي تنفيذ وصيته ، فحسدها الشيطان وأتاها في شكل راهب ، وجعل يحدثها ويؤكد لها أنه مشفق عليها ثم أشار عليها أن تتزوج لترزق أولادا وان تكف عن عمل الصدقات لئلا ينفذ مالها وقال لها ان زوجك قد نال الملكوت فلا يحتاج إلى صدقة فأجابته قائلة أنني قطعت مع نفسي عهدا بأن لا التصق برجل بعد زوجي وزادت بقولها إذا كانت الطيور كاليمام والغربان لا تعرف ذكرا آخر بعد الأول . فأولي بالبشر الذين خلقوا في صورة الله ومثاله أن يكونوا هكذا ، فتركها الشيطان غاضبا ." } },
      { kind: 'reading', text: { en: "commemoration of the angel Michael, on the twelfth day(1); the commemoration of the Mother of God (Theotokos), on the twenty-first day; and the commemoration of the Nativity of our Lord, on the\ntwenty-ninth day of each month. When the day of his departure drew near, he commanded his wife, to keep this custom, to not stop the giving of alms, and to do the acts of charity especially on these three festivals. He painted a picture of the honorable angel Michael and gave it to her.", ar: "ولما أتي يوم عيد الملاك وقد جهزت كل ما يلزم كعادتها ظهر لها الشيطان في زي ملاك وأعطاها السلام قائلا ان الملاك ميخائيل أرسله إليها يأمرها أن تترك الصدقات وتتزوج برجل مؤمن ثم قال لها ان امرأة بدون رجل كسفينة بغير رئيس وصار يورد لها من الكتاب المقدس أدلة عن إبراهيم واسحق ويعقوب وداود وغيرهم ممن تزوجوا وأرضوا الله فأجابته قائلة ان كنت ملاك الله فأين الصليب علامة جنديتك لان جندي الملك لا يخرج إلى مكان إلا ومعه هذه العلامة . فلما سمع منها هذا الكلام عاد إلى شكله الأول ووثب عليها يريد خنقها . فاستغاثت بالملاك ميخائيل صاحب العيد فخلصها في الحال ثم قال لها هيا رتبي أمورك لأنك في هذا اليوم تنتقلين من هذا العالم وقد اعد لك الرب ما لم تره عين ولا سمعت به أذن ولم يخطر علي قلب بشر وأعطاها السلام وصعد إلى السماء ." } },
      { kind: 'reading', text: { en: "After the departure of her husband, she continued to fulfill his will. Satan was jealous of her, and he came to her disguised as a monk, who talked to her expressing his pity for her. He advised her to get married, to bring forth children, and to refrain from doing charitable deeds lest she finish her money. He told her also that her husband had received the Kingdom and he had no need of the alms giving. She answered saying, \"I have vowed not to consort with another man after my husband.\" She went on saying, \"If birds as the doves and the ravens do not take second mates, how then can men who are created in the form and likeness of God do this?\" The devil left her angry.", ar: "أما القديسة فأنها بعد انتهاء العيد استدعت إليها الأب الأسقف والكهنة وسلمت لهم أموالها لتوزيعها علي المحتاجين ثم تنيحت بسلام ." } },
      { kind: 'reading', text: { en: "When the feast of the Angel had come, and she had prepared all what she needed as her custom, Satan appeared to her in the form of an angel and said to her, \"Peace be to you, the angel Michael has sent me to you, commanding you to cease from these alms, and to marry a believing man.\" Then he told her, \"A woman without a man is like a ship without a captain,\" and he began to bring her proofs out of the Holy Bible in regard of Abraham, Isaac, Jacob, , and others like them who married wives and pleased God. She replied saying, \"If you are an angel of God, where is the Cross, the symbol of your military service? For the soldier of the King never goes to any place without this symbol with him.\" When Satan heard these words from her, he returned to his original form, and jumped on her to choke her. She cried for the angel Michael, whose feast she was celebrating, and he delivered her immediately from him. The angel Michael told her, \"Go and arrange your affairs, for you shall depart from this world today. And behold the Lord has prepared for you what eye has not seen, and ear has not heard, nor has it occurred to the heart of man,\" then he gave her the greeting of peace, and went up into heaven.", ar: "صلاتها تكون معنا آمين" } },
      { kind: 'reading', text: { en: "After, St. Euphemia had celebrated the feast of the angel Michael, she sent for the father the bishop and the priests. She gave them all her money to give to the poor and the needy. Then, she took the Picture of the honorable angel Michael and prayed before it. She laid it upon her face and breast, then departed in peace.", ar: "" } },
      { kind: 'reading', text: { en: "May his intercession be with us and Glory be to God forever. Amen.", ar: "" } },
      { kind: 'reading', text: { en: "During the reign of , Pope Alexandros preached to the people, explaining to them the error of worshipping the idols that do not move or reason, which are made by human hands, and the error of offering sacrifices to them. He changed the temple of this idol to a church in the name of Michael the Archangel, and destroyed that statue. He asked them to distribute these sacrifices to the poor that Christ had called His brothers, to receive the intercession of the angel Michael. This church was called, at that time, the church of El-Kaisariah.", ar: "" } },
      { kind: 'reading', text: { en: "It was said also that this feast was taken after the Ancient Egyptians. They believed that the flood of the Nile started on the eve of the twelfth of the month of Baounah by \"the coming down of the drop.\" That is to say, the tear of \"Isis,\" the goddess of fertility and motherhood. The tear that she shed grieving for her husband \"Osiris,\" the god of agriculture and abundance, who was killed by \"Typhon\" the god of evil.", ar: "" } },
      { kind: 'reading', text: { en: "This feast was replaced in Christianity by the feast of Michael the Archangel (Tareekh El-Omah El-koptiah).", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of St. Justus, the Sixth Pope of the See of St. Mark.", ar: "" } },
      { kind: 'reading', text: { en: "On this day also, of the year 135 A.D., St. Justus, the Sixth Pope of the See of , departed. This saint was an honorable and learned man before his ordination. He was baptized by St. Mark the Apostle, along with his father, his mother and others. St. Anianus, the second pope, ordained him a deacon, then a priest, and appointed him to preach, and teach the people. He was chosen for the papacy to succeed Pope Primus. He shepherded his people with the best of care for ten years. He departed at a pleasing good old age.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of St. Kyrillos the Second, the 67th Pope of Alexandria.", ar: "" } },
      { kind: 'reading', text: { en: "On this day also, the twelfth of Baounah, 808 A.M. (June 6th, 1092 A.D.), the great Pope, St. Kyrillos the Second, the 67th Pope of Alexandria, departed. He became a monk in Sawma'et (Cell) of Singar. Because of his knowledge and righteousness, they chose him a Patriarch, a successor to St. Christodolus, the 66th Pope. His enthronement was on , 794 A.M. (March 18th, 1078 A.D.).", ar: "" } },
      { kind: 'reading', text: { en: "Some of the bishops disobeyed the Pope and decided to depose him. They assembled a council from forty-seven bishops for this purpose. When the Fatimid governor knew of this dissension, he called the bishops to his orchard. He harshly talked to them with words God had put in his mouth. The overseer of the orchard (Yaseeb) sided with those who opposed the Pope. Peter, the pope's disciple, reproved him and an exchange of words took place between them while the Pope was coming out of the meeting. The Pope told the overseer, \"If the Governor has authority, Christ has authority over the heaven and earth.\" The Pope dismounted his horse, and made a matonia before him, which was on Saturday the , 802 A.M. On the next Saturday, the governor became enraged with the overseer of his orchard. He went there and ordered the beheading of the overseer. That was in the same place where the Pope had made the matonia to him and in the same hour.", ar: "" } },
      { kind: 'reading', text: { en: "The Governor told the dissenting bishops, \"You all should be in accordance, and obey your Archbishop.\" Thus, they all were reconciled, and went to the church of . They celebrated the Divine liturgy on Saturday and Sunday and then went to their parishes rejoicing. This Pope remained on the Chair for fourteen years, two month, and thirteen days, then departed in peace.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baouna-13",
    title: { en: "Baouna 13", ar: "13 بؤونه" },
    blocks: [
      { kind: 'heading', text: { en: "The Commemoration of the Archangel Gabriel, the Announcer of Daniel the Prophet.", ar: "تذكار رئيس الملائكة الجليل جبرائيل &quot;غبريال&quot;" } },
      { kind: 'reading', text: { en: "On this day also, the church in Egypt celebrates a feast for the . The angel Gabriel announced with the return of the children of Israel from captivity, the coming of the Lord Christ, the time of His coming, that He would be killed, the destruction of Jerusalem, and that no other Messiah would come after Him except the anti-Christ. This angel is the one who to the , and six months later, he came with the glad tidings of the salvation of the world when he to the saying, \"And behold, you will conceive in your womb and bring forth a Son, and shall call His name JESUS. He will be great, and will be called the Son of the Highest; ... And He will reign over the house of Jacob forever, and of His kingdom there will be no end.\" ( 1:31-33) Therefore, our church has arranged this feast to venerate this honorable angel.", ar: "في هذا اليوم جرت العادة بالديار المصرية أن تعيد للملاك الجليل جبرائيل الذي بشر دانيال برجوع بني إسرائيل وبمجيء السيد المسيح ووقت مجيئه . كما أعلمه بأنه يقتل وتخرب بعد ذلك مدينة أورشليم ولا يأتي بعده إلا المسيح الكذاب وهذا الملاك هو الذي بشر زكريا بولادة يوحنا وبعد ستة أشهر أتي ببشارة الخلاص للعالم عندما بشر العذراء قائلا &quot; ها أنت ستحبلين وتلدين أبنا وتسمينه يسوع هذا يكون عظيما وابن العلي يدعي ويملك علي بيت يعقوب ولا يكون لملكه نهاية&quot; (لو 1 : 31 – 33 ) ولهذا رتبت كنيستنا هذا العيد تكريما لهذا الملاك الجليل ." } },
      { kind: 'reading', text: { en: "May his intercession be with us and Glory be to God forever. Amen.", ar: "شفاعته تكون معنا . ولربنا المجد دائما . آمين" } },
      { kind: 'heading', text: { en: "The Departure of St. John, Bishop of Jerusalem.", ar: "نياحة القديس يوحنا أسقف أورشليم" } },
      { kind: 'reading', text: { en: "On this day, of the year 419 A.D., the holy father St. John the second, bishop of Jerusalem, departed. He became a monk in the monastery of St. Hilarion, with the great father (1). His virtues and knowledge became well known, so they chose him a bishop for Jerusalem in the year 388 A.D., after the ordination of St. Epiphanius, bishop of Cyprus.", ar: "في مثل هذا اليوم من سنة 146 م تنيح الأب القديس يوحنا الثاني أسقف أورشليم . وكان قد ترهب في دير القديس إيلاريون مع الأب الكبير القديس أبيفانيوس أسقف قبرص (ذكرت سيرته تحت يوم 17 بشنس ، ونقل جسده تحت يوم 28 بشنس ) وذاعت فضائله وعلمه فاختاروه لكرسي أورشليم في سنة 388 م بعد رسامة القديس أبيفانيوس أسقفا علي قبرص ، فضربه العدو بمحبة المال فجمع مالا كثيرا وصنع لمائدته أوان من الفضة وأهمل الفقراء والمساكين . ولما بلغ خبره القديس أبيفانيوس شق عليه ذلك لما كان يعلمه عنه أولا من الزهد والنسك والعبادة والرحمة . ونظرا لصداقتهما القديمة قام من قبرص وأتي إلى أورشليم متظاهرا أنه يقصد السجود بها وزيارة القديسين . وفي الباطن ليقابل الأب يوحنا . فلما وصل إلى هناك دعاه الأب يوحنا ووضع أمامه تلك الأواني الفضية علي المائدة فتوجع قلب القديس أبيفانيوس فدبر حيلة للاستيلاء عليها وذلك أنه قصد أحد الأديرة وحده وأرسل إليه يستعير منه تلك الأواني زاعما أن قوما من أكابر القبرصيين قد أتوه ويريد أن يقدم لهم الطعام فيها . ولما أرسلها إليه أخذها وباعها وتصدق بثمنها علي الفقراء . وبعد أيام طالبه الأب يوحنا بالأواني فاستمهله . وكرر مرة ثانية وثالثة وأذ لم يردها له تقابل معه ذات يوم في كنيسة القيامة قائلا له &quot; لا أتركك حتى تعطيني الأواني &quot; فصلي القديس أبيفانيوس إلى السيد المسيح من أجل صاحبه القديم . فعمي وبكي واستغاث بالقديس أبيفانيوس فصلي القديس لا جله . فبرئت إحدى عينيه فالتفت إليه وقال له إن السيد المسيح قد ترك هذه العين الأخرى بدون بصر تذكرة لك . ثم ذكره بسيرته الأولي الصالحة وأعلمه أنه باع الأواني وتصدق بثمنها وأنه ما جاء إلى القدس إلا ليتحقق ما سمعه عن بخله ومحبته للعالم . فانتبه الأب يوحنا من غفلته وسلك في عمل الرحمة سلوكا يفوق الوصف فتصدق بكل ما يملك من مال وثياب وأوان وزهد في كل أمور العالم حتى أنهم لم يجدوا عند نياحته درهما واحدا ، وقد وهبه الله موهبة شفاء المرضي وعمل الآيات وبعد أن أكمل في الرئاسة إحدى وثلاثين سنة تنيح بسلام." } },
      { kind: 'reading', text: { en: "After the ordination of St. John a bishop, the enemy of good led him astray through the love of money. He gathered much money, made silver vessels for his table, and neglected the poor and the needy. When St. Epiphanius heard that, he was troubled for what he knew about his friend St. John, from asceticism, righteousness, worshipping and being merciful. St. Epiphanius, because of his old friendship with St. John, came from Cyprus to Jerusalem. He made it appear that he had come to visit and worship the holy places, and visit the saints, but in fact he came to meet Abba John. When he arrived in Jerusalem, Abba John invited him for a visit. He prepared a table for St. Epiphanius and put these silver vessels on the table before him. When St. Epiphanius saw that, his heart was in pain, for he saw that his friend Abba John had in him no mercy for the poor and the needy. St. Epiphanius devised a plan to put his hands on these silver vessels. He went to one of the monasteries of Jerusalem, and sent to Abba John asking to borrow these vessels from him. He pretended that some of the elders of Cyprus came to visit him and he wished to offer them food using them. When Abba John sent the vessels to St. Epiphanius, he took them, sold them and gave the money as alms to the poor and needy.", ar: "صلاته تكون معنا . آمين" } },
      { kind: 'reading', text: { en: "A few days later, Abba John asked for the vessels, but St. Epiphanius asked him to wait a while on him. Abba John repeated his demand a second and a third time. When St. Epiphanius did not return them, Abba John seized him by the hem of his garment in the church of Resurrection and said to him, \"I will not let you go until you give me back my silver vessels.\" St. Epiphanius prayed to the Lord Christ, and entreated Him for the sake of his old friend. Abba John became blind. He wept, and entreated St. Epiphanius to help him. St. Epiphanius prayed for his sake and one of his eyes was healed. He looked at him and said, \"Behold, the Lord Christ has left blind one of your eyes as a reminder for you.\" He reminded him of his earlier benevolent life, and told him that he had sold his vessels and gave their price as alms. He also told Abba John that he only came to Jerusalem to substantiate what he had heard about his greed and love of the world. Abba John awoke from his foolishness and inadvertence. He walked diligently in the path of charity beyond what can be described. He gave as alms all that he owned of money, clothes, and the vessels. He forsake all things worldly to the point that they did not find even a \"Dirham\" with him when he departed. God granted him the gift of healing the sick and performing signs. After he finished in his episcopate thirty one years, he departed in peace.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baouna-14",
    title: { en: "Baouna 14", ar: "14 بؤونه" },
    blocks: [
      { kind: 'heading', text: { en: "The Martyrdom of Sts. Apakir, John, Ptolemy and Philip.", ar: "استشهاد القديس اباكير ورفيقيه يوحنا وابطلماوس" } },
      { kind: 'reading', text: { en: "On this day also, Sts. Apakir, John, Ptolemy and Philip, were martyred. St. Apakir was born in the city of Damanhur, and had a rich brother called Philip. They had agreed with two priests, one called John and the other called Ptolemy, to receive the crown of martyrdom. They went to the city of Kartsa (Kartes), and confessed the name of the Lord Christ before the Governor. The governor ordered to shoot them to death with arrows, but the arrows did not touch them. They were then cast into red hot fire, but the angel of the lord delivered them from it. Then the governor commanded to tie them to the tails of horses, and to drag them from Kartes to the city of Damanhur, but the Lord guarded them from any harm. The governor commanded that their heads be cut off outside the city of Damanhur. They received the crown of martyrdom. People from the city of Sa came and took the body of St. Apakir, built for him a church, and laid his body inside it. Many signs and wonders took place through him. The people of Damanhur came and took the bodies of John, Ptolemy, and Philip, wrapped them in expensive shrouds and buried them there.", ar: "في مثل هذا اليوم استشهد القديسون أباكير ويوحنا وأبطلماوس وفيلبس . وقد ولد القديس أباكير بدمنهور من كرسي أبو صير غربي نهر النيل وكان له أخ غني يسمي فيلبس وكان هذا قد اتفق مع قسين أحدهما اسمه يوحنا والأخر أبطلماوس واجتمعوا معا وأجمعوا رأيهم علي نيل إكليل الشهادة فذهبوا إلى قرطسا واعترفوا أمام الوالي بالسيد المسيح ، فأمر أن يرموهم بالسهام فلم تدن منهم . ثم طرحهم في نار مشتعلة فخلصهم ملاك الرب منها . فأمر أن يربطوا في أذناب الخيل من قرطسا إلى دمنهور ولكن الرب حفظهم دون آذى، ثم أمر الوالي بقطع رؤوسهم خارج مدينة دمنهور فنالوا إكليل الشهادة وأتي قوم من صا وأخذوا جسد القديس أباكير وبنوا عليه كنيسة أما الثلاثة الآخرون فقد أخذهم أهل دمنهور وكفنوهم بأكفان ثمينة ودفنوهم هناك ." } },
      { kind: 'reading', text: { en: "May their prayers be with us and Glory be to God forever. Amen.", ar: "صلاتهم تكون معنا . ولربنا المجد دائما . آمين" } },
      { kind: 'heading', text: { en: "The Departure of Pope Yoannis the Nineteenth, 113th Patriarch of Alexandria.", ar: "نياحة البابا يوأنس التاسع عشر البطريرك" } },
      { kind: 'reading', text: { en: "On this day, of the year 1658 A.M. (1942 A.D.) Pope Yoannis the Nineteenth, 113th Patriarch of Alexandria, departed. He was born in the village of Dair Tasa, Asyiut governorate in the year 1571 A.M. (1855 A.D.). His parents were righteous, therefore he was raised on piety and godliness. He drank the love of virtuous life and loved, since his young age, to read the biographies of saints. He longed to follow their example, accordingly he went to the monastery of the Virgin Lady known as El-Baramous in Wadi El-Natroun, in the month of Baramoudah, 1591 A.M. He became a monk on the third of Kiahk, 1592 A.M. (1876 A.D.). Because of his fervent worship, intelligence, and intellect, the fathers unanimously agreed to nominate him to be a priest. , ordained him a priest in the year 1593 A.M., then hegumen in Baramhat, 1594 A.M., and appointed him on the same day to be the head of the monastery. He remained the head of the monastery for ten years, during which he was an example of, ambition, honesty, purity of conduct, firmness, godliness, and good management.", ar: "في مثل هذا اليوم من سنة 1658 للشهداء ( 1942 م ) تنيح البابا يوأنس التاسع عشر وهو الثالث عشر بعد المائة من باباوات الإسكندرية . ولد بدير تاسا التابعة لمركز البداري بمديرية أسيوط في سنة 1571 للشهداء ( 1855م ) من والدين تقيين فنشأ علي البر والتقوى وتشرب حب الفضيلة وشغف منذ صغره بقراءة سير القديسين ، ثم تاقت نفسه إلى الاقتداء بهم فقصد دير السيدة العذراء بالبرموس بوادي النطرون في شهر برمودة سنة 1591 للشهداء . وهناك قضي مدة الاختبار - التي يقضيها عادة طالب الترهب - علي الوجه الأكمل . ثم أندمج في سلك الرهبنة في 3 كيهك سنة 1592 للشهداء ( 1876م ) . ونظرا لما اتصف به من حدة الذهن والذكاء المتوقد والعبادة الحارة فقد استقر رأي الأباء علي تزكيته قسا . فرسمه السعيد الذكر المتنيح البابا كيرلس الخامس البطريرك ( 112) قسا في سنة 1593 ش ثم قمصا في برمهات سنة 1594 ش . وفي اليوم نفسه أسندت إليه رئاسة الدير ، فمكث في الرئاسة عشر سنوات كان فيها مثال الهمة والحزم والأمانة وطهارة السلوك والتقوى وحسن التدبير." } },
      { kind: 'reading', text: { en: "When the Chair of the diocese of El-Biharah became vacant, the people chose Yoannis a metropolitan for that Chair. He was ordained on the , 1603 A.M. (1887 A.D.) and also was appointed as a deputy of the See of . After the departure of Anba Yoannis, metropolitan of El-Menofaya at that time, the people of the diocese nominated him to care for them. The diocese of El-Menofaya was added to his duties in the year 1610 A.M. (1894 A.D.), and he became the metropolitan of El-Biharah, El-Menofaya, and the deputy of the See of St. Mark.", ar: "وعندما خلا كرسي أبرشية البحيرة اختاره الشعب مطرانا لهذا الكرسي فرسم في 12 برمهات سنة 1603 للشهداء ( 1887 م ) ، وعين أيضا وكيلا للكرازة المرقسية . وبعد نياحة الأنبا يوأنس مطران المنوفية في ذلك العهد زكاه شعب الأبرشية لرعايته فضمت إليه في سنة 1610 للشهداء ( 1894 م ) وأصبح مطرانا للبحيرة والمنوفية وكيلا للكرازة المرقسية ." } },
      { kind: 'reading', text: { en: "Since his official seat was in Alexandria, he established there a theological school to educate the monks. He sent from its students a mission to Athens for higher theological studies.", ar: "ولما كانت الإسكندرية هي مقر كرسيه فقد أنشأ بها مدرسة لاهوتية لتعليم الرهبان كما أرسل من طلبتها بعثة إلى أثينا للاستزادة من دراسة العلوم اللاهوتية ." } },
      { kind: 'reading', text: { en: "The revenue of the church properties was inconsiderable. By his good judgement, the revenue increased year after year. Because of the highrise buildings that he built and the renovation of the old ones. He also gave great care for the Coptic schools, elementary and high, until their standard became equivalent to the best schools. He built and renovated most of the churches in his parish. He also gave special attention to the monasteries in his jurisdiction, which were improved greatly because of his good care and close supervision.", ar: "وكان أيراد أوقاف الإسكندرية ضئيلا ولكن بحسن تصرفه وغيرته زاد الإيراد سنة بعد أخري بفضل ما شيده من العمارات الشاهقة وما جدده من المباني القديمة كما يرجع إليه الفضل الأكبر في النهوض بالمدارس المرقسية إذ بذل عناية كبيرة واهتم بأمرها حتى وصلت في قسميها الابتدائي والثانوي إلى مستوي أرقي المدارس . ونظرا لما أمتاز به من بعد النظر وصائب الرأي فقد اختارته الحكومة ممثلا للأقباط في عدة مجالس نيابية كمجلس شوري القوانين والجمعية العمومية ولجنة وضع الدستور وغيرها ." } },
      { kind: 'reading', text: { en: "Because of his foresight, and prudence, the government chose him as a representative for the Copts in many councils and committees at the general assembly, the committee for formulating the constitution and many others.", ar: "وقضي في المطرانية اثنين وأربعين عاما حفلت بجلائل الأعمال إذ ساهم في إنشاء جملة مدارس وبناء وتجديد أغلب كنائس أبرشيته وكان له أوفر نصيب في تعضيد المشروعات النافعة كذلك وجه عناية خاصة إلى الأديرة البحرية فارتقت شؤونها بحسن أشرافه عليها ورعايته لها ." } },
      { kind: 'reading', text: { en: "He spent forty-two years as a metropolitan, which were full of splendid works. When the blessed Pope Kyrillos the fifth, departed, on the 1st day of Misra, 1643 A.M. (August 7th, 1927 A.D.) the Holy Synod convened on the fourth of Misra. They unanimously agreed to chose him Acting Pope to run the affairs of the church until ordaining a patriarch. As a result of that, the Holy Synod had received many nominations from the parishes approving that choice.", ar: "ولما تنيح البابا البار الطيب الذكر الأنبا كيرلس الخامس في أول مسرى سنة 1643 للشهداء ( 7 أغسطس سنة 1927 م ) اجتمع المجمع الإكليريكي في ( 4 مسري سنة 1643 ش 10 أغسطس سنة 1927 م ) من الأباء المطارنة والأساقفة بالدار البطريركية وأستقر الرأي علي اختياره قائما مقام البطريرك لإدارة شئون الأمة والكنيسة لحين رسامة بطريرك . وعلي أثر ذلك تلقي المجمع تزكيات من عموم الابرشيات والمجالس الملية بالموافقة علي هذا الاختيار ." } },
      { kind: 'reading', text: { en: "He performed his duties as Acting Patriarch for one year, four months, and ten days. During this period he administered the affairs of the See of St. Mark very well, during which also the Holy Synod, with Anba Yoannis presiding, issued a canon to regulate the affairs of the monasteries and the monks. He organized a committee to oversee the church properties and those of the monasteries and to review their accounts.", ar: "ولبث قائما بأعمال البطريركية سنة واحدة وأربعة أشهر وعشرة أيام دبر في أثنائها شئون الكرازة المرقسية أحسن تدبير وفي خلالها أصدر المجمع الإكليريكي برياسته قانونا لتنظيم شئون الأديرة والرهبان ." } },
      { kind: 'reading', text: { en: "From what everyone knew of his purity, virtuous life, good character, asceticism, and piety, they all unanimously agreed to chose him a patriarch with nominations from the bishops, priests and lay leaders. He was enthroned a patriarch on Sunday the 1645 A.M. (December 16th, 1928 A.D.) in the great St. Mark cathedral in Cairo (Azbakiah). That took place with a great celebration attended by the representatives of the King, princes, ministers, important Egyptian personalities, the metropolitans of different denominations eastern and western, and ambassadors of foreign countries.", ar: "أما الأوقاف القبطية فقد رأي بصائب فكره أن تؤلف لجنة برئاسته وعضوية أثنين من المطارنة وأربعة من أعضاء المجلس الملي العام لمراجعة حسابات أوقاف الأديرة وقد صدر قرار بذلك من وزير الداخلية ." } },
      { kind: 'reading', text: { en: "After his ordination, Pope Yoannis directed his attention to caring for the affairs of the Coptic People and the church. He established a higher theological institution for the education of the monks in the city of Helwan. He ordained for the kingdom of Ethiopia, a Coptic Metropolitan and four well-learned Ethiopian bishops. He travelled to Ethiopia to reaffirm the unity between the Coptic and Ethiopian churches. He stayed there for thirteen days where they received him with great honor and respect. In Addis Ababa, he ordained the head of the Ethiopian monks (the successor of St. Takla Haymanot) a bishop.", ar: "ونظرا لما يعرفه الجميع عنه من طهارة السيرة والخصال الحميدة والنسك والزهد وكمال الأخلاق فقد انتهي الإجماع علي اختياره بطريركا بتزكيات من الأباء المطارنة والكهنة وأعيان الشعب والمجالس الملية فرسم بطريركا في صباح الأحد 7 كيهك سنة 1645 للشهداء ( 16 ديسمبر سنة 1928 م ) بالكاتدرائية المرقسية الكبرى بمصر باحتفال عظيم حضره نائب الملك والأمراء والوزراء وكبار رجال الدولة وعظماء المصريين من مختلف الطوائف ومطارنة الطوائف الشرقية والغربية ووزراء الدول المفوضون ." } },
      { kind: 'reading', text: { en: "With the will of God, he made the Holy Oil (Myron) in the year 1648 A.M. (1930 A.D.). The last time the oil was made was one hundred and ten years earlier during the papacy of Pope Peter, 109th Pope of Alexandria. Pope Yoannis made the Holy Oil a second time, specially for the kingdom of Ethiopia, attended by Anba Kyrillos, metropolitan of Ethiopia, and Anba Peter, an Ethiopian bishop.", ar: "وبعد رسامته وجه عنايته إلى الاهتمام بشئون الأمة والكنيسة وكان أول مظهر لهذه العناية أتشاء مدرسة لاهوتية عليا للرهبان في مدينة حلوان كما رسم للمملكة الأثيوبية مطرانا قبطيا وأربعة أساقفة من علماء الأثيوبيين . وتوثيقا لعري الاتحاد بين الكنيستين القبطية والأثيوبية سافر إلى البلاد الأثيوبية ومكث هناك ثلاثة عشر يوما كان فيها موضع الاحتفاء العظيم . ورسم في أديس أبابا رئيس رهبان الأحباش ( خليفة القديس تكلا هيمانوت الحبشي ) أسقفا ، وشاءت العناية الربانية أن يتولي عمل الميرون المقدس فعمله في سنة 1648 للشهداء ( 1930 م ) وكان قد مضي علي عمله مائة وعشر سنين منذ عهد المتنيح البابا بطرس المائة والتاسع من باباوات الإسكندرية كما عمله مرة ثانية خصيصا للملكة الأثيوبية بحضور الأنبا كيرلس مطران أثيوبيا والأنبا بطرس أحد الأساقفة الأثيوبيين." } },
      { kind: 'reading', text: { en: "His contributions, too numerous to be mentioned completely, include watching over the welfare of the church, kindness to the needy, support for charitable organizations, moral and financial support for the Coptic teaching institutions, and assistance on valuable projects that financially and spiritually benefitted the Copts.", ar: "ويضيق المجال عن تعداد فضائله التي تجلت من حين لآخر في السهر علي مصلحة الكنيسة والعطف علي المحتاجين ومؤازرة ومعاونة الجمعيات الخيرية ومعاهد التعليم ماديا وأدبيا وتعضيد المشروعات النافعة التي عادت علي الأقباط بالخير والبركات ." } },
      { kind: 'reading', text: { en: "During Pope Yoannis' papacy, a war broke out between Ethiopia and Italy, during which most of the Ethiopian bishops died except Anba Abraam and another bishop. When Italy occupied Ethiopia, the Emperor departed from his country. Anba Kyrillos, the metropolitan of Ethiopia, was exiled to Egypt, for he refused to agree with Italy on separating the Ethiopian church from the Coptic Orthodox church. In November, 1937 A.D., the Italian governor of Ethiopia decided the independence of the Ethiopian church and its separation from the Alexandrian See. He appointed Anba Abraam, the Ethiopian bishop, a patriarch for Ethiopia. Nevertheless, God punished him for his betrayal. He became blind and died shortly after. The Alexandrian Holy Synod decided to excommunicate him, not recognizing him nor the bishops that he ordained. This situation in Ethiopia did not last long; during the Second World War the Emperor of Ethiopia regained his kingdom from Italy. Anba Kyrillos returned to his church with great honor, in May 1942 A.D.", ar: "وفي أثناء رئاسته الكرسي المرقسي نشبت الحرب بين مملكة أثيوبيا إلى الديار المصرية لأنه لم يوافق إيطاليا علي انفصال الكنيسة الأثيوبية عن الكنيسة القبطية الأرثوذكسية ." } },
      { kind: 'reading', text: { en: "When Pope Yoannis had realized the return of the Ethiopian church to its mother church, the Coptic Church, he was stricken with the ailments of old age. He departed in peace on Sunday 14th day of Baounah, 1658 A.M. (June 21st, 1942 A.D.).", ar: "وفي 27 نوفمبر سنة 1937 قرر نائب ملك إيطاليا استقلال كنيسة أثيوبيا وانفصالها عن الكرسي الإسكندري . وعين الأنبا أبرآم الأسقف الأثيوبي بطريركا علي أثيوبيا ، لكن الله عاقبه علي هذه الخيانة فأصيب بالعمي ومات . ثم قرر المجمع المقدس الإسكندري حرم أبرآم المذكور وعدم الاعتراف به ولا بالأساقفة الذين رسمهم ." } },
      { kind: 'reading', text: { en: "May his prayers be with us. Amen", ar: "ولكن هذا الحال لم يدم كثيرا إذا قامت الحرب العظمي في سنة 1939 ودخلت إيطاليا الحرب ضد إنجلترا وفرنسا . وفي سنة 1941 م استرد إمبراطور أثيوبيا مملكته من إيطاليا وعاد الأنبا كيرلس مطران الإمبراطورية الأثيوبية إلى كرسيه مكرما في 30 مايو سنة 1942 م مصحوبا بوفد بطريركي مكون من سعادة صادق وهبه باشا ومريت بك غالي وفرج بك موسى قنصل مصر بأثيوبيا سابقا ." } },
      { kind: 'reading', text: { en: "", ar: "وبعد أن اطمأن البابا يوأنس علي عودة أثيوبيا إلى حظيرة أمها الكنيسة القبطية كان قد اعتراه مرض الشيخوخة فاسلم الروح في الساعة الثانية من صبيحة الأحد 14 بؤونة سنة 1665 ش ( 21 يونية سنة 1942 م ) بركة صلاته تكون معنا . آمين" } },
      { kind: 'heading', text: { en: "", ar: "اول فصل الصيف" } },
      { kind: 'reading', text: { en: "", ar: "اطول نهار 14 ساعة و5 دقائق" } }
    ],
  },
  {
    id: "synax-baouna-15",
    title: { en: "Baouna 15", ar: "15 بؤونه" },
    blocks: [
      { kind: 'heading', text: { en: "The Consecration of the Church of Mari Mina at Maryut.", ar: "تذكار كنيسة مارمينا بمريوط" } },
      { kind: 'reading', text: { en: "On this day also, is the commemoration of the appearance of the body of the honorable saint, and , and the consecration of his church at Maryut (Mareotis).", ar: "في مثل هذا اليوم تذكار ظهور جسد القديس الجليل والشهيد العظيم ما رمينا وتكريس كنيسته بمريوط وذلك أنه لما كان جسد هذا القديس مخفي وأراد الرب إظهاره حدث أنه كان في تلك الجهة راعي غنم وفي أحد الأيام غطس خروف أجرب من خرافه في بركة ماء كانت بجانب المكان الذي به جسد القديس ثم خرج من الماء وتمرغ في تراب ذلك المكان فبريء في الحال فلما عاين الراعي هذه الأعجوبة بهت وصار يأخذ تراب ذلك المكان ويسكب عليه من ماء هذه البركة ويلطخ به كل خروف أجرب أو به عاهة فيبرأ في الحال وشاع هذا الآمر في كل الأقاليم حتى سمع به ملك القسطنطينية وكان له ابنة وحيدة مصابة بالبرص فأرسلها أبوها إلى هناك واستعلمت من الراعي عن كيفية التخلص من مرضها فعرفها فأخذت من التراب وبللته بالماء وتوارت ثم لطخت جسمها ونامت تلك الليلة في ذلك المكان فرأت في الحلم القديس مينا وهو يقول لها &quot; قومي باكرا واحفري في هذا المكان فتجدي جسدي &quot; واستيقظت من نومها فوجدت نفسها قد شفيت ولما حفرت في المكان وجدت الجسد المقدس فأرسلت إلى والدها وأعلمته بهذا الآمر ففرح كثيرا وشكر الله ومجد اسمه . وأرسل المال والرجال وبني في ذلك الموضع كنيسة كرست في مثل هذا اليوم ." } },
      { kind: 'reading', text: { en: "Now, the body of this saint was hidden, and the Lord wished to reveal it. It came to pass that there was a shepherd, who pastured his sheep near the place where the body of the saint was buried. One day, one of his sheep, which was sick of a skin disease (mangy), dipped itself in the water of a pond which was near that place. It then went out of the water, and rolled itself in the sand of that place, and it was healed straightway. When the shepherd saw this wonder, he marvelled, and took the sand of that place and mixed it with the water of the pond. He smeared every mangy sheep, or any that had a deformity, and they were healed immediately.", ar: "ولما تملك أركاديوس وأنوريوس أمرا أن تبني هناك مدينة سميت مريوط وكانت الجماهير تتقاطر إلى تلك الكنيسة يستشفعون بالقديس الطوباوي مار مينا وقد شرفه الله بعمل الآيات والعجائب التي كانت تظهر من جسده الطاهر حتى احتل المسلمون المدينة وهدمت الكنيسة ." } },
      { kind: 'reading', text: { en: "The report of this shepherd became widespread in all the regions of the empire, until the emperor of Constantinople heard of it. He had an only daughter who was leprous. Her father sent her there. She questioned the shepherd about how she could get rid of her illness, and he told her. She took some of that sand and mixed it with the water. She retired to her quarters and smeared her body with the mixture and slept that night in that place. She saw in a dream St. Mina and he told her, \"Rise up early and dig in this place and you shall find my body.\" When she woke up from her sleep, she found herself healed. She dug in that place, and she found the holy body. She sent to her father to inform him about what had happened. He rejoiced exceedingly, thanked God and praised His Holy Name. He sent men and money and built a church in that place which was consecrated on this day.", ar: "أما تاريخ حياة هذا القديس فهو مذكور تحت اليوم الخامس عشر من شهر هاتور شفاعته تكون معنا ولربنا المجد دائما . آمين" } },
      { kind: 'reading', text: { en: "When Arcadius and Honorius reigned they ordered a city to be built there which was called Maryut. The masses came to this church interceding with the blessed Mari Mina. God had honored him by the miracles and wonders(1) that were manifested from his pure body, until the Moslems occupied the city and destroyed it.", ar: "" } },
      { kind: 'reading', text: { en: "The biography of this saint is mentioned under the .", ar: "" } },
      { kind: 'reading', text: { en: "May his intercession be with us and Glory be to God forever. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Turning Over of the Relics of the Great St. Mark the Apostle by the hand of Pope Paul the Sixth, Pope of Rome.", ar: "استلام رفات مار مرقس بروما" } },
      { kind: 'reading', text: { en: "On this day, of the year 1684 A.M., that coincided with Saturday the 22nd of June, 1968 A.D., and in the tenth year of the papacy of , the official delegation of the Pope of Alexandria received the relics of the great from the hand of Pope Paul the Sixth, Pope of Rome, in the Papal palace, Vatican City.", ar: "في مثل هذ1 اليوم من سنة 1684 للشهداء الأطهار الموافق السبت 22 من شهر يونيو سنة 1968 م وفي السنة العاشرة لحبرية البابا كيرلس السادس وهو البابا المائة والسادس عشر في سلسلة باباوات الكرازة المرقسية تسلم الوفد الرسمي الموفد من قبل البابا كيرلس السادس رفات القديس العظيم مار مرقس الرسول كاروز الديار المصرية والبطريرك الأول للكرازة المرقسية من يد البابا بولس السادس بابا روما في القصر البابوي بمدينة الفاتيكان ." } },
      { kind: 'reading', text: { en: "The delegation consisted of ten metropolitans and bishops, seven of them were Coptic and three Ethiopians, and three lay leaders. The Alexandrian papal delegation left Cairo on Thursday the 23rd day of Baounah, 1684 A.M. (June 20th, 1968 A.D.) on a special plane accompanied by 90 of the Coptic personalities, among them, seven priests. They were received by a delegation of cardinals and priests delegated by Pope Paul the Sixth, and the ambassador of Egypt to the Vatican, at the airport in Rome.", ar: "وكان الوفد مؤلفا من عشرة من المطارنة والأساقفة بينهم سبعة من الأقباط وثلاثة من المطارنة الأثيوبيين وثلاثة من الأراخنه . أما المطارنة والأساقفة فهم علي التوالي بحسب أقدمية الرسامة : الأنبا مرقس مطران أبو تيج وطهطا وطما وتوابعها رئيس الوفد ، الأنبا ميخائيل مطران أسيوط وتوابعها والأنبا أنطونيوس مطران سوهاج والمنشاة وتوابعهما ، والأنبا بطرس مطران أخميم وساقلته وتوابعهما والأنبا يوأنس مطران تيجراي وتوابعها بأثيوبيا والأنبا لوكاس مطران أروسي وتوابعها بأثيوبيا والأنبا بطرس مطران جوندار وتوابعها بأثيوبيا والأنبا دوماديوس أسقف الجيزة وتوابعها ، والأنبا غريغوريوس أسقف عام للدراسات اللاهوتية العليا والثقافة القبطية والبحث العلمي والأنبا بولس أسقف حلوان وتوابعها ." } },
      { kind: 'reading', text: { en: "Twelve o'clock, the morning of Saturday the 15th of Baounah (June 22nd), was the appointed time for the Alexandrian Papal delegation to meet the Pope of Rome and receive the relics of St. Mark the Apostle. At the appointed time, the delegation went in headed by Anba Marcus, metropolitan of Abu-Teeg and Tahta, and were received by Pope Paul VI in his private office. Pope Paul greeted the delegation, commending Pope Kyrillos the sixth, and the church of Alexandria. He congratulated the delegation on the opening of the new St. Mark Cathedral and the receiving of the relics of St. Mark. Anba Marcus, the head of the delegation, replied with a short speech, in which he carried the greetings of his brother, the Pope of Alexandria. Then he handed him a letter from Pope Kyrillos the sixth, thanking him and introducing the members of the delegation.", ar: "وأما الأراخنه المدنيون بحسب ترتيب الحروف الأبجدية فهم الأستاذ إدوارد ميخائيل الأمين العام للجنة الملية لأوقاف البطريركية والأستاذ فرح إندراوس الأمين العام لهيئة الأوقاف القبطية والأستاذ المستشار فريد الفرعوني وكيل المجلس الملي بالإسكندرية ." } },
      { kind: 'reading', text: { en: "Pope of Rome, along with the head of the Alexandrian delegation, then carried the box that contained the relics of St. Mark. They all walked in a procession to a grand room, which was prepared to receive the Copts, accompanied by the official delegates to witness this historical and joyful moment. The box containing the relics was placed on a special table. The Roman Pontiff came forward and knelt before the box and kissed it. He was followed by Anba Marcus, the head of the Alexandrian Papal delegation, who was followed by the members of the delegation. During the veneration of the relics of St. Mark the Apostle, the Coptic priests and deacons present chanted appropriate ecclesiastical hymns. Joy filled the hearts of everyone, Egyptian and foreign. An atmosphere of spirituality and holiness filled the room.", ar: "وقد غادر الوفد البابوي السكندري القاهرة بعد ظهر يوم الخميس 23 بؤونة سنة 1684 ش الموافق 20 يونيو سنة 1968 م في طائرة خاصة يرافقه فيها نحو 90 من اراخنه القبط بينهم سبعة من الكهنة ." } },
      { kind: 'reading', text: { en: "The Roman Pope then sat on his throne, and Anba Gregorius, bishop of higher studies and scientific research, gave a speech in English, representing the delegation. He expressed in it the greetings of Pope Kyrillos the Sixth, and the joy of the Christians of Egypt and Ethiopia for the return of the relics of St. Mark the Apostle after eleven centuries. During which the body of St. Mark was absent from the country in which he was martyred.", ar: "وكان في استقبالهم بمطار روما بعض المطارنة والكهنة موفدين من قبل البابا بولس السادس وسفير جمهورية مصر العربية لدي الفاتيكان ." } },
      { kind: 'reading', text: { en: "Pope of Rome, replied in an official speech in French, that he read while sitting on the throne. In it he exalted the history of the Alexandrian church, and its long struggle in the field of dogma. He also praised its heros, and its learned people such as Athanasius the apostolic, , Pantaenus and Clement. He hoped that the celebration of the day would be a sign of love and a bond between the church of Alexandria and the church of Rome. The Roman Pope asked in his speech also from the head, Cardinal Doval, and members of the Roman Papal delegation to carry his greetings, admiration, and appreciation to Pope Kyrillos the Sixth, the clergy of the church of Alexandria, Egypt and its people.", ar: "وتحددت الساعة الثانية عشرة من صباح يوم السبت 15 بؤونة الموافق 22 يونيو لمقابلة الوفد البابوي السكندري لبابا روما وتسلم رفات مار مرقس الرسول وقبيل الموعد المحدد بوقت كاف تحرك الركب المؤلف من الوفد البابوي السكندري وأعضاء البعثة الرومانية الكاثوليكية برياسة الكاردينال دوفال كاردينال الجزائر ومعه المطران فيلبرا اندز أمين عام لجنة العمل علي اتحاد المسيحيين والمطران أوليفوتي مطران البندقية ( فينيسيا ) وثلاثة من الكهنة في موكب رسمي وقد أقلتهم سيارات الفاتيكان الفاخرة تتقدمها الدراجات البخارية إلى القصر البابوي بمدينة الفاتيكان ." } },
      { kind: 'reading', text: { en: "Afterwards, the Pope and Anba Marcus, the head of the delegation, rose up to exchange the commemorative gifts. Anba Marcus gave the Pope the presents which were sent by H.H. Pope Kyrillos. Pope of Rome admired the precious gifts and asked Anba Marcus to convey his thanks to H.H. Pope Kyrillos. The Pope in return gave the members of the delegation commemorative presents.", ar: "وفي الساعة عشرة تماما دخل الوفد البابوي السكندري يتقدمه الأنبا مرقس مطران أبو تبج وطنطا رئيس الوفد يتبعه المطارنة والأساقفة بحسب ترتيب الرسامة ثم الأراخنه ، وكان البابا بولس السادس عند مدخل مكتبه الخاص واقفا يستقبل رئيس وأعضاء الوفد الواحد بعد الأخر ثم جلس علي عرشه وجلس أعضاء الوفد وبدأ البابا بولس السادس يتكلم وهو جالس يحيي الوفد ومشيدا بالبابا كيرلس السادس وبكنيسة الإسكندرية ويهنئ بافتتاح الكاتدرائية المرقسية الجديدة وباستلام رفات مار مرقس الرسول ورد الأنبا مرقس رئيس الوفد بكلمة قصيرة قال فيها أنه يحمل إليه تحيات أخيه بابا الإسكندرية ثم سلمه خطابا من البابا كيرلس السادس يوجه فيه الشكر إليه ويفيده بأسماء أعضاء الوفد الرسمي الذين انتدبهم نيابة عنه لاستلام رفات مار مرقس الرسول ثم نهض البابا بولس ونهض أعضاء الوفد معه وحمل بابا روما ورئيس الوفد السكندري معا الصندوق الحاوي لرفات مار مرقس وسار الكل اثنين اثنين في موكب رسمي وانتقلوا من مكتب البابا إلى قاعة كبيرة كانت قد أعدت لاستقبال الأقباط المرافقين للوفد الرسمي ليشهدوا اللحظة المقدسة السعيدة ووضع صندوق الرفات علي مائدة خاصة ثم تقدم الحبر الروماني وسجد أمام الصندوق وقبله وفعل كذلك الوفد البابوي السكندري وتلاه بقيه أعضاء الوفد وفي أثناء أداء هذه التحية الإكرامية لرفات مار مرقس الرسول كان الكهنة القبط ينشدون الألحان الكنسية المناسبة وقد استحوذت السعادة علي قلوب الجميع مصريين وأجانب ومرت تلك اللحظات رهيبة وسعيدة وكان الموقف كله مثيرا وقد خيم علي القاعة جو عميق من الروحانية والتقوى والقداسة والورع" } },
      { kind: 'reading', text: { en: "The Roman Pope, then gave Anba Marcus, the head of the Alexandrian Papal delegation, an official document dated May 28th, 1968 A.D. testifying that the , and were taken from their original place with veneration. The document was signed by Cardinal Porfeer, the deputy of Vatican City. Thus, the official celebration of handing over the relics of St. Mark the Apostle ended, and the delegation went back to their hotel.", ar: "ثم جلس بابا روما علي عرشه وحينئذ نهض الأنبا غريغوريوس وألقي نيابة عن الوفد خطابا باللغة الإنجليزية نقل فيه تحية البابا كيرلس السادس إلى البابا بولس السادس معبرا عن سعادة مسيحيي مصر وأثيوبيا بعودة رفات مار مرقس الرسول بعد أحد عشر قرنا ظل فيها جسد مار مرقس غريبا عن البلد الذي مات فيه شهيدا." } },
      { kind: 'reading', text: { en: "May the blessings of St. Mark be with us all. Amen.", ar: "ورد بابا روما في خطاب رسمي باللغة الفرنسية كان يقرأه وهو جالس علي عرشه أشاد فيه بتاريخ كنيسة الإسكندرية ونضالها الطويل الرائد في ميدان العقيدة وأشاد أيضا بأبطالها وعلمائها من أمثال أثناسيوس الرسولي وكيرلس عمود الإيمان وبنتينوس واكليمنضس راجيا أن يكون حفل اليوم علامة محبة ورابطة تربط بين كنيسة الإسكندرية وكنيسة روما وطلب البابا الروماني في خطابه إلى رئيس وأعضاء البعثة البابوية الرومانية أن يحملوا تحياته ومحبته وتقديره إلى البابا كيرلس السادس وأكليروس كنيسة الإسكندرية ومصر وشعبها ." } },
      { kind: 'reading', text: { en: "", ar: "بعد ذلك نهض البابا بولس والأنبا مرقس رئيس الوفد ليتبادلا الهدايا التذكارية فقدم الأنبا مرقس هدايا البابا كيرلس السادس وهي أربع كالآتي :" } },
      { kind: 'reading', text: { en: "", ar: "1 – صندوق فاخر مغطي ومبطن بالقطيفة الحمراء ويحمل كتاب العهد الجديد باللغة القبطية البحيرية مجلد بجلد فاخر بلون بني ممتاز وكتب عليه الإهداء باللغتين القبطية والإنجليزية من البابا كيرلس إلى البابا بولس السادس مع الإشارة إلى تاريخ اليوم وهو السبت 22 يونيو 1968 الموافق 15 بؤونة 1684ش ." } },
      { kind: 'reading', text: { en: "", ar: "2 – صندوق فاخر مغطي ومبطن بالقطيفة الحمراء ويشتمل علي قطعة نسيج أثرية ثمينة من القرن الخامس والسادس الميلادي عثر عليها في بلدة الشيخ عبادة بمحافظة المنيا وقد كانت هذه القطعة ضمن محفوظات المعهد العالي للدراسات القبطية بالقاهرة قدمها للبابا كيرلس السادس مساهمة وتعبيرا عن السرور العام بعودة رفات مار مرقس ." } },
      { kind: 'reading', text: { en: "", ar: "3 – صندوق فاخر مغطي ومبطن بالقطيفة الحمراء ويحمل اسطوانات القداس الباسيلي وألحانه كاملة التي أصدرها قسم الموسيقي والألحان بالمعهد العالي للدراسات القبطية ." } },
      { kind: 'reading', text: { en: "", ar: "4 - صندوق فاخر مغطي ومبطن بالقطيفة الحمراء ويحمل سجادة ممتازة طولها متران و30 سنتيمترا من صنع فلاحي قرية الحرانية بمصر تحت أشراف الفنان الدكتور رمسيس ويصا واصف الأستاذ بالمعهد العالي للدراسات القبطية وقد سجل علي هذه السجادة رسوم عدة تمثل قصة يوسف الصديق كاملة ." } },
      { kind: 'reading', text: { en: "", ar: "وقد أعجب بابا روما بهذه الهدايا الثمينة كل الإعجاب وشكر بابا الإسكندرية شكرا جزيلا وقال أنه سيحتفظ بهذا كله في الفاتيكان ذخيرة لكل الأجيال . ثم وزع البابا بولس السادس بيده هدية تذكارية لكل أعضاء الوفد البابوي السكندري عبارة عن صليب رسم عليه المسيح مصلوبا ويقف علي جانبي الصليب القديس بطرس الرسل علي يمين المسيح والقديس بولس الرسول علي يساره ومن خلف الصليب نقش اسم بولس السادس الحبر الأعظم . كما أهدي البابا لجميع الكهنة والمرافقين مداليات تذكارية نقشت عليها صورتا مار بطرس ومار بولس الرسولين من جهة وعلي الوجه الآخر نقش صورة بولس السادس الحبر الروماني ثم قدم البابا الروماني للأنبا مرقس رئيس الوفد البابوي السكندري وثيقة رسمية بتاريخ 28 مايو سنة 1968 م تشهد بصحة الرفات وأنها بالحقيقة رفات مار مرقس الرسول وأنها استخرجت من مكانها الأصلي بكل وقار وقد وقع عليها أسقف بورفير حارس ذخيرة الكرسي الرسولي ووكيل عام الفاتيكان وكانت الساعة قد صارت الأولي بعد الظهر وبذلك أنتهي الحفل الرسمي لتسليم رفات القديس مرقس وعاد الوفد إلى فندق ميكل أنجلو ( الملاك ميخائيل ) بروما ." } },
      { kind: 'reading', text: { en: "", ar: "بركة مار مرقس الرسول تشمل الجميع ولربنا المجد دائما ." } }
    ],
  },
  {
    id: "synax-baouna-16",
    title: { en: "Baouna 16", ar: "16 بؤونه" },
    blocks: [
      { kind: 'heading', text: { en: "The Departure of St. Abba Nofer the Anchorite.", ar: "نياحة القديس ابو نوفر السائح" } },
      { kind: 'reading', text: { en: "On this day, the ascetic father, Abba Nofer the Anchorite, departed at a good old age, and of a glorious memory, in the desert of Upper Egypt. The grace of God had moved , and he longed to see the servants of God, the Anchorites. He saw many of them, among them St. Abba Nofer, and wrote their biographies.", ar: "في مثل هذا اليوم تنيح الأب الفاضل صاحب الذكر الجميل والشيخوخة الصالحة القديس أبا نفر السائح ببرية الصعيد . وذلك قد ذكره القديس بفنوتيوس الذي حركته نعمة الله شوقا إلى رؤية عبيد الله السواح . فأبصر جماعة منهم ومن بينهم القديس أبا نفر وكتب قصصهم . وقال أنه دخل البرية مرة ووجد عين ماء ونخلة ورأي القديس مقبلا إليه عريانا ومستترا بشعر رأسه ولحيته . فلما رآه الأب بفنوتيوس خاف وظنه روحا فشجعه القديس وصلب أمامه وصلي الصلاة الربانية ثم قال له : &quot; مرحبا بك يا بفنوتيوس &quot; فلما دعاه باسمه هدأ روعه . ثم صليا وجلسا يتحدثان بعظائم الله . فسأله بفنوتيوس أن يعرفه عن سيرته وكيف وصل إلى هناك . فأجابه : &quot; أنني كنت في دير رهبان أتقياء قديسين ، فسمعتهم ينعتون سكان البرية السواح بكل الأوصاف الجميلة فقلت لهم : وهل يوجد من هو أفضل منكم . فأجابوا نعم . سكان البرية السواح لأننا نحن قريبون من العالم فإن ضاق صدرنا وجدنا من يعزينا وان مرضنا وجدنا من يفتقدنا وان تعرينا وجدنا من يكسونا أما سكان البرية فليس لهم شيء من ذلك فلما سمعت منهم هذا جزع قلبي ." } },
      { kind: 'reading', text: { en: "He said that once he went into the desert and found a well of water and a palm tree. Then he saw the saint coming to him, naked, and the hair of his head and beard covered his body. When St. Paphnutius saw him, he was afraid and thought that he was a spirit. Saint Abba Nofer encouraged him, made the sign of the cross, and prayed the Lord's prayer, then said to him, \"Welcome O Paphnoute.\" When he called him by his name, St. Paphnutius calmed down. They prayed together, then sat, and talked about the greatness and goodness of God.", ar: "ولما كان الليل أخذت قليلا من الخبز وخرجت من الدير ثم صليت إلى السيد المسيح أن يهديني إلى موضع أقيم فيه فسهل لي الرب أن وجدت رجلا قديسا فأقمت عنده حتى علمني كيف تكون السياحة وبعد ذلك أتيت إلى هنا فوجدت هذه النخلة وهذه العين . تطرح النخلة اثني عشر عرجونا في كل سنة فيكفيني كل عرجون شهرا وأشرب الماء من هذه العين . لي إلى اليوم ستون سنة لم أر وجه إنسان سواك ." } },
      { kind: 'reading', text: { en: "St. Paphnutius asked Abba Nofer to tell him about his life and how he came to that place. Abba Nofer replied, \"I was in a monastery wherein lived holy and righteous monks. I heard them talking about the greatness of those anchorites who dwelled in the desert and their good virtues. I said to them, 'Are there any who are better than you?' They said to me, 'Yes, those anchorites who dwell in the wilderness. We live near the world, if we are sorrowful or sad, we find someone to console us; if we are sick, we find someone to visit and treat us; if we are naked, we find someone to clothe us. Those who live in the wilderness lack all these things.' When I heard that from them, my heart became anxious.", ar: "وبينما هما يتحدثان بهذا نزل ملاك الرب وأعلم القديس أبا نفر بقرب نياحته . وفي الحال تغير لونه وصار شبه نار . ثم أحني ركبتيه وسجد للرب . وبعد أن ودع القديس بفنوتيوس أسلم روحه الطاهرة فكفنه القديس بفنوتيوس ودفنه في مغارته ورغب أن يسكن موضعه ولكن بعدما دفنه نشفت النخلة وسقطت أما عين الماء فجفت . وكان ذلك بتدبير من الله ليعود القديس بفنوتيوس إلى العالم ويبشرهم بذكر السواح القديسين الذين رآهم ." } },
      { kind: 'reading', text: { en: "\"When the night came, I took a little bread and I went out from the monastery. Then I prayed to the Lord Christ and asked Him to guide me to the place where I was to live. The Lord facilitated my way and I found a holy and righteous man. I dwelt with him, and he taught me all about the life and the ways of the hermits and the anchorites. After I came to this place, I found a palm tree, and a well. The tree bore twelve clusters of dates each year. One cluster of dates is enough food for me for a month, and I drink water from this well. I have lived here for sixty years during which I have never seen the face of a man except yours.\"", ar: "صلاتهم تكون معنا . ولربنا المجد دائما . آمين" } },
      { kind: 'reading', text: { en: "While they were talking together the angel of the Lord came down, and told St. Abba Nofer that his departure was near. Straightway, his color changed and became like fire, then he bowed his knees and worshipped God. After he embraced St. Paphnutius, he delivered up his pure soul. St. Paphnutius wrapped him, and buried him in his cave. St. Paphnutius wished to live in the place of Abba Nofer. But after he had buried him, the palm tree dried and fell down and the water of the well dried up. That happened by the Will of God, so St. Paphnoute would return to the world and tell us about the holy hermits that he had seen.", ar: "" } },
      { kind: 'reading', text: { en: "May their prayers be with us and Glory be to god forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baouna-17",
    title: { en: "Baouna 17", ar: "17 بؤونه" },
    blocks: [
      { kind: 'heading', text: { en: "The Departure of St. Latsoun El-Bahnasawy.", ar: "نياحة القديس لاتصون البهنساوى" } },
      { kind: 'reading', text: { en: "On this day also, the great saint Anba Latsoun of El-Bahnesa, departed. One day, he went to the church and heard the words of the Lord Christ in the Holy Gospel saying: \"For whoever desires to save his life will lose it, but whoever loses his life for My sake will save it. For what advantage is it to a man if he gains the whole world, and is himself destroyed or lost?\" (Luke 9:24-25) These words kindled his heart, so he left the world and went to the wilderness of Scetis (Sheahat). There he fought a great fight with ceaseless fasting and prayers.", ar: "في مثل هذا اليوم تنيح القديس العظيم الأنبا لاتصون من أهل البهنسا وذات يوم دخل الكنيسة فسمع قول السيد المسيح في الإنجيل المقدس &quot; من أراد أن يخلص نفسه يهلكها ومن يهلك نفسه من أجلي يجدها . لأنه ماذا ينتفع الإنسان لو ربح العالم كله وخسر نفسه . أو ماذا يعطي الإنسان فداء عن نفسه (لو 9 : 24 و 25)." } },
      { kind: 'reading', text: { en: "The angel of the Lord appeared to him and commanded him to go to St. Isidore, to clothe him with the holy Eskeem. He went to him, and after forty days St. Isidore clothed him with it. He increased in his asceticism, then he lived a solitary life in the wilderness.", ar: "فلما سمع ذلك التهب قلبه فترك العالم ومضي إلى جبل شيهيت وأجهد نفسه بصلوات متواترة وأصوام كثيرة وظهر له ملاك الرب وأمره أن يمضي إلى القديس ايسيذورس ليلبسه الإسكيم المقدس فذهب اليه وبعد أربعين يوما ألبسه إياه فزاد في نسكه ثم انفرد في البرية وهناك حضر إليه القديس بلامون وذلك أن الشيطان كان قد ظهر للقديس بلامون في شكل امرأة وأخذ يغريه علي الزواج منها ذاكرا بعض رجال العهد القديم الذين كانوا متزوجين ومع ذلك كانوا أبرارا ولكن القديس عرف أنه الشيطان فرسم علي نفسه علامة الصليب وصلي إلى الرب فتحول الشيطان إلى دخان وغاب عنه ، فذهب القديس بلامون إلى القديس لاتصون يسترشده في المحاربات الشيطانية فأرشده إلى كيفية التغلب عليها ورجع الأب بلامون إلى مكانه أما القديس لاتصون فقد ازداد في نسكله وتقشفه حتى تنيح بسلام ." } },
      { kind: 'reading', text: { en: "There, he was visited by St. Balamon (Palaemon). Satan had appeared to him disguised as a woman. Satan tried to persuade him to marry her by mentioning some of the Old Testament men that were married but yet were righteous. St. Balamon realized that he was the devil. He crossed himself with the sign of the cross, and prayed to the Lord to save him. The devil became like smoke and disappeared. St. Balamon went to St. Latsoun to take his advice on devil warfare. He instructed him on how to overcome the devil and his deception. St. Balamon then went back to his abode. As of St. Latsoun, he increased in his asceticism until he departed in peace.", ar: "صلاته تكون معنا . ولربنا المجد دائما . آمين" } },
      { kind: 'reading', text: { en: "May his prayers be with us and Glory be to God forever. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Return of the Relics of the Great St. Mark to the New St. Mark Cathedral.", ar: "عودة رفات القديس مارمرقس" } },
      { kind: 'reading', text: { en: "On this day, of the year 1684 A.M., that coincided with Monday the 24th of June, 1968 A.D., and in the tenth year of the papacy of , the relics of , were . Pope Kyrillos had delegated an official delegation to travel to Rome to receive the relics of St. Mark the Apostle from Pope Paul VI. The papal delegation consisted of ten metropolitans and bishops, seven of them were Coptic and three Ethiopians, and three of the prominent Coptic lay leaders. The Alexandrian delegation received the relics of St. Mark the Apostle on Saturday the 22nd of June, 1968 A.D. from Pope Paul VI. The moment of handing over the holy relics, after eleven centuries, during which the body of St. Mark was kept in the city of Venice, in Italy, was a solemn and joyful moment. The next day, Sunday 16th of Baounah (June 23rd), the Alexandrian Papal delegation celebrated a festive pontifical liturgy in the church of St. Athanasius the Apostolic in Rome. The ten metropolitans, bishops, and the priests accompanying the delegation, all served in the liturgy. Members of the Roman Papal delegation, the Copts who accompanied the Delegation, and those who lived in Rome, newspaper and news agency reporters, and many foreign dignitaries attended the liturgy.", ar: "في مثل هذا اليوم من سنة 1684 للشهداء الأطهار الموافق الاثنين 24 من شهر يونيو سنة 1968 لميلاد المسيح وفي السنة العاشرة لحبرية البابا كيرلس السادس وهو البابا المائة والسادس عشر في سلسلة باباوات الكرسي الإسكندري عاد إلى القاهرة رفات القديس العظيم ناظر الإله الإنجيلي مار مرقس الرسول كاروز الديار المصرية والبطريرك الأول من بطاركة الإسكندرية . وكان البابا كيرلس السادس قد انتدب وفدا رسميا للسفر إلى روما لتسلم رفات القديس مرقس الرسول من البابا بولس السادس . وتألف الوفد من عشرة من المطارنة والأساقفة بينهم ثلاثة من المطارنة الأثيوبيين ومن ثلاثة من كبار أراخنة القبط ." } },
      { kind: 'reading', text: { en: "The Alexandrian Papal delegation carrying the holy relics, on Monday the 24th of June, 1968 A.D., went to the airport in an official procession, preceded by the motorcycles and police escort. They boarded a plane which came especially from Cairo. The plane arrived at Cairo airport at ten thirty P.M. of the same day. Awaiting the arrival of the relics were, Pope Kyrillos the Sixth, Mari Ignatius Yacoub, the Antiochian Patriarch for the Syrian Orthodox, a great number of coptic and foreign bishops, the head of various denominations and religions, Egyptian and foreign, and thousands of the Egyptian masses, Christian and Moslems. They sang and chanted enjoyable religious songs, waiting for the arrival of the plane.", ar: "أما المطارنة والأساقفة فهم حسب أقدمية الرسامة : الأنبا مرقس مطران كرسي أبو تيج وطهطا وطما وتوابعها ، ورئيس الوفد الأنبا ميخائيل مطران كرسي أسيوط وتوابعها ، الأنبا أنطونيوس مطران كرسي سوهاج والمنشاة وتوابعهما والأنبا بطرس مطران كرسي أخميم وساقلته وتوابعهما ، والأنبا يوأنس مطران تيجراي وتوابعها بأثيوبيا ، والأنبا لوكاس مطران كرسي اروسي وتوابعها بأثيوبيا ، والأنبا بطرس مطران كرسي جوندار وتوابعها بأثيوبيا ، والأنبا دوماديوس أسقف كرسي الجيزة وتوابعها ، والأنبا غريغوريوس أسقف عام للدراسات اللاهوتية العليا والثقافة القبطية والبحث العلمي والأنبا بولس أسقف حلوان وتوابعها" } },
      { kind: 'reading', text: { en: "When the plane landed, H.H. Pope Kyrillos went up the stairs of the aircraft, and received the precious box that contained the relics of St. Mark the Apostle, from the head of the delegation. Many, and especially those who were in the balcony of the airport, at this particular moment, saw three white doves flying over the aircraft. Since pigeons do not fly during the night, these were not ordinary pigeons. Perhaps, it was the spirits of the saints welcoming the relics of the great St. Mark. It is worthy to note also that the plane was suppose to arrive at five o'clock but it was delayed for no apparent reason till it was dark. Perhaps also, it was just for the spectators to witness and see these flying doves.", ar: "وطار الوفد البابوي الإسكندري إلى روما في يوم الخميس 13 بؤونه سنة 1684 الموافق 30 من يونيو سنة 1968م في طائرة خاصة أقلتهم ومعهم نحو 90 قبطيا من المرافقين كان من بينهم سبعة من الكهنة وفي الساعة الثانية عشر من يوم السبت الموافق 15 من بؤونة الموافق 22 من يونيو ذهب الوفد البابوي السكندري ومعه أعضاء البعثة البابوية الرومانية في موكب رسمي إلى القصر البابوي بمدينة الفاتيكان وقابلوا البابا بولس السادس وتسلموا منه الرفات المقدس في حفل رسمي كان يجلله الوقار الديني ويتسم بالخشوع والتقوى ولقد كانت لحظة تسلم الرفات المقدس بعد أحد عشر قرنا كان فيها جسد مار مرقس محفوظا في مدينة البندقية ( فينيسيا ) بإيطاليا لحظة رهيبة بقدر ما هي سعيدة ." } },
      { kind: 'reading', text: { en: "The Pope disembarked the aircraft carrying the box on his shoulder in the middle of the chanting and singing of the deacons, followed by a tremendous procession of thousands chanting with the deacons in joy and jubilation. The head of the Roman Papal delegation, Cardinal Doval, Cardinal of Algeria, was amazed by this tremendous religious rally. He also expressed that he was deeply touched by the devoutness of the Copts and their great honor and veneration for St. Mark. He said that what he saw far exceeded his expectations, especially that the masses had to wait from five o'clock P.M., the expected time of arrival of the aircraft, till ten thirty or even later.", ar: "وفي اليوم التالي وهو الأحد 16 بؤونة الموافق 23 يونيو أقام الوفد البابوي السكندري قداسا حبريا احتفاليا بكنيسة القديس أثناسيوس الرسولي بروما خدم فيه جميع المطارنة والأساقفة العشرة والكهنة المرافقون وقد حضر أعضاء البعثة البابوية الرومانية وجميع المرافقين من القبط وعدد كبير من الأقباط المقيمون بروما ومن الأجانب ومندوبي الصحف ووكالات الأنباء وكان قداسا رائعا رفع بروحانية عميقة . وبعد قراءة الإنجيل حمل المطارنة والأساقفة صندوق الرفات المقدس وطافوا به 3 مرات أنحاء الكنيسة ثم بخر المطارنة والأساقفة أمام الرفات بحسب ترتيب أقدمية الرسامة وكان الكهنة والشمامسة يرتلون الألحان المناسبة ." } },
      { kind: 'reading', text: { en: "Pope Kyrillos returned to the old St. Mark Cathedral in El-Azbakiah with the box of the relics. He placed the box on top of the main altar which was consecrated in the name of St. Mark the Apostle. , when the Pope carried it to the new St. Mark Cathedral in its inauguration.", ar: "وعاد الوفد البابوي السكندري ومعه أعضاء البعثة البابوية الرومانية يحملون الرفات المقدس في يوم الاثنين في موكب رسمي تتقدمه الدراجات البخارية إلى المطار . ومن هناك استقلوا طائرة خاصة قامت خصيصا من القاهرة ووصلت إليها في العاشرة والنصف من مساء اليوم نفسه . وكان البابا كيرلس في انتظار وصول الرفات وكان يصحبه مار أغناطيوس يعقوب الثالث بطريرك إنطاكية وسائر المشرق للسريان الأرثوذكس وعدد كبير من المطارنة والأساقفة الأقباط والأجانب ورؤساء الطوائف والأديان مصريين وأجانب وألوف من أفراد الشعب مسيحيين ومسلمين يرتلون وينشدون أحلي الأناشيد الدينية وكان المطار كله يدوي بالترانيم وعند مارست الطائرة صعد البابا إلى سلم الطائرة وتسلم من يد رئيس الوفد الصندوق الثمين الذي يحمل رفات مار مرقس الرسول وفي هذه اللحظة رأي الكثيرون وخاصة المطلون من شرفات المطار ثلاث حمامات بيضاء ناصعة البياض حلقت فوق الطائرة ولما كان الحمام لا يطير في هذا الوقت من الليل فلم يكن هذا أذن بحمام عادي ولعله أرواح القديسين ترحب برفات القديس العظيم مار مرقس" } },
      { kind: 'reading', text: { en: "May the blessings of St. Mark be with us all. Amen.", ar: "ونزل البابا كيرلس يحمل صندوق الرفات علي كتفه بين ترتيل الشمامسة ويتبعه موكب ضخم من كتل بشرية تعد بالألوف يرنمون مع الشمامسة فرحين متهللين حتى أن رئيس البعثة البابوية الرومانية ذهل من تلك المظاهرة الدينية الكبيرة وأعرب عن تأثره البالغ بتدين الأقباط وعظيم إجلالهم وإكبارهم للقديس مرقس وقال أن ما رآه فاق كل تقديره فما كان يتوقع بتاتا أن يكون استقبال رفات مار مرقس بهذه الحماسة الروحية البالغة خاصة وان الجماهير ظلت منتظره بالمطار منذ الخامسة مساء - حيث كان مقررا وصول الطائرة - إلى الساعة الحادية عشرة مساء أو يزيد ." } },
      { kind: 'reading', text: { en: "", ar: "وعاد البابا في سيارته ومعه صندوق الرفات إلى الكاتدرائية المرقسية الكبرى القديمة بالأزبكية ووضع الصندوق علي المذبح الكبير المدشن باسم مار مرقس وظل الصندوق هناك إلى اليوم الثالث لوصوله . وفي صباح يوم الأربعاء 19 بؤونة الموافق 26 يونيو في نحو السادسة صباحا حمل البابا صندوق الرفات وأتي به في سيارته الخاصة إلى دير الأنبا رويس الذي كان يعرف بدير الخندق والمقامة علي أرضه الكاتدرائية المرقسية الجديدة التي افتتحها البابا كيرلس بحضور الرئيس جمال عبد الناصر رئيس جمهورية مصر العربية والإمبراطور هيلاسلاسي الأول إمبراطور أثيوبيا في اليوم السابق مباشرة وأعني به الثلاثاء 18 بؤونة الموافق 15 يونيو وقد وضع البابا رفات مار مرقس علي مائدة في منتصف شرقية هيكل الكاتدرائية الجديدة . وظل كذلك طوال مدة القداس الحبري الحافل الذي رأسه البابا كيرلس السادس واشترك معه البطريرك مار أغناطيوس يعقوب الثالث بطريرك إنطاكية وسائر المشرق للسريان الأرثوذكس وعدد من مطارنة السريان والهنود والأرمن الأرثوذكس وحضر القداس الإلهي جلالة هيلاسلاسي الأول إمبراطور أثيوبيا وعدد كبير من رؤساء الأديان ومندوبي الكنائس والطوائف من مختلف بلاد العالم وعدد من أفراد الشعب يزيد علي ستة آلاف نسمة . وبعد القداس نزل البابا في موكب رسمي يحمل صندوق الرفات إلى المزار الجميل المعد له تحت الهيكل الكبير ووضع الصندوق في جسم المذبح الرخامي القائم في وسط المزار وغطي بغطاء رخامي ومن فوقه مائدة المذبح وأنشدت فرق مختلفة ألحانا مناسبة تحية لمار مرقس بسبع لغات مختلفة أي بالقبطية والأثيوبية ، والسريانية ، والأرمنية واليونانية واللاتينية والعربية وكان يوما سعيدا من أسعد الأيام التي شهدتها مصر وكنيسة الإسكندرية والكرازة المرقسية ." } },
      { kind: 'reading', text: { en: "", ar: "بركة مار مرقس الرسول تشمل الجميع ، آمين" } }
    ],
  },
  {
    id: "synax-baouna-18",
    title: { en: "Baouna 18", ar: "18 بؤونه" },
    blocks: [
      { kind: 'heading', text: { en: "The Departure of St. Damianos, 35th Pope of Alexandria.", ar: "نياحة البابا داميانوس ال 35" } },
      { kind: 'reading', text: { en: "On this day also, of the year 321 A.M. (June 25th, 605 A.D.) St. Damianos, 35th Pope of Alexandria, departed. He became a monk in his early years in the desert of Scete. He continued to fight and to devote himself to God for sixteen years. He was ordained a deacon in the monastery of . Then he went to the monastery of the fathers which is to the west of Alexandria, and there he increased his asceticism.", ar: "في مثل هذا اليوم من سنة 321 ش 12 يونيو سنة 605 م تنيح البابا القديس داميانوس البطريرك الخامس والثلاثين من باباوات الكرازة المرقسية وقد كان منذ حداثته في برية شيهيت فلبث عابدا مجاهدا ست عشرة سنة ورسم شماسا بدير القديس يوحنا القصير ثم ذهب إلى دير الآباء غربي مدينة الإسكندرية وهناك زاد في نسكه ." } },
      { kind: 'reading', text: { en: "When Pope Peter (34) was enthroned on the See of St. Mark, he brought and appointed Damianos a private secretary. Damianos pursued a good course of life and everyone loved him. When Pope Peter departed, the bishop unanimously agreed to ordain him a patriarch. He was enthroned a patriarch on the 285 A.M. (June 26th, 569 A.D.). He cared for his flock well and he wrote many epistles and discourses.", ar: "ولما جلس البابا بطرس الرابع والثلاثين علي كرسي الكرازة المرقسية استحضره وجعله كاتما لسره فسار سيرة حسنة حتى أحبه الجميع ولذا فانه لما تنيح البابا بطرس اتفق رأي الأساقفة علي رسامته بطريركا فأعتلي كرسي البطريركية في 2 أبيب سنة 285 ش ( 26 يونيو سنة 569م ) واحسن الرعاية وكتب رسائل وميامر كثيرة ." } },
      { kind: 'reading', text: { en: "In the wilderness of Scete, there were some followers of Melitius El-Assyuty, who drank wine a few times during the night before they intended to partake of the Holy Communion. They claimed that the Lord Christ gave to His disciples two cups: the first He did not say, \"This is My Blood\" but when he gave them the second cup he said, \"This is My Blood.\" St. Damianos showed them their error. He clarified to them that the first cup was the cup of the Jewish passover, and He nullified it with the second cup. He also told them that the canons of the church ban those that eat before communion from partaking of the Holy Eucharist. Some of them turned from their evil, but those that did not turn from their evil council were driven out of the wilderness.", ar: "وكان ببرية الاسقيط بعض اتباع مليتيوس الاسيوطي الذين كانوا يشربون الخمر عدة مرات أثناء الليل إذا عزموا في صباحه علي التقرب من الأسرار زاعمين ان السيد المسيح ناول تلاميذه كآسين الأول لم يقل عنها هذا دمي وفي الثانية قال هذا دمي . فبين لهم القديس داميانوس غلطهم وكشف له خطاهم وأبان أن الكأس الأولي كانت كأس الفصح اليهودي وقد أبطلها بالكأس الثانية وان القوانين الكنسية تمنع من يذوق شيئا قبل التناول من أن يتقدم إلى السر المقدس فرجع البعض وأما الذين لم يرجعوا عن سوء رأيهم فقد طردهم من البرية ." } },
      { kind: 'reading', text: { en: "When Anba Theophanius, the Antiochian Patriarch departed, they ordained a successor to him called Peter, who sent a letter to Pope Damianos which said, \"There is no need for us to say that God is the three Persons.\" When Pope Damianos read this letter he became enkindled with zeal. He wrote him a letter which explained that God is, in no doubt, one in His Godhead, one in essence, but He is Three persons, God the Father, God the Son, God the Holy Spirit, One God. He wrote to him many testimonies from the Holy Scriptures and from the sayings of the holy fathers. Nevertheless, Peter refused to return to the truth, and insisted on his error. Pope Damianos ordered that his name not be mentioned in the Divine Liturgy for twenty years until the heretic died.", ar: "ولما تنيح البابا ثاؤفانيوس بطريرك إنطاكية رسموا خلفا له يدعي بطرس وكان غليظ القلب مظلما في أفكاره فكتب رسالة إلى البابا داميانوس يقول له فيها : انه لا ضرورة تستدعي القول بان الله هو ثلاثة أقانيم . فلما وقف عليها البابا داميانوس اتقد غيرة وكتب له رسالة بين فيها أن الله وان كان بلا شك واحدا في جوهره وذاته ألا أنه واحد موصوف بثلاثة أقانيم طبيعة واحدة ، لاهوت واحد ، واستشهد علي ذلك بأقوال كثيرين من الأباء القديسين ولكن بطرس هذا لم يرد أن يهتدي إلى الحق وأصر علي عناده فأمر البابا داميانوس بعدم ذكره في القداس مدة عشرين سنة حتى مات هذا المجدف ." } },
      { kind: 'reading', text: { en: "Pope Damianos remained for thirty five years, eleven month, and sixteen days, teaching and preaching to his flock. He departed at a good old age.", ar: "وقضي البابا داميانوس خمسا وثلاثين سنة واحد عشر شهرا وستة عشر يوما يعلم ويعظ رعيته وتنيح في شيخوخة صالحة ." } },
      { kind: 'reading', text: { en: "May his prayers be with us and Glory be to God forever. Amen.", ar: "صلاته تكون معنا . ولربنا المجد دائما . آمين ." } },
      { kind: 'heading', text: { en: "The Inauguration of the New St. Mark Cathedral in the Monastery of Anba Rowais.", ar: "افتتاح الكاتدرائية المرقسية الجديدة بدير الأنبا رويس" } },
      { kind: 'reading', text: { en: "On this day, of the year 1684 A.M., that coincided with Tuesday the 25th of June, 1968 A.D., and in the tenth year of the papacy of , the holy church celebrates the inauguration of the new St. Mark Cathedral in Dair El-Anba Rowais, which was known also as Dair El-Khandaq.", ar: "في مثل هذا اليوم من عام 1684 للشهداء الأطهار الموافق الثلاثاء 25 من يونيو عام 1968 وفي السنة العاشرة لحبرية البابا كيرلس السادس وهو المائة والسادس عشر في سلسلة باباوات الكرسي المرقسي السكندري - احتفلت الكنيسة المقدسة بافتتاح الكاتدرائية المرقسية الجديدة القائمة بدير الأنبا رويس الذي كان يعرف أيضا بدير الخندق ." } },
      { kind: 'reading', text: { en: "For this occasion and for the of from Rome, after being in the city of Venice in Italy for eleven centuries, i.e. since the ninth century, . The celebration was headed by H.H. Pope Kyrillos the Sixth and was attended by President Gamal Abdel Naser, President of the Arab Republic of Egypt, Emperor Haile Selassie the First, Emperor of Ethiopia, and many of the heads of different religions and representatives of churches from all around the world. Among those religious leaders was Mari Ignatius Yacoub the Third, the Antiochian Patriarch for the Syrian Orthodox.", ar: "وقد أقيم لهذه المناسبة ولمناسبة عودة رفات القديس مرقس الرسول من روما بعد أن ظل في مدينة البندقية بإيطاليا أحد عشر قرنا أي منذ القرن التاسع للميلاد - احتفال ديني كبير رأسه البابا كيرلس السادس وشهده الرئيس جمال عبد الناصر رئيس جمهورية مصر العربية والإمبراطور هيلاسلاسي الأول إمبراطور أثيوبيا وعدد كبير من رؤساء الأديان ومندوبي الكنائس في كل العالم كان من بينهم البطريرك مار أغناطيوس يعقوب الثالث بطريرك إنطاكية وسائر المشرق للسريان الأرثوذكس ." } },
      { kind: 'reading', text: { en: "Many momentous speeches, were delivered in different languages for this occasion. The speakers were, Pope Kyrillos the Sixth, the Patriarch of the Syrian Orthodox, Cardinal Doval, the head of the Roman Papal delegation, the Catholicos Patriarch of Ethiopia, the secretary general of the World Council of Churches, and the Patriarch of Moscow and all Russia. They all expressed their joy on this happy and blessed day, saluting the church of Alexandria, which had a glorious history, with salutation of appreciation and respect.", ar: "وقد ألقيت كلمات هامة وبلغات مختلفة لهذه المناسبة من البابا كيرلس السادس ومن بطريرك السريان الأرثوذكس ومن الكاردينال دوفال رئيس البعثة الباباوية الرومانية وبطريرك جاثليق أثيوبيا والسكرتير العام لمجلس الكنائس العالمي وبطريرك موسكو وكل روسيا وقد عبر الكل عن فرحتهم بهذا اليوم السعيد وحيوا كنيسة الإسكندرية ذات التاريخ المجيد تحية تقدير وإكبار" } },
      { kind: 'reading', text: { en: "At the end of the speeches the Pope along with the President of Egypt and the Emperor of Ethiopia went to the entrance of the new Cathedral. They unveiled the curtains from the commemorative plaque that was prepared to perpetuate this historical day.", ar: "وفي نهاية الكلمات انتقل البابا ومعه رئيس الجمهورية وإمبراطور أثيوبيا إلى مدخل الكاتدرائية الجديدة وأزاحوا الستار عن اللوحة التذكارية التي أقيمت تخليدا لهذا اليوم التاريخي ." } },
      { kind: 'reading', text: { en: "This celebration was attended by the journalists, the international news agencies' reporters, radio, television and more than six thousand Egyptians and foreigners.", ar: "وقد شهد الحفل الصحفيون ومندوبو وكالات الأنباء العالمية والإذاعة والتليفزيون فضلا عن ستة آلاف بين مصريين وأجانب." } },
      { kind: 'reading', text: { en: "May the blessings of St. Mark be with us all. Amen.", ar: "بركة مار مرقس تشمل الجميع . آمين" } }
    ],
  },
  {
    id: "synax-baouna-19",
    title: { en: "Baouna 19", ar: "19 بؤونه" },
    blocks: [
      { kind: 'heading', text: { en: "The Martyrdom of St. George (Girgis) known as El-Mezahem.", ar: "استشهاد القديس جرجس المزاحم" } },
      { kind: 'reading', text: { en: "This day also, in the year 675 A.M. (June, 959 A.D.), marks the martyrdom of St. George, the new martyr, known as El-Mezahem. His father was a Moslem bedouin. He married a Christian woman from the city of Demerah El-kibliah. He had from her three sons, one of them was this Saint, and they called him El-Mezahem.", ar: "في مثل هذا اليوم من سنة 675 ش ( 13 يونيو سنة 959 م ) استشهد القديس جرجس الجديد المعروف بالمزاحم كان أبوه مسلما بدويا متزوجا من امرأة مسيحية من أهل دميرة القبلية ورزق منها بثلاثة بنين أحدهم هذا القديس فسموه &quot; مزاحم &quot; وكان يتردد مع والدته علي الكنيسة منذ حداثته فرأي أولاد المسيحيين يلبسون ملابس بيضاء في أيام تناولهم الأسرار المقدسة فاشتاق أن تلبسه أمه مثلهم وتسمح له أن يأكل مما يأكلونه في الهيكل فعرفته أن هذا لا يكون إلا إذا تعمد وأعطته لقمة بركة من القربان الذي يوزعونه علي الشعب فصارت في فمه كالعسل فقال في نفسه &quot; إذا كان طعم القربان الذي لم يقدس بالصلاة حلوا بهذا المقدار فكيف يكون طعم القربان المقدس ؟ &quot; وأخذ شوقه يزداد إلى الإيمان بالمسيح منذ ذلك الحين ." } },
      { kind: 'reading', text: { en: "He used to go with his mother to the church at a young age. He also used to see the children of the Christians dress in white on the days that they partook of the Holy Mysteries. He longed that his mother would dress him like them, and allow him to eat from whatever they ate at the altar. His mother told him that could not be, unless he was baptized. She gave him a portion of the blessed Eulogia bread, that they distributed to the people, and it tasted in his mouth like that of honey. He meditated in his heart and said, \"If the taste of this bread that was not consecrated by prayers tastes like this, what will be the taste of the Offering?\" His longing for the faith in Christ increased from that time.", ar: "ولما كبر تزوج امرأة مسيحية وأعلمها أنه يريد أن يصير مسيحيا فأشارت عليه أن يعتمد أولا . فمضي إلى برما ولما اشتهر أمره أتي إلى دمياط واعتمد وتسمي باسم جرجس وعرفه المسلمون فقبضوا عليه وعذبوه فتخلص منهم وذهب إلى صفط أبي تراب حيث أقام بها ثلاث سنوات . ولما عرف أمره ذهب إلى قطور ولبث بها يخدم كنيسة القديس مار جرجس ثم عاد إلى دميرة وسمع بها يخدم كنيسة القديس مار جرجس ثم عاد إلى دميرة وسمع به الملمون فأسلموه للوالي فأودعه السجن فاجتمع المسلمون وكسروا باب السجن وضربوه فشجوا رأسه وتركوه بين الحياة والموت ولما أتي بعض المؤمنين في الغد ليدفنوه ظنا منهم أنه مات وجدوه حيا . وعقد المسلمون مجلسا وهددوه فل يرجع عن رأيه فعلقوه علي صاري مركب ولكن القاضي أنزله وأودعه السجن وكانت زوجة هذا القديس تصبره وتعزيه وتعلمه بأن الذي حل به من العذاب إنما هو من أجل خطاياه لئلا يغريه الشيطان فيفتخر أنه صار مثل الشهداء وظهر له ملاك الرب وعزاه وقواه وأنبأه بأنه سينال إكليل الشهادة في اليوم التالي . وفي الصباح اجتمع المسلمون عند الوالي وطلبوا منه قطع رأسه فسلمه لهم فأخذوه وقطعوا رأسه عند كنيسة الملاك ميخائيل بدميرة وطرحوه في نار متقدة مدة يوم وليلة . وأذ لم يحترق جسده وضعوه في برميل وطرحوه في البحر وبتدبير الله رسا إلى جزيرة بها امرأة مؤمنة فأخذته وكفنته وخبأته في منزلها إلى أن بنوا له كنيسة ووضعوه فيها شفاعته تكون معنا . آمين" } },
      { kind: 'reading', text: { en: "When he grew up, he married a Christian woman, and he told her that he wished to become a Christian. She told him that he had to be baptized. He went to Birma, was baptized there and was called George (Girgis). When this matter became known, he went to Domiat. The Moslems there recognized him, seized him and tortured him. Then he escaped and fled to the city of Saft Abu-Trab, where he stayed for three years. When his matter became known again he went to the city of Katurah, and remained there serving the church of St. George, then went back to Demerah. When the Moslems of the city of Demerah knew his history, they seized him, and delivered him to the governor who put him in prison. The Moslems assembled and broke the door of the prison. They beat the Saint severely, split open his head, and left him between life and death. When some of the believers came on the morrow to bury him, for they thought that he was dead, they found him alive. The Moslems convened a council, and threatened him, but he did not change his conviction. They hung him up on the mast of a ship, but the governor ordered that he be taken down and cast him up in prison.", ar: "" } },
      { kind: 'reading', text: { en: "His wife strengthened him, and comforted him. She taught him to believe that the punishment which had come upon him was because of his sins; lest Satan lead him astray and he might boast that he became like the martyrs. The angel of the Lord appeared to him, comforted him, strengthened him, and informed him that he would receive the crown of martyrdom on the next day. On the next morning, the Moslems gathered with the governor and demanded from him that the head of El-Mozahem be cut off. He handed him over to them. They took him, and cut off his head near the church of the angel Michael in the city of Demerah. They cast his body in hot fire for a day and a night. But his body did not burn, so they put him in a barrel and threw him into the river. By the Will of God the barrel landed on the shore of an island, which was inhabited by a believing woman. She took his body, shrouded him, hid him in her house until they built a church for him, in which they laid his body.", ar: "" } },
      { kind: 'reading', text: { en: "May his intercession be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Martyrdom of St. Bishai Anoub.", ar: "استشهاد القديس بشاى انوب الدمياطى في انصنا" } },
      { kind: 'reading', text: { en: "On this day also, St. Bishai Anoub, which means \"fine gold\", was martyred. He was from the city of Banios, in the diocese of Domiat. He was one of the soldiers of Cyprianus, governor of Athribis. When persecution was incited against the Christians, he went to the governor and confessed his faith in the Lord Christ before him. The governor tortured him, then sent him to the governor of Ansena (Antinoe). St. Bishai openly declared his faith in Christ before , the governor of Ansena, who tortured him severely. Finally, he ordered his head cut off outside the city. A great multitude followed him outside of the city. One of them, was the keeper of the lions of Arianus, the governor, and he had with him two lions bound with chains. One of them rushed forward, broke the chain, and attacked the Saint to devour him. Immediately, the angel of the Lord appeared, took the Saint and brought him to the city of Ain-Shams where his martyrdom was consummated.", ar: "في مثل هذا اليوم استشهد القديس بشاي أنوب الذي تفسيره &quot; ذهب الطلاء &quot; كان من بلدة تسمي بانايوس من كرسي دمياط وكان من جند قبريانوس والي أتريب ولما ثار الاضطهاد علي المسيحيين تقدم إلى الوالي وأعترف أمامه بالسيد المسيح فعذبه ثم أرسله إلى أنصنا فجاهر أمام واليها أريانا بالمسيح فعذبه كثيرا وأخيرا أمر بقطع رأسه خارج المدينة فخرج خلفه جمهور كثير وكان من جملتهم مروض سباع أريانا الوالي ومعه أسدان مقيدان بالسلاسل فقطع أسد منهما السلسلة ووثب علي القديس ليفترسه ففي الحال ظهر ملاك الرب وأخذ القديس وأتي به إلى مدينة عين شمس وهناك كملت شهادته ." } },
      { kind: 'reading', text: { en: "May his prayers be with us and Glory be to God forever. Amen.", ar: "صلاته تكون معنا ولربنا المجد دائما . آمين" } },
      { kind: 'heading', text: { en: "The First Pontifical Liturgy in the New St. Mark Cathedral in the Monastery of Anba Rowais.", ar: "إقامة \r\nأول قداس حبري بالكاتدرائية المرقسية الجديدة بدير الأنبا رويس" } },
      { kind: 'reading', text: { en: "On this day, of the year 1684 (Wednesday, June 26th, 1968), the church celebrated the first Pontifical Liturgy in the new St. Mark Cathedral in the monastery of Anba Rowais, which was known as Dair El-Khandaq, where the relics of were placed after his return from Venice and Rome.", ar: "في مثل هذا اليوم من عام 1684 للشهداء الأطهار الموافق الأربعاء 26 من يونيو سنة 1968 احتفلت الكنيسة بيوم افتتاح الكاتدرائية المرقسية الجديدة المقامة بدير الأنبا رويس المعروف قديما بدير الخندق والتي وضع فيها رفات القديس مار مرقس بعد عودته من البندقية وروما" } },
      { kind: 'reading', text: { en: "On the morning of Wednesday the 19th of Baounah (June 26th) at about six o'clock, took the box of the relics of St. Mark, that he had placed on the altar of the old St. Mark Cathedral in El-Azbakiah upon its arrival. He brought it in his private car to the new St. Mark Cathedral.", ar: "ولهذه المناسبة أقيم في ذلك اليوم قاس حبري حافل رأسه البابا كيرلس السادس واشترك معه البطريرك مار أغناطيوس يعقوب الثالث بطريرك إنطاكية وسائر المشرق للسريان الأرثوذكس وعدد من مطارنة السريان والهند والأرمن الأرثوذكس وحضره الإمبراطور هيلاسلاسي الأول إمبراطور أثيوبيا والكردينال دوفال رئيس البعثة الباباوية الرومانية وكثيرون من رؤساء الأديان والمطارنة والأساقفة ورجال الدين مصريين و أجانب من مختلف بلاد العالم وعدد غفير من الشعب نحو ستة آلاف نسمة ." } },
      { kind: 'reading', text: { en: "The Pontifical Divine Liturgy that was celebrated on this occasion was headed by H.H. Pope Kyrillos the Sixth, and participating with him were the patriarch Mari Ignatius Yacoub the Third, the Antiochian Patriarch for the Syrian Orthodox, and a number of Syrian, Indian and Armenian Orthodox bishops. This celebration was attended by Emperor Haile Selassie the First, Emperor of Ethiopia, Cardinal Doval, the head of the Roman Papal delegation and Cardinal of Algeria, many of the heads of different religions and representatives of churches from all around the world, and more than six thousand Egyptians and foreigners.", ar: "وأثناء القداس كان الصندوق الذي يحوى رفات مار مرقس الرسول موضوعا علي مائدة في منتصف شرقية هيكل الكاتدرائية وظل هناك طوال القداس وما أن انتهي القداس حتى نزل البابا كيرلس يحمل صندوق الرفات ومعه الإمبراطور وبطريرك السريان الأرثوذكس ورؤساء الكنائس في موكب كبير اتجه إلى مزار القديس مرقس المعد له تحت المذبح الرئيس ، وأودع الصندوق في المزار في داخل المذبح الرخامي وغطي بلوحة رخامية كبيرة وعليها مائدة المذبح وهنا أنشدت فرق التراتيل بالتتابع ألحانا مناسبة بلغات مختلفة تحية لمار مرقس الرسول باللغات القبطية والأثيوبية والسريانية والأرمنية واليونانية واللاتينية والعربية فكان يوما بهيجا من أسعد أيام كنيسة الإسكندرية" } },
      { kind: 'reading', text: { en: "During the Liturgy, the box that contained the was placed on a table in the middle of the eastern part of the altar of the Cathedral, and remained there till the end of the liturgy. Right after the liturgy, Pope Kyrillos went down carrying the box along with the Emperor, the Syrian Orthodox Patriarch and the heads of the churches in a magnificent procession. They went to the sanctuary that was prepared for St. Mark under the main altar of the Cathedral. Pope Kyrillos placed the box inside the marbled altar, which was covered by a large marble slab and on it was the altar table.", ar: "بركة مار مرقس الرسول تشمل الجميع . آمين" } },
      { kind: 'reading', text: { en: "The different choral groups then sang, successively in different languages, songs and hymns that befit the occasion in salutation for St. Mark. They sang in Coptic, Ethiopian, Syrian, Armenian, Greek, Latin, and in Arabic. The day was a joyous day and one of the most blessed days in the history of the church of Alexandria.", ar: "" } },
      { kind: 'reading', text: { en: "May the blessings of St. Mark be with us all. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of Pope Archelaus, the Eighteenth Pope of Alexandria.", ar: "نياحة البابا أشيلاوس البطريرك الثامن عشر" } },
      { kind: 'reading', text: { en: "On this day also, of the year 28 A.M. (June, 312 A.D.) Pope Archelaus, the Eighteenth Pope of Alexandria, departed. He was a priest in the church of Alexandria. When Pope Peter the first, the seal of martyrs, received the crown of martyrdom, the believers in Alexandria agreed and gathered the bishops. They ordained Archelaus the priest a Patriarch instead of Pope Peter,as he commended before his departure from this world. When he was enthroned on the patriarchal chair in the 19th of Kiahk, 28 A.M. (December 24th, 311 A.D.), a group of people came to him and asked him to accept Arius in the church. He accepted their petition against the command of his father Pope Peter, but he did not remain on the Chair longer than six months, then departed.", ar: "في مثل هذا اليوم من سنة 28 ش 23 يونيو سنة 312 م تنيح البابا أرشيلاوس البطريرك الثامن عشر وقد كان قسا في كنيسة الإسكندرية ولما نال البابا بطرس الأول خاتم الشهداء إكليل الشهادة اتفق المؤمنون بالإسكندرية وجمعوا الأساقفة ورسموا أرشيلاوس القس بطريركا عوضا عنه كما كان قد أوصي قبل انتقاله من هذا العالم فلما جلس علي الكرسي البطريركي في 19 كيهك سنة 28 ش ( 24 ديسمبر سنة 311 م ) تقدم إليه جماعة من الشعب وطلبوا منه قبول أريوس فقبل سؤالهم ورسمه شماسا . ولما قبله وخالف وصية أبيه بطرس لم يقم علي الكرسي سوي ستة شهور وتنيح صلاته تكون معنا . آمين" } },
      { kind: 'reading', text: { en: "May his prayers be with us. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baouna-20",
    title: { en: "Baouna 20", ar: "20 بؤونه" },
    blocks: [
      { kind: 'heading', text: { en: "The Departure of Elisha, the Prophet.", ar: "نياحة القديس اليشع النبى" } },
      { kind: 'reading', text: { en: "On this day, of the year 3195 of the world, the holy prophet Elisha, departed. This prophet was born in one of the villages of Israel called Alamut. His father's name was Shaphat. Elisha was a servant to the . When the Lord would take up Elijah the prophet into heaven, he went with him to the river Jordan. Elijah said to Elisha, \"Ask what I shall do for you, before I be taken away from you.\" Elisha asked, \"I pray you, let a double portion of your spirit be upon me,\" and it was as he asked. (2 Kings 2:1-18)", ar: "في هذا اليوم من سنة 3195 للعالم تنيح القديس اليشع النبي ولد هذا النبي في إحدى قري إسرائيل اسمها علموت واسم أبيه شافاط وكان خادما للقديس ايليا النبي . ولما كان وقت صعود ايليا النبي إلى السماء مضي معه إلى الأردن وقال له ايليا سلني ما شئت فطلب أن تتضاعف روحه عليه وكان كذلك فحلت عليه روح ايليا مضاعفة ." } },
      { kind: 'reading', text: { en: "Elisha divided the river and passed through it. Then he went to Jericho and went up from there to Bethel; and as he was going up the road, some youths came from the city and mocked him, and said to him, \"Go up, you baldhead! Go up, you baldhead!\" So he turned around and looked at them, and pronounced a curse on them in the name of the LORD. And two female bears came out of the woods and mauled forty-two of the youths. (2 Kings 2:23-24)", ar: "وقد شق البحر وعبره . ولما دخل أريحا وخرج منها تبعه صبية وكانوا يهزأون به فالتفت إليهم ولعنهم فخرجت دبتان من الوعر افترستا منهم اثنين وأربعين ولدا واشتكت له زوجة أحد الأنبياء أن زوجها مات وعليه دين والآن يلح في طلبه ولما علم أن عندها قليلا من الزيت طلب منها أن تستعير أوعية فارغة كثيرة علي قدر استطاعتها وبصلاته بارك الرب الزيت فامتلأت كل الأوعية ثم باعت منه المرأة وسددت دينها كما أقام ابن الشونمية من الموت ولما قصده نعمان السرياني أبرأه من برصه فقدم له أموالا كثيرة وثيابا مذهبة فلم يقبلها ولما أخذها تلميذه جيحزي لنفسه وعلم النبي بذلك بالروح غضب عليه فبرص هو وبنوه وكل نسله وصنع أليشع آيات أخري كثيرة وقد مكث يتنبأ نحو الخمسين سنة ولما توفي ووضع في قبر اتفق أن قوما أتوا بميت ووضعوه في هذا القبر فلما مس جسد هذا النبي عادت إلى الميت الحياة ورجع إلى أهله .صلاته تكون معنا . ولربنا المجد دائما . آمين" } },
      { kind: 'reading', text: { en: "A certain woman of the wives of the sons of the prophets cried out to Elisha, saying, \"Your servant my husband is dead, and the creditor is coming to take my two sons to be his slaves.\" So Elisha said to her, \"What shall I do for you? Tell me, what do you have in the house?\" And she said, \"Your maidservant has nothing in the house but a jar of oil.\" Then he said, \"Go, borrow vessels from everywhere, from all your neighbors; empty vessels; do not gather just a few.\" With his prayers the Lord blessed the oil and all the vessels became full. The woman sold the oil and paid off her debt. (2 Kings 4:1-7) He also raised the son of the Shunammite woman from the dead.", ar: "" } },
      { kind: 'reading', text: { en: "When Naaman the Syrian came to him, he healed him from his leprosy. Naaman offered him much money and costly clothes, but he refused them. Nevertheless, when his servant Gehazi took them for himself, the prophet knew that by the spirit. Elisha became angry and told him, \"Therefore the leprosy of Naaman shall cling to you and your descendants forever.\"", ar: "" } },
      { kind: 'reading', text: { en: "Elisha had performed many signs and miracles. He prophesied for about fifty years. When Elisha died, they buried him. And the raiding bands from Moab invaded the land in the spring of the year. So it was, as they were burying a man, a plundering band was seen, and they cast the man in the tomb of Elisha; and when the man was let down and touched the bones of Elisha, he revived, stood on his feet, and went back to his people. (2 Kings 13:20-21)", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us and Glory be to God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baouna-21",
    title: { en: "Baouna 21", ar: "21 بؤونه" },
    blocks: [
      { kind: 'heading', text: { en: "The Commemoration of the First Church for The Virgin Mary in the city of Philippi.", ar: "تذكار اول كنيسة والدة الاله القديسة مريم العذراء بفيلبى" } },
      { kind: 'reading', text: { en: "On this day, the church celebrates the commemoration of the first church to be built in the name of the Virgin Lady, the All pure St. Mary, the Theotokos (Mother of God), through whom the salvation of Adam and his posterity was fulfilled. When the two apostles Paul and Silas preached among the gentiles, many believed of them in the city of Philippi. They built a church there in the name of the Virgin, the Mother of God, and its consecration was on that day. It is meet for us to celebrate for her a spiritual festival, for she has borne the Savior of the world.", ar: "في هذا اليوم تعيد الكنيسة بتذكار بناء أول كنيسة علي اسم البتول كلية الطهر السيدة مريم والدة الإله التي كان بواسطتها خلاص آدم ونسله وذلك أنه لما بشر الرسولان بولس وبرنابا بين الأمم آمن كثيرون منهم بمدينة فيلبي وبنوا فيها كنيسة علي اسم البتول والدة الإله . وصار تكريسها في مثل هذا اليوم ولذا يجب علينا أن نعيد لها عيدا روحيا لأنها ولدت مخلص المسكونة .شفاعتها تكون معنا . آمين" } },
      { kind: 'reading', text: { en: "May her intercession be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Martyrdom of St. Timothy of Memphis (El-Masry).", ar: "استشهاد القديس تيموثاؤس المصري" } },
      { kind: 'reading', text: { en: "On this day also, St. Timothy of Memphis (El-Masry) was martyred. He was one of the soldiers of , governor of the city of Ansena. When he read the Edict of the Emperor Diocletian, which commanded the worship of idols, this soldier rose up in the middle of the people, seized the Edict, and tore it up saying, \"There is no God except Jesus Christ the Son of the Living God.\" The Governor became enraged. He seized Timothy by the hair of his head, and cast him down on the ground. He commanded him to be beaten until his flesh was mangled. The Saint cried out, saying, \"O my Lord Jesus Christ, help me for there is no God but You.\" God considered his endurance, and sent His angel, who healed his wounds. The Saint returned to the Governor crying, \"There is no God except Jesus Christ the Son of the Living God.\" The Governor tortured him severely again, and finally he cut off his head and thus St. Timothy received the crown of martyrdom.", ar: "في مثل هذا اليوم استشهد القديس تيموثاؤس الذي من مصر القديمة كان من أجناد أريانا والي أنصنا ولما صدر أمر دقلديانوس بعبادة الأوثان وثب هذا الجندي في وسط الجمع وأخذ الأمر ومزقه قائلا &quot; ليس اله إلا يسوع المسيح ابن الله الحي &quot; فغضب الوالي وأمسكه من شعره وطرحه إلى الأرض وأمر بضربه حتى تهرأ لحمه وكان يصرخ قائلا : &quot; يا سيدي يسوع المسيح أعني . فليس اله ألا أنت &quot; فنظر الرب إلى صبره وأرسل ملاكه فشفاه فعاد إلى الوالي وهو يصيح : &quot; ليس اله إلا يسوع المسيح ابن الله الحي &quot; فشدد عليه العذاب وأخيرا قطع رأسه فنال إكليل الشهادة . صلاته تكون معنا . آمين" } },
      { kind: 'reading', text: { en: "May his prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of St. Cedron (Kardonos), the Fourth Patriarch of Alexandria.", ar: "نياحة البابا القديس كردونوس الرابع من باباوات الكرازة المرقسية" } },
      { kind: 'reading', text: { en: "This day also (June 15th, 106 A.D.) marks the departure of St. Cedron (Kardonos), the Fourth Patriarch of Alexandria. This father was baptized by the hand of of the land of Egypt. He learned the doctrines and the books of the Church. After the departure of Pope Melius, he was ordained a Pope for the See of St. Mark in the (September 5th, 95 A.D.). He shepherded his people with the best of care, by preaching, teaching, and instructing them for eleven years, one month, and twelve days, then departed in peace.", ar: "في مثل هذا اليوم ( 15 يونية سنة 106 م ) تنيح البابا القديس كردونوس الرابع من باباوات الكرازة المرقسية وقد تعمد هذا الأب من يد القديس مرقس الرسول كاروز الديار المصرية . وتعلم علوم الكنيسة وبعد نياحة البابا ميليوس رسم بابا للكرسي المرقسي في 7 توت ( 5 سبتمبر سنة 95 م ) فرعي شعبه أحسن رعاية بالوعظ والتعليم والإرشاد مدة إحدى عشرة سنة وشهرا واثني عشر يوما وتنيح بسلام صلاته تكون معنا . ولربنا المجد دائما . آمين" } },
      { kind: 'reading', text: { en: "May his prayers be with us and Glory be to God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baouna-22",
    title: { en: "Baouna 22", ar: "22 بؤونه" },
    blocks: [
      { kind: 'heading', text: { en: "The Consecration of the Church of Sts. Cosmas, Damian, Their Mother, and Brothers.", ar: "تكريس كنيسة قزمان ودميان واخوتهما" } },
      { kind: 'reading', text: { en: "On this day, the church celebrates the consecration of the church of . They were from one of the Arab countries. Their mother feared God and was compassionate and merciful towards strangers and the needy. She became a widow, while her children were young. She raised them and taught them the fear of God. Cosmas and Damian studied medicine, and they treated the sick freely. As for their brothers, they went to the desert and became monks.", ar: "في هذا اليوم نعيد بتذكار تكريس كنيسة القديسين قزمان ودميان واخوتهما انتيموس ولاونديوس وأبرابيوس وأمهم ثاؤذوتي كانوا من إحدى بلاد العرب وكانت أمهم تخاف الله محبة للغرباء رحومة وقد ترملت عليهم صغارا فربتهم وعلمتهم مخافة الرب ." } },
      { kind: 'reading', text: { en: "When Diocletian renegaded the faith and ordered the worship of idols, he was told that Cosmas and Damian were preaching in the Name of the Lord Christ in every city and urging others not to worship the idols. He commanded them brought and delivered to the governor of the city, who tortured them with different kinds of tortures. Then he asked them the whereabouts of their brothers. Upon finding out, he brought the brothers and their mother. He ordered them to raise incense for the idols, but they refused. Then he ordered the five to be squeezed through the wheel. When they experienced no harm, he took them out and cast them in red-hot fire for three days and three nights then cast them in a hot steaming room. Finally, he placed them on red-hot iron beds. Through all this, the Lord strengthened and healed them.", ar: "وتعلم قزمان ودميان مهنة الطب وكانا يعالجان المرضي بلا أجر أما اخوتهما فمضوا إلى البرية وترهبوا ، ولما كفر دقلديانوس وأمر بعبادة الأوثان أعلموه عن قزمان ودميان أنهما يبشران في كل مدينة بالسيد المسيح ويحرضان علي عدم عبادة الأوثان فأمر بإحضارهما وتسليمهما لوالي المدينة الذي عذبهما بأنواع العذاب المختلفة ثم استعلم منهما عن مكان اخوتهما ولما عرفه استحضرهم وأمهم أيضا فأمر أن يعصر الخمسة في المعصرة ولما لم ينلهم آذى أخرجهم وألقاهم في أتون النار ثلاثة أيام وثلاث ليال ثم طرحهم في مستوقد حمام وأخيرا وضعهم علي أسرة من الحديد الساخن وفي هذه جميعها كان الرب يقويهم ويشفيهم ولما تعب الوالي من تعذيبهم أرسلهم إلى الملك فعذبهم هو أيضا وكانت أمهم تعزيهم وتصبرهم فانتهرها الملك فلعنته في وجهه ولعنت أوثانه النجسة فأمر بقطع رأسها ونالت إكليل الشهادة . وبقي جسدها مطروحا لم يجسر أحد أن يدفنه وكان القديس قزمان يصرخ في أثناء ذلك قائلا : &quot; يا أهل هذه المدينة أليس بينكم أحد ذو رحمة فيستر جسد هذه الأرملة العجوز ويدفنها ؟ &quot; عند ذلك تقدم بقطر بن رومانوس وأخذ الجسد وكفنه ثم دفنه ." } },
      { kind: 'reading', text: { en: "When the governor became weary of torturing them, he sent them to the Emperor who also tortured them. Their mother constantly encouraged them and comforted them. The Emperor rebuked her, and she cursed him in his presence and also cursed his idols. He ordered her head cut off, and she received the crown of martyrdom. Her body remained on the ground, no one dared to bury it, because of their fear of the Emperor. St. Cosmas screamed at those present saying, \"Men of the city, is there not one merciful person among you who will cover the body of this poor old widow and bury her?\" Straightway, Victor, Ebn-Romanus, came forward and took the body, shrouded it, then buried it.", ar: "ولما علم الملك بما عمل بقطر أمر بنفيه إلى ديار مصر وهناك نال إكليل الشهادة وفي الغد أمر الملك بقطع رؤوس القديسين قزمان ودميان وأخوتهما . فنالوا إكليل الحياة في ملكوت السموات . وبعد انقضاء زمان الاضطهاد بنيت لهم كنائس عديدة أظهر الرب فيها آيات وعجائب كثيرة شفاعتهم تكون معنا . ولربنا المجد دائما . آمين" } },
      { kind: 'reading', text: { en: "When the Emperor heard what Victor had done, he ordered him to be exiled to Egypt where he received the crown of martyrdom. The next day, the Emperor ordered the beheading of Sts. Cosmas, Damian, and their brothers. They received the crown of life in the Kingdom of Heaven. After the time of persecution was over, many churches were built for them, where God manifested many signs and wonders.", ar: "" } },
      { kind: 'reading', text: { en: "May their intercession be with us and Glory be to God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baouna-23",
    title: { en: "Baouna 23", ar: "23 بؤونه" },
    blocks: [
      { kind: 'heading', text: { en: "The Departure of St. Abba Noub the Confessor.", ar: "نياحة القديس ابانوب المعترف" } },
      { kind: 'reading', text: { en: "On this day, the holy and pure father Abba Noub the confessor, departed. This Saint was a devoted monk in one of the monasteries of Upper Egypt. That was during the time of Diocletian, who tortured the martyrs severely and shed their blood.", ar: "في مثل هذا اليوم تنيح الأب القديس الطاهر أبانوب المعترف كان هذا القديس راهبا فاضلا بأحد أديرة الصعيد في زمان دقلديانوس الذي عذب الشهداء كثيرا وسفك دماءهم حتى أنه سفك دماء ثمانين شهيدا في يوم واحد ، وحدث في أحد الأيام أن ذكر أحدهم اسم القديس أبانوب فاستحضره أريانا والي أنصنا وعرض عليه السجود للأوثان فأجابه القديس قائلا : &quot; كيف اترك سيدي يسوع المسيح وأعبد الأوثان المصنوعة من الحجارة &quot; فعذبه كثيرا ثم نفاه إلى الخمس مدن الغربية فأقام هناك محبوسا سبع سنين حتى أهلك الرب دقلديانوس وملك قسطنطين البار وأصدر أمره بإطلاق جميع من في السجون وإحضارهم اليه ليتبارك منهم ، لا سيما الفضلاء منهم وهم زخاريس الاهناسي ومكسيميانوس الفيومي وأغابي الذي من دهني وأبانوب الذي من بالاؤس فانطلق رسول الملك يخرج القديسين من السجون فكانوا يخرجون وهم يرتلون ويسبحون الله وكان القديس أبانوب قد عاد من الخمس مدن وأقام بجبل بشلا (ورد في مخطوط بشبين الكوم &quot; سبلا &quot;) بجوار بلده والتقي به رسول الملك فأخذه معه في مركب إلى أنصنا فالتقوا بالمسيحيين وبالأساقفة ورسموا القديس أبانوب قسا وحدث بينما كان يقدس وعند قوله : &quot; هذا قدس القديسين فمن كان طاهرا فليتقدم &quot; أنه رأي السيد المسيح له المجد يتجلي في الهيكل بمجده الأسنى وهو يغفر خطايا الشعب التائب وسافر الرسول إلى الملك ومعه القديسون وكان عددهم اثنين وسبعين ، ركب كل اثنين منهم عربة ولما مروا علي إحدى البلاد وكان بها أديرة للعذارى خرج للقائهم سبعمائة عذراء وهن ينشدون ويرتلن أمامهم حتى غابوا عن الأعين ولما وصلوا ودخلوا عند الملك طلب إليهم أن يغيروا ثيابهم بأخرى جديدة فلم يقبلوا فتبارك منهم وقبل جراحاتهم وأكرمهم وقدم لهم مالا فرفضوا وأخذوا ما تحتاجه الكنائس من ستور وأواني ، ثم ودعهم الملك وعادوا إلى بلادهم وعاد القديس أبانوب إلى ديره ولما أكمل سعيه تنيح بسلام . صلاته تكون معنا ولربنا المجد دائما . آمين" } },
      { kind: 'reading', text: { en: "One day, someone mentioned the name of the saint Abba Noub before , governor of Ansena. Arianus brought him and asked him to worship the idols. The Saint replied, \"How can I abandon my Lord Jesus Christ and worship the idols that are made of stones?\" Arianus tortured Abba Noub much then exiled him to the five western cities (Pentapolis). Abba Noub stayed in prison there for seven years, until God had perished Diocletian. When the righteous , he ordered the release of all those who were in prison for the Name of Christ. Constantine also asked that they be brought to him, so that he might be blessed by them, especially the honored ones as Zacharia El-Ahnasy, Maximus El-Fayyumy, Agabius from the city of Dakhnin, and Abba Noub from the city of Balaos. The envoy of the Emperor went to all the countries releasing the prisoners, who left singing and praising God.", ar: "" } },
      { kind: 'reading', text: { en: "The holy father Abba Noub returned from the five cities (Pentapolis) and lived in mount Beshla (Sebla) near his hometown. The envoy of the Emperor met Abba Noub, and took him with him to Ansena. There he met the Christians and the bishops who ordained him a priest. While he was consecrating the Offering and as he said, \"Hollies for the Holy,\" he saw the Lord Christ, to Him is the Glory, in His heavenly splendor, in the altar forgiving the sins of the people who were repentant.", ar: "" } },
      { kind: 'reading', text: { en: "The envoy traveled back to the Emperor along with the holy fathers who were seventy two in number. Every two of them rode a chariot. They passed by a city, where there were convents for the virgins. Seven hundred virgins went out to meet them with songs and hymns and they sang to them until they were out of their sight. When the holy fathers arrived and came before the Emperor, he asked them to change their clothes with new ones, but they refused. He was blessed by them, kissed their wounds and honored them. He offered them money, but they refused to take any except what the churches needed for vestments and vessels. The Emperor then embraced them and bid them farewell, and they returned to their countries. St. Abba Noub went back to his monastery and when he finished his strife he departed in peace.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us and Glory be to God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baouna-24",
    title: { en: "Baouna 24", ar: "24 بؤونه" },
    blocks: [
      { kind: 'heading', text: { en: "Martyrdom of the Great Saint Anba Moses the Black", ar: "استشهاد القديس أنبا موسى الأسود" } },
      { kind: 'reading', text: { en: "On this day, St. Moses the Black, whose life story is remarkable, was martyred. This saint took the Kingdom of Heaven by force, exactly as our Lord Jesus Christ said: The Kingdom of Heaven suffers violence, and the violent take it by force. (Matthew 11:12). In his early life, St. Moses was a slave to people who worshiped the sun. He was a mighty man who loved to eat and drink excessively. He killed, robbed and committed all evil. No one could stand up before him, or challenge him. On many occasions, he lifted up his eyes to look to the sun and to talk to it saying, O Sun!! if you are God, let me know it. Then he said, And you O God whom I do not know, let me know you. One day, he heard someone saying to him, The monks of Wadi El-Natroun know the real God. Go to them and they will tell you. Instantly, he rose up, girded his sword and went to the wilderness of Shiheat. He met St. Esidorous (Isidore) the priest, who was frightened when he saw him, because of his appearance. St. Moses comforted him by saying that he came to the monks so that they might let him know the real God. St. Esidorous took him to St. Macarius the Great, who preached to him, taught him the faith and baptized him. He accepted St. Moses as a monk and taught him to live in the wilderness. St. Moses dashed in many worships, and fought a spiritual fight which was greater than that fought by many saints. However, the devil fought him intensively with his old habits of excessive eating, drinking, and fornication. He informed St. Esidorous about everything which came upon him in his fight with the Enemy. He comforted him and taught him how to overcome the snares of the devil. It was told about him, that when the elders of the Monastery slept, he used to go round to their cells and take their water pots and fill them with water which he brought from a well at a far distance from the monastery. After many years in spiritual struggle, the devil envied him, and struck him with a sore on his foot which made him sick and bed-ridden. When he knew that this was from the devil, he increased in his asceticism and worship, until his body became as a burnt wood. God looked to his patience, healed his illness, and removed all his pains. The blessing of the Lord came upon him. After a while, he became the Father and the spiritual guide of 500 brothers, who elected him to be ordained a priest. When he came before the Patriarch to be ordained, the patriarch wanted to test him by asking the elders, Who brought this black here? Cast him out. He obeyed, and left saying to himself, It is good what they have done to you, O black colored one. The Patriarch, however, called him back and ordained him a priest, and said to him, Moses, all of you now has become white.", ar: "في مثل هذا اليوم استشهد القديس العظيم الأنبا موسى الأسود صاحب السيرة العجيبة . هذا الذي اغتصب ملكوت السموات حقا كما قال الإنجيل : &quot; ملكوت الله يغصب والغاصبون يختطفونه &quot; (مت 11 : 12) كان في حياته الأولي عبدا لقوم يعبدون الشمس جبارا قويا كثير الإفراط في الآكل وشرب الخمر يقتل ويسرق ويعمل الشر ولا يستطيع أحد أن يقف في وجهه او يعانده وكان في أكثر أوقاته يتطلع إلى الشمس ويخاطبها قائلا : &quot; أيتها الشمس أن كنت أنت الإله فعرفيني &quot; ثم يقول &quot; وأنت أيها الإله الذي لا اعرفه عرفني ذاتك &quot; فسمع يوما من يقول له : &quot; أن رهبان وادي النطرون يعرفون الله فاذهب إليهم وهم يعرفونك &quot; فقام لوقته وتقلد سيفه وأتي إلى البرية . فالتقي بالقديس ايسيذوروس القس ، الذي لما رآه خاف من منظره فطمأنه موسى قائلا أنه إنما أتي إليهم ليعرفوه الإله فأتي به إلى القديس مقاريوس الكبير وهذا وعظه ولقنه الأمانة وعمده وقبله راهبا وأسكنه في البرية فاندفع القديس موسى في عبادات كثيرة تفوق عبادة كثيرين من القديسين وكان الشيطان يقاتله بما كان فيه أولا من محبة الآكل والشرب وغير ذلك فيخبر القديس ايسيذوروس بذلك فكان يعزيه ويعلمه كيف يعمل ليتغلب علي حيل الشيطان ويروي عنه أنه كان إذا نام شيوخ الدير يمر بقلاليهم ويأخذ جرارهم ويملأها من الماء الذي كان يحضره من بئر بعيدة عن الدير وبعد سنين كثيرة في الجهاد حسده الشيطان وضربه بقرحة في رجله أقعدته وطرحته مريضا . ولما علم أنها من حرب الشيطان ازداد في نسكه وعبادته حتى صار جسده كخشبه محروقة فنظر الرب إلى صبره وأبرأه من علته وزالت عنه الأوجاع وحلت عليه نعمة الله ثم بعد زمان اجتمع لديه خمسمائة أخ فصار أبا لهم وانتخبوه ليرسموه قسا . ولما حضر أمام البطريرك لرسامته أراد أن يجربه فقال للشيوخ : &quot; من ذا الذي أتي بهذا الأسود إلى هنا . اطردوه &quot; فأطاع وخرج وهو يقول لنفسه : &quot; حسنا عملوا بك يا اسود اللون &quot; غير أن البطريرك عاد فاستدعاه ورسمه ثم قال له : &quot; يا موسى لقد صرت الآن كلك أبيض &quot;" } },
      { kind: 'reading', text: { en: "One day, he went with some elders to St. Macarius the Great, who said to them, I see among you one to whom belong the crown of martyrdom. St. Moses answered him, Probably it is me, for it is written: 'For all they that take with the sword, shall perish with the sword.' (Matt. 26:25) After they returned to the monastery, it did not take long until the Barbarians attacked the monastery. He told the brethren, Whoever wants to escape, let him escape. They asked him, And you O father, why do you not also escape? He replied that he had waited for this day for long time. The Barbarians entered the monastery and killed him with seven other brothers. One of the brethren was hiding, and saw the angel of the Lord, with a crown in his hand standing by and waiting for him. He went out from his hiding place to the Barbarians and he was also martyred.", ar: "واتفق أن مضى مع الشيوخ إلى القديس مقاريوس الكبير فقال القديس مقاريوس : &quot; أني أري فيكم واحدا له إكليل الشهادة &quot; فأجابه القديس موسى لعلي أنا هو لأنه مكتوب : من قتل بالسيف فبالسيف يقتل &quot; ولما عاد إلى ديره لم يلبث طويلا حتى هجم البربر علي الدير . فقال حينئذ للأخوة الذين كانوا عنده :&quot; من شاء منكم أن يهرب فليهرب &quot; فقالوا له : &quot; وأنت يا أبانا لماذا لا تهرب ؟&quot; فقال : &quot; أنا أنتظر هذا اليوم منذ عدة سنين &quot; ودخل البربر فقتلوه وسبعة أخوة كانوا معه غير أن أحد الاخوة اختفي وراء حصير . فرأي ملاك الرب وبيده إكليل وهو واقف ينتظره فلم يلبث أن خرج مسرعا إلى البربر فقتلوه أيضا ." } },
      { kind: 'reading', text: { en: "Beloved Ones, contemplate in the power of repentance, and what it did. It transformed an infidel slave who was a murderer, adulterer and robber into a great Father, teacher, comforter, and priest who wrote rules for the monks, and saint whose name is mentioned on the altar in our prayers.", ar: "فتأملوا أيها الأحباء قوة التوبة وما فعلت . فقد نقلت عبدا كافرا قاتلا زانيا سارقا وصيرته أبا ومعلما ومعزيا وكاهنا وواضع قوانين للرهبان ومذكورا علي المذابح ويوجد جسد هذا القديس بدير القديسة العذراء &quot;البرموس&quot; الآن حيث يحتفل.صلاته تكون معنا . ولربنا المجد دائما . آمين" } },
      { kind: 'reading', text: { en: "His Body is located now in the Monastery of El-Baramouse.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us, and glory be to God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baouna-25",
    title: { en: "Baouna 25", ar: "25 بؤونه" },
    blocks: [
      { kind: 'heading', text: { en: "The Martyrdom of St. Jude, one of the Seventy Disciples.", ar: "استشهاد القديس يهوذا أحد السبعين رسولا" } },
      { kind: 'reading', text: { en: "On this day, St. Jude, one of the Seventy disciples, was martyred. This Apostle preached in many cities, and in the islands, where he built a church. He went to Edessa, healed its king Abgar from his sickness and baptized him. After this he went to the city of Araz, preached there, and baptized many of its people. The governor of the city seized him, and tortured him with many tortures. Then, they shot at him with arrows, so he delivered up his pure soul. He is the writer of the Epistle attributed to his name in the New Testament which is filled with wisdom and grace.", ar: "في مثل هذا اليوم استشهد القديس يهوذا (قيل أن يهوذا هو الملقب لدلوس أوتداوس وهو شقيق يعقوب ويوسي وسمعان أبناء مريم زوجة كلوبا &quot; حلفي &quot; خالة السيد المسيح . أحد السبعين تلميذا ، و كاتب الرسالة المعروفة باسمه في العهد الجديد المملوءة من كل حكمة ونعمة . بشر في بلاد العرب واستقر في بلاد العجم حيث بشر في مدن كثيرة وفي الجزائر وبني فيها كنيسة ومضي إلى الرها وشفي أبجر ملكها من مرضه ثم عمده وكان معه سمعان القانوي ، عزم القائد برداين أن يقوم بحرب ضد الهند واستشار السحرة فلم يأتوه بنتيجة . فقالا له الرسولان &quot; سيأتيك رسول من الهند لعقد صلح &quot; وبالفعل تم هذا فأطلق للرسولين حرية التبشير . ثم دخلا مدينة أراط وبشرا فيها وعمد كثيرين من أهلها فقبض عليها واليها وعذبها بكل نوع ثم رموه بالسهام فأسلم روحه الطاهرة ، ونالا إكليل الشهادة صلاتها تكون معنا . آمين" } },
      { kind: 'reading', text: { en: "May his prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of St. Peter the Fourth, 34th Pope of Alexandria.", ar: "نياحة القديس البابا بطرس الرابع البطريرك 34" } },
      { kind: 'reading', text: { en: "On this day also, the holy father and fighter St. Peter the Fourth, 34th Pope of Alexandria, departed. His predecessor Pope Theodosius was exiled by the orders of Emperor Vespasian because he did not agree with him on the resolutions of the Council of Chalcedon. When the Pope departed in exile, the Emperor did not permit the ordination of a new Patriarch. The lay leaders of the city of Alexandria went to its governor, who was an honorable and forthright man, and expressed to him their grief because of the vacancy of the Patriarchal chair. He advised them to go to the monastery of El-Zogag as if they were going to pray, there they could then ordain the patriarch of their choice. They rejoiced at this counsel. The bishops took Abba Peter to the monastery of El-Zogag and ordained him Patriarch on the , 283 A.M. (July 25th,567 A.D.).", ar: "في مثل هذا اليوم من سنة 285 ش ( 19 يونية 569 م ) تنيح القديس المجاهد البابا بطرس البطريرك الرابع والثلاثين من باباوات الكرازة المرقسية . وذلك لما تنيح سلفه البابا ثاؤدسيوس في المنفي بأمر وسباسيانوس الملك لأنه لم يوافقه علي قرارات مجمع خلقدونية تقدم أعيان مدينة الإسكندرية إلى واليها في ذلك الوقت وكان رجلا صالحا مستقيم الرأي وأظهروا له ألمهم من خلو الكرسي البطريركي فأشار عليهم أن يذهبوا إلى دير الزجاج . كما لو كانوا ذاهبين للصلاة . ثم يرسموا هناك البطريرك الذي يرغبونه . ففرحوا بذلك وأخذ الأساقفة هذا الأب بطرس إلى هناك ورسموه بطريركا ، في أول مسرى سنة 283 ش ( 25 يوليه سنة 567 م ) وكان الأنبا ساويرس الأنطاكي قد تنيح . فلما بلغ أهالي إنطاكية أن المصريين قد رسموا لهم بطريركا رسموا لهم هم أيضا بطريركا يسمي ثاؤفانيوس وتراسل هو والبابا بطرس برسائل الإيمان الأرثوذكسي ز وكان كل منهما يذكر أخاه في صلاة القداس . إلا أن كلا منها لم يجرؤ علي الذهاب إلى مقر كرسيه فكان البابا بطرس يقيم في دير أبيفانية قبلي دير الزجاج . كما كان ثاؤفانيوس يقيم في دير أفتونيوس بظاهر إنطاكية . وكان يومئذ بظاهر الإسكندرية ستمائة دير واثنتان وثلاثون قرية جميع سكانها أرثوذكسيين وكانت مدينة الإسكندرية ومدن مصر والصعيد ورهبان الأديرة بجبل شيهيت وأثيوبيا والنوبة تحت رئاسة البابا بطرس . ولم يكن يفتر عن إرسال الرسائل إلى المؤمنين ليثبتهم علي الإيمان المستقيم وكان يطوف أديرة الإسكندرية وقراها يعلمهم ويعظهم ويثبتهم وكان قد اختر رجلا قديسا عالما يسمي داميانوس وجعله كاتبا له وأوكل إليه الاهتمام بالكنائس وهو الذي صار بطريركا بعده أما البابا بطرس فقد استمر في الاهتمام برعيته وتثبيتهم علي الإيمان الأرثوذكسي حتى تنيح بسلام . صلاته تكون معنا . ولربنا المجد دائما . آمين" } },
      { kind: 'reading', text: { en: "Before this, Anba Severus had departed and the Antiochian chair remained vacant. When the people of Antioch heard that the Egyptians had ordained for themselves a patriarch, they also ordained for themselves a patriarch called Theophanius. He and Pope Peter exchanged letters concerning the Orthodox faith. Each one mentioned his brother in the Divine Liturgy, nevertheless they did not dare to go to their official seats. Pope Peter resided in the monastery of Epiphaniah south of El-Zogag monastery, as Theophanius was residing in the monastery of Aphtonius in the outskirts of Antioch.", ar: "" } },
      { kind: 'reading', text: { en: "In those days, there were six hundred monasteries and thirty-two villages on the outskirts of Alexandria; all their inhabitants were Orthodox. The city of Alexandria, the cities of Upper and Lower Egypt, the monks of the monasteries of the desert of Scete, Ethiopia and Nuba were under the authority of Pope Peter. He did not cease sending Epistles to the believers to confirm them in the Orthodox faith. He went around visiting the monasteries of Alexandria and its villages, teaching, admonishing, and strengthening them. He chose a holy and learned man called Damianos and appointed him as his scribe. Pope Peter delegated to him the care of the churches, and he became a patriarch after him. Pope Peter went on caring for his flock, confirming them in the Orthodox faith until he departed in peace.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us and Glory be to God for ever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baouna-26",
    title: { en: "Baouna 26", ar: "26 بؤونه" },
    blocks: [
      { kind: 'heading', text: { en: "The Consecration of the Church of Archangel Gabriel.", ar: "تذكار تكريس كنيسة رئيس الملائكة غبريال" } },
      { kind: 'reading', text: { en: "On this day also, is the commemoration of the consecration of a church in the name of the honorable angel Gabriel the announcer, on the Naklon mount, in El-Fayyoum.", ar: "في مثل هذا اليوم تذكار تكريس كنيسة باسم الملاك الجليل جبرائيل المبشر بجبل النقلون بالفيوم .شفاعته تكون معنا . ولربنا المجد دائما . آمين" } },
      { kind: 'reading', text: { en: "May his intercession be with us and Glory be to God forever. Amen.", ar: "(جاء فى اللؤلؤة وفى كنوز النعمة جزء 2 انه يقرأ 22 كيهك تذكار للملاك بدلا من اليوم )" } },
      { kind: 'heading', text: { en: "The Departure of the Great Prophet Joshua Son of Nun.", ar: "نياحة يشوع ابن نون النبى" } },
      { kind: 'reading', text: { en: "On this day, of the year 2570 of the world, the great prophet Joshua Son of Nun, departed. He was born, in the year 2460 of the world, in Egypt (Fifty three years before the deliverance of the people of Israel from the bondage of Pharaoh). He was a disciple and servant to Moses. Moses, after leading the people of Israel out of Egypt with the might of the Divine arm and the extraordinary wonders, brought them to the nearby mount of Sinai. He went up the mount taking with him Joshua, his minister, to receive the commandments. During the war of Israel against Am-a-lek, Joshua was the leader of the soldiers.", ar: "في مثل هذا اليوم من سنة 2570 للعالم تنيح النبي العظيم يشوع بن نون . ولد في مصر سنة 2460 للعالم ( أي قبل خروج الشعب الإسرائيلي من عبودية فرعون بثلاث وخمسين سنة ) كان تلميذا وخادما لموسى النبي الذي بعد أن أخرج شعب الله بقوة الذراع الإلهي والعجائب العظيمة وأوصلهم إلى قرب جبل سينا صعد إلى الجبل آخذا معه يشوع خادمه لسماع الوحي واستلام الوصايا . وفي أثناء حرب إسرائيل ضد عماليق كان يشوع قائدا للجنود ، فلما انتخب موسى اثني عشر رجلا ، واحدا من كل سبط وأرسلهم ليتجسسوا أرض الميعاد كان يشوع واحدا منهم وقد أتم خدمته بكل أمانة، وقرر هو وكالب وحدهما الأخبار الصادقة عن أرض الميعاد . ولذلك دخل الاثنان فقط تلك الأرض دون جميع الشعب الإسرائيلي الذي خرج من مصر الذين لكونهم تذمروا وشكوا في صدق مواعيد الله فقد اقسم تعالي أنهم لا يدخلون إلى راحته ، ولكن أولادهم الذين ولدوا لهم بعد خروجهم من مصر هم الذين دخلوا تلك الأرض مع يشوع وكالب .ولما تنيح العظيم موسى سنة 2553 للعالم خاطب الله يشوع قائلا &quot; أن موسى عبدي قد مات فالآن قم أعبر هذا الأردن أنت وكل هذا الشعب إلى الأرض التي أنا معطيها لهم أي لبني إسرائيل كل موضع تدوسه بطون أقدامكم لكم أعطيته كما كلمت موسى من البرية ولبنان هذا إلى النهر الكبير نهر الفرات جميع أرض الحثيين والي البحر الكبير نحو مغرب الشمس يكون تخمكم لا يقف إنسان في وجهك كل أيام حياتك كما كنت مع عبدي موسى أكون معك . لا أهملك ولا أتركك تشدد وتشجع لأنك أنت تقسم لهذا الشعب الأرض التي حلفت لآبائهم أن أعطيهم إنما كن متشددا وتشجع جدا لكي تتحفظ للعمل حسب كل الشريعة التي أمرك بها موسى عبدي لا تمل عنها يمينا ولا شمالا لكي تفلح حيثما تذهب لا يبرح سفر هذه الشريعة من فمك بل تلهج فيه نهارا وليلا لكي تتحفظ للعمل حسب كل ما هو مكتوب فيه . لأنك حينئذ تصلح طريقك وحينئذ تفلح &quot; (يش 1 : 1 – 8) فتقوي قلب يشوع وأرسل جاسوسين سرا تجسسا الأرض ودخلا بيت راحاب الزانية فخبأتهما ثم أنزلتهما من الكوة لان بيتها كان بحائط السور وذلك بعد أن أمناها علي نفسها وعلي كل أهل بيتها (يش 2 : 1 – 15)" } },
      { kind: 'reading', text: { en: "When Moses chose twelve men to spy out the promised land, one from each tribe, Joshua was one of them. He completed this mission with honesty. He and Caleb alone brought forth the true and accurate information about the promised land. Therefore they alone entered this land without the people of Israel that came out of the land of Egypt. Because they had murmured and doubted in the sincerity of the promises of God, God swore in His anger that they would not enter to His rest. Their children that they begot after their deliverance from Egypt, entered this land along with Joshua and Caleb.", ar: "ثم فتح أريحا بعد أن طاف حول أسوارها مرات متعددة وهو يهتف فأنهدمت أسوارها العظيمة . وصعد الشعب إلى المدينة وقتلوا كل من كان فيها من إنسان وحيوان بعد ما أخرجوا راحاب وأباها وأمها واخوتها وكل من لها وعشيرتها خارج المحلة . وأحرقوا المدينة بالنار فقد جعلوها في خزانة بيت الرب واستحيا يشوع راحاب الزانية وكل بيت أبيها لأنها خبأت الرسولين" } },
      { kind: 'reading', text: { en: "After the death of the in the year 2553 of the world, the LORD spoke to Joshua the son of Nun saying: \"Moses My servant is dead. Now therefore, arise, go over this Jordan, you and all this people, to the land which I am giving to them; the children of Israel. Every place that the sole of your foot will tread upon I have given you, as I said to Moses. From the wilderness and this Lebanon as far as the great river, the River Euphrates, all the land of the Hittites, and to the Great Sea toward the going down of the sun, shall be your territory. No man shall be able to stand before you all the days of your life; as I was with Moses, so I will be with you. I will not leave you nor forsake you. Be strong and of good courage, for to this people you shall divide as an inheritance the land which I swore to their fathers to give them. Only be strong and very courageous, that you may observe to do according to all the law which Moses My servant commanded you; do not turn from it to the right hand or to the left, that you may prosper wherever you go. This Book of the Law shall not depart from your mouth, but you shall meditate in it day and night, that you may observe to do according to all that is written in it. For then you will make your way prosperous, and then you will have good success.\" (Joshua 1:1-8)", ar: "وكان الرب مع هذا الصديق فقتل ملوكا وفتح مدنا كثيرة فخافته الأمم، ولعظم الخوف احتال أهل جبعون فلبسوا ثيابا بالية ونعالا مرقعة وصيروا خبز زادهم فتاتا . ومضوا إلى يشوع وقالوا له نحن جيئا من أرض بعيدة نريد منك الأمان والعهد فأجابهم يشوع ومشايخ بني إسرائيل : &quot; انظروا لئلا تكونوا ساكنين في هذه الأرض &quot; فأجابوهم : &quot; من أرض بعيدة جئنا علي اسم الرب إلهكم . هذا خبزنا سخنا تزودناه من بيوتنا يوم خروجنا لكي نسير إليكم : وها هو الآن يابس قد صار فتاتا . وهذه ثيابنا ونعالنا قد بليت من طول الطريق جدا&quot; فأمنوهم وحلفوا لهم وبعد ثلاثة أيام سمعوا أنهم قريبون إليهم وأنهم ساكنون في وسطهم فلعنهم يشوع وجعلهم عبيدا ينقلون الحطب لخدمة بيت الرب ." } },
      { kind: 'reading', text: { en: "Joshua's heart was strengthened and he sent out two men to spy out the land secretly. So they went, and came to the house of a harlot named Rahab, and lodged there. The woman hid them; and they swore to spare her and all her household. Then she let them down by a rope through the window, for her house was on the city wall. (Joshua 2:1-15) Then Joshua opened (i.e. conquered) Jericho after he had gone around its walls several times and when they shouted with a great shout the great walls of the city fell down. The people went up into the city and killed both man and beast. The two men that had spied out the country, went into Rahab's house and brought her, her father, her mother, her brethren, and all that she had, out of the camp. Joshua spared their lives as the two spies promised her for she had spared their lives, and hid them. Then they burnt the city, and all that was therein. The gold, and the silver and vessels of brass and iron, were taken to the treasury of the house of the Lord.", ar: "وحارب يشوع خمسة ملوك الأموريين حيث ساعدته يد الرب بنزول الحجارة كالمطر علي الأعداء وكان الشعب يقاتلهم أمام مدينة جبعون فأوقف الشمس إلى أن أباد الخمسة الملوك مع كل عساكرهم وحسب أوامر الله قسم الأرض بين بني إسرائيل وأعطي الكهنة بلادا لسكناهم وأرضا لمواشيهم ثم افرد خمس مدن يلتجئ إليها كل قاتل بغير قصد ولما أكمل نحو مئة وعشر سنين ووصل إلى شيخوخة صالحة استدعي الشيوخ والرؤساء والقضاة والمعلمين ووعظهم ونبههم أن لا يحيدوا عن عبادة الله تعالي . ووضع لهم الرسوم والفرائض اللازمة ثم تنيح بسلام . صلاته تكون معنا . آمين" } },
      { kind: 'reading', text: { en: "The Lord was with this righteous man, so he opened many cities, killed many kings, and the nations feared him. Because of the great fear, the inhabitants of Gibeon worked craftily, and went and pretended to be ambassadors. And they took old sacks on their donkeys, old wineskins torn and mended, old and patched sandals on their feet, and old garments on themselves; and all the bread of their provision was dry and moldy. And they went to Joshua, and said to him, \"We have come from a far country; now therefore, make a covenant with us.\" But the men of Israel said to them, \"Perhaps you dwell among us; so how can we make a covenant with you?\" They said to them, \"From a very far country your servants have come, because of the name of the LORD your God; for we have heard of His fame ... this bread of ours we took hot for our provision from our houses on the day we departed to come to you. But now look, it is dry and moldy ... and these our garments and our sandals have become old because of the very long journey.\" Joshua made peace with them, and made a covenant with them to let them live; and the rulers of the congregation swore to them. Three days later, after they had made a covenant with them, they heard that they were their neighbors who dwelt near them. Joshua called for them, and he spoke to them, saying, \"Why have you deceived us, saying, 'We are very far from you,' when you dwell near us? Now therefore, you are cursed, and none of you shall be freed from being slaves.\" Joshua made them woodcutters and water carriers for the congregation and for the house of the LORD. (Joshua 9:3-27)", ar: "" } },
      { kind: 'reading', text: { en: "Joshua fought with the five Amorite kings, hence the hand of the Lord had helped him by casting down great stones from heaven upon them. The children of Israel fought them before the city of Gibeon, and he made the sun stand still until the five kings and their soldiers were destroyed. Joshua divided the land according to the command of God among the children of Israel. He gave the priests cities to dwell in, and land for their cattle. He set apart five cities of refuge wherein all those who had committed a murder unintentionally might dwell.", ar: "" } },
      { kind: 'reading', text: { en: "When he completed about one hundred ten years and reached a good old age, he gathered together the elders of Israel, their heads, their judges and their officers, and commanded them to keep the commandment of the Law and not to deviate from worshipping God, then departed in peace.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "", ar: "استشهاد القديس ايسنت حاجب ترجان" } },
      { kind: 'reading', text: { en: "", ar: "في مثل هذا اليوم استشهاد القديس ايسنت حاجب ترجان. صلاته تكون معنا و لربنا المجد دائما أبديا آمين ." } }
    ],
  },
  {
    id: "synax-baouna-27",
    title: { en: "Baouna 27", ar: "27 بؤونه" },
    blocks: [
      { kind: 'heading', text: { en: "The Martyrdom of St. Thomas of Shentalet.", ar: "استشهاد القديس توماس الشندلاتى" } },
      { kind: 'reading', text: { en: "On this day also, St. Thomas of Shentalet(1) (Sandalat) was martyred. Michael, the angel of the Lord, appeared to this Saint when he was twenty-one years old, while he was sleeping in the field tending the pigs. The angel Michael commanded him to go and confess the Lord Christ. St. Thomas went to Alexandria and confessed his faith before the governor who tortured him with different kinds of tortures. There were with him under the torture St. Babnuda, of the city of El-Bandara, and Anba Shenousy(2), from the city of Balkim, and they encouraged each other to endure. After many tortures, the governor sent St. Thomas to , the governor of Ansena, where he was beheaded and received the crown of martyrdom. There were seven hundred men and nine women martyred during his days.", ar: "في مثل هذا اليوم استشهد القديس توماس الذي من شندلات (مركز السنطة غربية) هذا القديس ظهر له ميخائيل ملاك الرب وهو في سن الحادية والعشرين بينما كان نائما في الحقل يرعى الخنازير وأمره أن ينهض ويعترف بالسيد المسيح فذهب إلى الإسكندرية واعترف أمام الوالي فعذبه بكل أنواع العذاب وكان معه في العذاب القديس ببنوده الذي من البندرة ، وأنبا شنوسي (وردت &quot; موسى &quot; في مخطوط بشبين الكوم) الذي من بلكيم . فكانوا يصبرون بعضهم بعضا . وبعد عذابات كثيرة أرسله الوالي إلى أريانا والي أنصنا وهناك قطع رأسه فنال إكليل الشهادة وكان عدد الذين استشهدوا في أيامه سبعمائة رجل وتسع نساء .صلاتهم تكون معنا . ولربنا المجد دائما . آمين" } },
      { kind: 'reading', text: { en: "May their prayers be with us and Glory be to God forever. Amen.", ar: "" } },
      { kind: 'reading', text: { en: "(2) The name (Moses) mentioned in a manuscript in Shebeen El-Koum.", ar: "" } },
      { kind: 'heading', text: { en: "", ar: "استشهاد القديس مار بقطر بن رومانيوس" } },
      { kind: 'reading', text: { en: "", ar: "في مثل هذا اليوم استشهاد القديس مار بقطر بن رومانيوس. صلاته تكون معنا و لربنا المجد دائما أبديا آمين ." } },
      { kind: 'heading', text: { en: "The Martyrdom of St. Ananias, the Apostle.", ar: "استشهاد القديس حنانيا الرسول أحد السبعين" } },
      { kind: 'reading', text: { en: "On this day, St. Ananias, the apostle, departed. The apostles ordained this saint bishop for the city of Damascus. He preached therein with the life-giving gospel, as he preached also in the city of Beth-Gabriel and converted many of its people to the faith, and baptized them and their children.", ar: "في مثل هذا اليوم تنيح القديس حنانيا الرسول هذا القديس أقامه الرسل أسقفا علي دمشق فبشر فيها ببشارة الحياة . كما بشر في بيت جبريل أيضا ورد كثيرين من أهلها إلى الإيمان وعمدهم هم وأبناءهم . وهو الذي عمد بولس الرسول عندما أرسله الرب إليه ولما عمده وقعت من عينيه قشور ثم أبصر . وقد أجري الله علي يدي هذا القديس آيات كثيرة فأمن ببشارته كثيرون من اليهود والأمم . وبعد ذلك قبض عليه لوكيانوس الأمير وعذبه بعذابات شديدة منها حرق جنبيه بمشاعل نار وأخيرا أخرجه خارج المدينة وأمر برجمه حتى اسلم روحه الطاهرة بيد الرب صلاته تكون معنا . آمين" } },
      { kind: 'reading', text: { en: "when the Lord sent him to him. When he baptized St. Paul, something like scales fell from his eyes, and he received his sight at once. God wrought many great miracles by his hands; and many of the Jews and Gentiles believed through his preaching. Afterwards, Lucianus the governor seized St. Ananias, and tortured him with sever tortures, such as burning his sides with fiery torches. Finally, Lucianus took him outside the city, and commanded him stoned until St. Ananias delivered up his pure soul in the hand of the Lord.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baouna-28",
    title: { en: "Baouna 28", ar: "28 بؤونه" },
    blocks: [
      { kind: 'heading', text: { en: "The Departure of St. Theodosius, 33rd Pope of Alexandria.", ar: "نياحة البابا ثاؤذورس &quot;33 &quot;" } },
      { kind: 'reading', text: { en: "On this day, of the year 283 A.M. (June 22nd, 567 A.D.) St. Theodosius, the thirty-third Pope of Alexandria, departed. After the departure of Pope Timothy, the bishops and the Orthodox Christians gathered and ordained this father a patriarch. He was a learned man, and well rehearsed in the church books. Soon after, the enemy of the good enticed some evil men from the city of Alexandria, to take Acacius, Archdeacon of the churches of the city of Alexandria, and appoint him a patriarch. That happened with the help of Julian, who was excommunicated by Pope Timothy for his approval of the council of Chalcedon.", ar: "في مثل هذا اليوم من سنة 283 ش ( 22 يونيو سنة 567 م ) تنيح القديس ثاؤدسيوس البطريرك الثالث والثلاثين من باباوات الكرازة المرقسية . وذلك أنه بعد نياحة تيموثاوس أجتمع الأساقفة والشعب الأرثوذكسي ورسموا هذا الأب بطريركا وكان عالما حافظا لكتب الكنيسة وبعد أيام أثار عليه عدو الخير قوما أشرارا من أهل المدينة وأخذوا فاكيوس رئيس شمامسة كنيسة الإسكندرية ورسموه بطريركا بمعاونة يوليانوس . الذي كان البابا تيموثاوس قد حرمه لموافقته لمجمع خلقيدونية .ولما رسم فاكيوس نفوا البابا ثاؤدسيوس إلى جرسيمانوس وكان القديس ساويرس الأنطاكي يقيم في سخا من بلاد مصر وكان يعزيه ويصبره ذاكرا له ماخري للرسل وليوحنا ذهبي الفم . وبعد ستة أشهر من نفيه ذهب إلى مليج وأقام بها سنتين وبعد ذلك تقدم أهل الإسكندرية إلى الوالي وطلبوا منه أن يأمر بإعادة راعيهم الشرعي وطرد فاكيوس الدخيل ووصل الخبر إلى الملك يوستينيانوس والملكة المحبة للإله ثاؤذورا . فأرسلت تسأل عن صحة رسامة البابا ثاؤدسيوس حتى إذا كانت طبق القانون يتسلم كرسيه فعقدوا مجمعا من الشعب ومائة وعشرين كاهنا وأجمعوا علي أن ثاؤدسيوس رسم باتفاق الأساقفة والشعب وفقا للقانون . وكان فاكيوس حاضرا في المجمع فوقف معترفا بأنه هو المعتدي وطلب مسامحته علي أن يبقي رئيس شمامسة كما كان قبلا وأرسلوا للملكة بذلك غير أنه لما كان الملك موافقا علي معتقد غير الصحيح فكتب إلى نائبه في الإسكندرية يقول : &quot; إذا اتفق معنا البطريرك ثاؤدسيوس في الإيمان فتضاف إليه مع البطريركية الولاية علي الإسكندرية وإذ لم يوافق يخرج من المدينة &quot; فلما سمع البطريرك هذا القول قال : &quot; هكذا الشيطان قال للسيد المسيح بعد ما أراه جميع مماليك العالم ومجدها أعطيك هذه جميعها أن خررت وسجدت لي &quot; (مت 4 : 8 و 9) ثم خرج من المدينة ومضي إلى الصعيد وأقام هناك يثبت ثم استدعاه الملك إلى القسطنطينية فذهب إليها مع بعض الكهنة العلماء فتلقاه الملك بإكرام عظيم وأجلسه في مكان ممتاز واخذ بتملقه ويخاطبه بلطف لكي يوافق علي معتقد مجمع خلقيدونية وإذ لم يوافقه نفاه إلى صعيد مصر وأقام عوضا عنه شخصا يسمي بولس فلما وصل هذا إلى الإسكندرية لم يقبله أهلها ولبث سنة لم يتقرب إليه إلا نفر قليل . ولما وصل هذا الآمر إلى الملك آمر بإغلاق الكنائس حتى يخضعوا للبطريرك الذي عينه الملك فبني المؤمنون كنيسة علي اسم القديس مرقس خارج المدينة وأخري علي اسم القديسين قزمان ودميان وكانوا يتقربون فيهما ويعمدون أولادهم ." } },
      { kind: 'reading', text: { en: "When they appointed Acacius, they exiled Pope Theodosius to the city of Germanos. St. Severus, the Antiochian Patriarch, who was residing in Sakha, in the Egyptian land, comforted and strengthened him. He reminded him of the tribulation that came upon the apostles, and . Six month after the exile of Pope Theodosius, he went to the city of Malig, and dwelt there for two years. Afterwards, the people of the city of Alexandria went to the governor and demanded from him the return of their legitimate shepherd, and the expulsion of Acacius the Fraudulent. When the news reached Emperor Justinian and the God-loving Empress Theodora, she sent a letter to the church in Alexandria to ask about the legitimacy of the ordination of Pope Theodosius, for if it was according to the canon of the church he should be reinstated on his chair. A council of lay people and one hundred twenty priests convened and unanimously agreed that Theodosius was ordained with the consent of the bishops and the people and according to the canons of the church. Acacius was present in this council; he rose up confessing that he had transgressed. He asked for forgiveness and to remain as archdeacon as he was before. They sent these facts to the Empress. Since the Emperor was in agreement with the faith of the council of Chalcedon, he wanted to attract the Pope to this erroneous faith. He wrote to his representative in Alexandria saying, \"If the Patriarch Theodosius agreed with us in faith, along with his papacy, add the governorship of the city of Alexandria, but if he did not agree, he should be expelled from the city.\" When the Patriarch heard that, he said, \"That what the devil had told the Lord Christ after he showed him all the kingdoms of the world and their glory, 'All these things will I give you, if you will fall down and worship me'\". The Patriarch then left the city and went to Upper Egypt and stayed there confirming the believers.", ar: "ولما سمع الملك بذلك عاد فأمر بفتح الكنائس فلما سمع البابا ثاؤدسيوس بهذا الآمر خشي أن يكون الملك قد قصد بذلك أن يستميلهم فكتب لهم رسالة يثبتهم علي الإيمان المستقيم ويحذرهم من خداع ذلك المخالف . وأقام في المنفي ثمان وعشرين سنة في صعيد مصر وأربع سنين في مدينة الإسكندرية وأمضي في البطريركية واحدا وثلاثين سنة وأربعة أشهر وخمسة عشر يوما وقد وضع هذا البابا ميامر وتعاليم كثيرة صلاته تكون معنا . آمين" } },
      { kind: 'reading', text: { en: "Later on, the Emperor called St. Theodosius to Constantinople, so he went with some of the learned priests. The Emperor received him with great honor, and seated him in a distinguished place. He tried to flatter him, and talk gently to him, to persuade him to agree on the faith of the council of Chalcedon. When he did not yield, he exiled him to Upper Egypt, and appointed in his place a person called Paul. When this Paul arrived to Alexandria, its people did not receive him. He remained there for a year and only few followed him. When the Emperor heard of this, he commanded to shut the churches until the people submitted to the patriarch he appointed. The believers built a church in the name of and another on the name of Sts. Cosmas and Damian outside the city where they were able to receive the Holy Mysteries and baptize their children.", ar: "" } },
      { kind: 'reading', text: { en: "When the Emperor heard that, he had the churches opened. Pope Theodosius, when he heard this, feared that the Emperor might have intended to lure the people by that act. He wrote a letter to the believers to confirm them in the Orthodox faith and to warn them from the deception of this infidel. He lived four years in Alexandria, and remained in exile in Upper Egypt for twenty-eight years. He spent thirty-one years, four months, and fifteen days in the patriarchate. This Pope wrote many discourses and useful teachings.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Commemoration of the Consecration of the Church of Anba Sarabamoun, Bishop of Nikios.", ar: "تذكار تكريس كنيسة الأنبا صرابامون أسقف نيقيوس" } },
      { kind: 'reading', text: { en: "On this day also, the church celebrates the Commemoration of the Consecration of the Church of Anba Sarabamoun, the martyr, Bishop of Nikios.", ar: "في هذا اليوم نعيد بتذكار تكريس كنيسة الشهيد الأنبا صرابامون أسقف نقيوس." } },
      { kind: 'reading', text: { en: "May his prayers be with us and Glory be to God forever. Amen.", ar: "صلاته تكون معنا ولربنا المجد دائما . آمين" } }
    ],
  },
  {
    id: "synax-baouna-29",
    title: { en: "Baouna 29", ar: "29 بؤونه" },
    blocks: [
      { kind: 'heading', text: { en: "The Martyrdom of Sts. Abba Hour and his Mother Theodora.", ar: "استشهاد القديس اباهور ، أبا بيشاى" } },
      { kind: 'reading', text: { en: "On this day also, Sts. Abba Hour and his mother Theodora, were martyred. Abba Hour was a soldier in the army of Antioch. He came to Alexandria, and confessed the Lord Christ before its governor. He commanded that Abba Hour's hands be cut off, that he be tied to the tail of an ox and dragged through the city. Then he was thrown into a pit filled with snakes which did not harm him. During all that torture, he cried out to the Lord Christ, who healed and strengthened him. His mother came to see him and she rejoiced in his strife.", ar: "في مثل هذا اليوم استشهد القديسون أباهور وأنبا بيشاي وثيؤدورة أمهما وذلك أن أباهور كان من جند إنطاكية فأتي إلى الإسكندرية واعترف أمام واليها بالسيد المسيح فأمر بقطع يديه وان يربط في مؤخرة ثور ويجره في المدينة ثم ألقاه في حفرة مملوءة بالأفاعي فلم تؤذه ، وكان في كل ذلك يستغيث بالسيد المسيح الذي كان يشفيه ويقويه وفيما هو علي هذه الحال أتت أمه ورأته ففرحت بجهاده وأعلموا الوالي بها فاستحضرها وهددها فلم تخف . فأمر أن يضعوا أعوادا ساخنة من الحديد في جنبيها ، وكانت في أثناء ذلك ترتل للرب وتقدسه لأنها استحقت أن تتألم من أجل اسمه . إلى أن أسلمت روحها ونالت إكليل الشهادة ثم وضعوا القديس في إناء مملوء زيت وقطران يغلي فكان يسبح الله حتى أسلم الروح ونال إكليل الشهادة ، أما أخوه فقد استشهد في اليوم الأول من النسيء صلاتهم تكون معنا . ولربنا المجد دائما . أمين" } },
      { kind: 'reading', text: { en: "They told the governor about her, and he had her brought to him. He asked her to sacrifice to the idols but when she refused he became enraged at her, and frightened her but she was not afraid of his raging. He commanded to put red-hot iron rods in her sides. When they did so she rejoiced and sang hymns to venerate the Lord for He made her worthy to suffer for His Holy Name. Later on she delivered up her soul and received the crown of martyrdom.", ar: "" } },
      { kind: 'reading', text: { en: "As for St. Abba Hour (Hor), they placed him in a cauldron of boiling oil and tar, and he praised\nGod until he delivered up his soul and received the crown of martyrdom. His brother", ar: "" } },
      { kind: 'reading', text: { en: "May their prayers be with us and Glory be to God forever. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Martyrdom of the Seven Ascetic Saints in Tounar Mount.", ar: "استشهاد السبعة نساك بجبل تونه" } },
      { kind: 'reading', text: { en: "On this day, the seven ascetic saints in Tounar Mount (Tona), were martyred. These were:\nBasadi, Cotolus, Ardama, Moses, Esey, Parkalas (Mikalas), and a monk called Cotolus. The angel of the Lord had appeared to Sts. Basadi and Cotolus and commanded them to confess the name of the Lord Christ. They rose up straightway to go to the governor. They met the five saints embarking a ship going to the governor to also confess the Lord Christ. They all agreed together on receiving the crown of martyrdom. They went to the governor and confessed the Lord Christ. He tortured them excessively, then hung stones from their necks, and shut them up in prison. The Lord appeared to them, comforted, strengthened, and promised them the kingdom. The governor then sent them to Alexandria, where they were tortured severely. He threw them into cauldrons full of sulphur and pitch, and lighted a great fire under them, then he took them out and threw them away. The Lord sent His angel who healed them. They came back to the governor and confessed the Lord Christ before him. One hundred thirty persons witnessed that. They confessed the Lord Christ, were martyred, and they received the crown of martyrdom. The Governor intensified the torture on the seven saints, and finally cut off their heads with the sword, and they received the crown of martyrdom.", ar: "في مثل هذا اليوم استشهد القديسون السبعة النساك الذين من جبل تونه وهم : باسيدي وكوتولس وأرداما وموسى وايسي وباركالاس وراهب أخر اسمه كوتولس . وذلك أن ملاك الرب ظهر للقديسين باسيدي وكوتولس وأمرهما أن يعترفا باسم السيد المسيح فنهضا مسرعين نحو الوالي فالتقيا بالخمسة القديسين آتين علي سفينة قاصدين الوالي ليعترفوا هم أيضا بالسيد المسيح فاتفقوا معا علي نيل إكليل الشهادة ومضوا إلى الوالي واعترفوا بالسيد المسيح ، فعذبهم كثيرا ثم علق حجارة في أعناقهم وأودعهم السجن ، فظهر لهم السيد وعزاهم وقواهم ووعدهم بالملكوت ثم أرسلهم الوالي إلى الإسكندرية فعذبهم هناك عذابا قاسيا إذ وضعهم في قدر مملوء كبريتا وزفتا ، وأوقد تحتهم النار ثم أخرجهم وطرحهم فأرسل الرب ملاكه وشفاهم وأتوا إلى الوالي واعترفوا أمامه ورأي ذلك مائة وثلاثين شخصا فاعترفوا بالسيد المسيح ونالوا إكليل الشهادة أما القديسون فقد شدد عليهم الوالي العذاب وأخيرا قطع رؤوسهم بالسيف ونالوا إكليل الشهادة شفاعتهم تكون معنا . آمين" } },
      { kind: 'reading', text: { en: "May their intercession be with us. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baouna-30",
    title: { en: "Baouna 30", ar: "30 بؤونه" },
    blocks: [
      { kind: 'heading', text: { en: "The Nativity of St. John, the Baptist.", ar: "ميلاد القديس يوحنا المعمدان" } },
      { kind: 'reading', text: { en: "On this day, the church celebrates the nativity of St. John the Baptist. He whom none born of women was greater. He who kneeled to the Lord Christ while he was still in his mother's womb, and was worthy to lay his hand upon the head of the Son of God during Baptism. The Holy Bible said about him: \"Now full time came for her to be delivered, and she brought forth a son. When her neighbors and relatives heard how the Lord had shown great mercy to her, they rejoiced with her. Now so it was, on the eighth day, that they came to circumcise the child; and they would have called him by the name of his father, . And his mother answered and said, 'No; he shall be called John.' But they said to her, 'There is no one among your relatives who is called by this name.' So they made signs to his father; what he would have him called. And he asked for a writing tablet, and wrote, saying, 'His name is John.' And they all marveled. Immediately his mouth was opened and his tongue loosed, and he spoke, praising God. He prophesied about his son, saying. 'you, child, will be called the prophet of the Highest; for you will go before the face of the Lord to prepare His ways.'\" (Luke 1:57-76)", ar: "في مثل هذا اليوم كان ميلاد القديس يوحنا المعمدان . هذا الذي لم تلد النساء أعظم منه ، وهو الذي سجد للمسيح وهو بعد في بطن أمه . كما استحق أن يضع يده علي رأس ابن الله وقت العماد . وجاء عنه في الإنجيل المقدس : &quot; أما أليصابات فلما تم زمانها لتلد فولدت ابنا وسمع جيرانها وأقرباؤها ان الرب عظم رحمته لها ففرحوا معها ، ولما كان في اليوم الثامن جاءوا لختنوا الصبي ودعوه باسم أبيه زكريا . فقالت أمه لا بل يسمي يوحنا . فقالوا لها ليس أحد في عشيرتك تسمي بهذا الاسم ، ثم أشاروا لأبيه ماذا يريد أن يسميه فطلب لوحا وكتب قائلا اسمه يوحنا . فتعجب الجميع لأنه في الحال انفتح فمه ولسانه وتكلم وبارك الله وتنبأ عن ابنه أنه سيدعي نبيا للعلي وينطلق أمام وجه الرب ليعد طريقه ( لو 2 : 57 – 76) ." } },
      { kind: 'reading', text: { en: "When he was two years old, the wise men (Magi) came, Herod killed the children, some divulged about this child and the soldiers searched for him to kill him. Zechariah took the child and brought him to the sanctuary, laid him on the altar and told the soldiers, \"I have received him from this place\". The angel of the Lord caught up the child and brought him to the desert of Ziphana, so the soldiers became enraged and they killed his father Zechariah. For this reason the Lord had said to the Jews: \"That on you may come all the righteous blood shed on the earth, from the blood of righteous Abel to the blood of Zechariah, son of Berechiah, whom you murdered between the temple and the altar.\" ( 23:35) So the child John grew and became strong in spirit, and was in the deserts more than twenty years living an angelic life, till the day of his manifestation to Israel. (Luke 1:80)", ar: "ولما كان ابن سنتين واتفق مجيء المجوس وقتل هيرودس الأطفال وشي بعضهم عن هذا الطفل ، فطلبه الجند ليقتلوه لكن زكريا حمله وأتي به إلى الهيكل وقال للجند : &quot; من هذا المكان تسلمته &quot; فخطفه الملاك وأتي به إلى بريه الزيفانا . فاغتاظ الجند وقتلوا أباه زكريا . ولهذا السبب قال الرب لليهود &quot; يأتي عليكم كل دم زكي سفك علي الأرض من دم هابيل الصديق إلى دم زكريا بن براخيا الذي قتلتموه بين الهيكل والمذبح &quot; (مت 23 : 25 ). أما الصبي يوحنا فكان ينمو ويتقوى بالروح (لو 1 : 80) ." } },
      { kind: 'reading', text: { en: "And John himself was clothed in camel's hair, with a leather belt around his waist; and his food was locusts and wild honey. (Matthew 3:4) He lived in the wilderness persevering in prayers and asceticism, until the Lord ordered him, to fulfill the prophesies, to preach to the people about the coming of the Savior of the World. For he was sent from God, to bear witness of the Light, that all through him might believe. He was not that Light, but was sent to bear witness of that Light. (John 1:6-8)", ar: "وظل منذ أيام طفولته يسكن البرية وعاش فيها أكثر من عشرين سنة عيشة ملائكية حتى يوم ظهوره لإسرائيل (لو 1 : 57 – 80) ." } },
      { kind: 'reading', text: { en: "Now in the fifteenth year of the reign of Tiberius Caesar, Pontius Pilate being governor of Judea, Herod being tetrarch of Galilee, his brother Philip tetrarch of Iturea and the region of Trachonitis, and Lysanias tetrarch of Abilene, Annas and Caiaphas being high priests, the Word of God came to John the son of Zacharias in the wilderness. And he went into all the region around the Jordan, preaching a baptism of repentance for the remission of sins, as it is written in the book of the words of , saying: \"The voice of one crying in the wilderness: 'Prepare the way of the LORD, make His paths straight. Every valley shall be filled and every mountain and hill brought low; and the crooked places shall be made straight and the rough ways made smooth; and all flesh shall see the salvation of God.' \" (Luke 3:1-6)", ar: "وكان لباس يوحنا من وبر الإبل وعلي حقويه منطقه من جلد وكان طعامه الجراد والعسل البري (مت 3 : 4 : مز 1 : 6) وقد أقام بالبرية مواظبا علي الصلاة والتقشف إلى أن أمره الله تعالي لتتم النبوة أن يبشر الشعب بمجيء مخلص العالم (مت 3 : 4 مز 1 : 6 ) لأنه مرسل من الله ليشهد للنور لكي يؤمن الكل بواسطته ولم يكن هو النور بل ليشهد للنور (يو 1 : 6 – 8)" } },
      { kind: 'reading', text: { en: "In those days John the Baptist came preaching in the wilderness of Judea, and saying, \"Repent, for the kingdom of heaven is at hand!\" (Matthew 3:1-2)", ar: "وفي السنة الخامسة عشرة من ملك طيباريوس قيصر حينما كان بيلاطس البنطي واليا علي اليهودية وهيرودس رئيس ربع علي الجليل وفيلبس أخوه رئيس ربع علي ايطورية وبلاد تراكونيتس وليساتوس رئيس ربع علي أبيلية وحنان وقيافا رئيسا للكهنة كانت كلمة الله إلى يوحنا بن زكريا في البرية فجاء إلى بقعة الأردن كلها يكرز بمعمودية التوبة لمغفرة الخطايا كما هو مكتوب في سفر اشعياء النبي &quot; صوت صارخ في البرية أعدوا طريق الرب اصنعوا سبله مستقيمة وكل واد يمتلئ وكل جبل وأكمة ينخفض والمعوج يستقيم ووعر الطريق يصير سهلا ويعاين كل بشر خلاص الله &quot; (لو 3 : 1 – 6) ." } },
      { kind: 'reading', text: { en: "Then Jerusalem, all Judea, and all the region around the Jordan went out to him and were baptized by him in the Jordan, confessing their sins. (Matthew 3:5-6)", ar: "وفي تلك الأيام أقبل يوحنا المعمدان يكرز في برية اليهودية ويقول &quot; توبوا فقد اقترب ملكوت السموات &quot; (مت 3 : 1 و2) ، فكان يخرج اليه أهل أورشليم وكل اليهود وجميع بقعة الأردن فيعتمدون منه في الأردن معترفين بخطاياهم (مت 3 : 5 – 6) ، وإذ كان الشعب ينتظر والجميع يفكرون في قلوبهم عن يوحنا لعله هو المسيح أجابهم يوحنا قائلا : &quot; أنا أعمدكم بماء ولكن يأتي من هو أقوي مني الذي لست أهلا أن أحل سيور حذائه هو سيعمدكم بالروح القدس ونار . الذي رفشه في يده وسينقي بيدره ويجمع القمح إلى مخزنه وأما التبن فيحرقه بنار لا تطفأ (لو 3 : 16 و 17) ، حينئذ أتي يسوع من الجليل إلى الأردن إلى يوحنا ليتعمد منه فمنعه يوحنا قائلا &quot; أنا محتاج أن أعتمد منك وأنت تأتي إلى &quot; فأجابه يسوع قائلا : &quot; اسمح الآن لأنه هكذا ينبغي لنا أن نتمم كل بر &quot; حينئذ تركه . فلما اعتمد يسوع صعد للوقت من الماء فانفتحت له السموات ورأي روح الله نازلا مثل حمامة وحالا عليه &quot; وإذا صوت من السموات قائلا هذا هو ابني الحبيب الذي به سررت (مت 3 : 13 – 17 . لو 3 : 20 – 22) . ثم جاء تلاميذ يوحنا اليه وقالوا له : يا معلم هوذا الذي معك في عبر الأردن الذي أنت قد شهدت له هو يعمد والجميع يأتون اليه . فأجاب يوحنا وقال لا يقدر إنسان أن يأخذ شيئا ان لم يكن قد أعطي من السماء أنتم أنفسكم تشهدون لي أني قلت لست أنا المسيح بل أني مرسل أمامه من له العروس فهو العريس ، إذا فرحي هذا قد كمل ينبغي أن ذلك يزيد وأني أنا أنقص الذي يأتي من فوق هو فوق الجميع والذي من الأرض هو أرضي ومن الأرض يتكلم الذي يأتي من السماء هو فوق الجميع وما رآه وسمعه به يشهد وشهادته ليس أحد يقبلها ومن قبل شهادته فقد ختم أن الله صادق لآن الذي أرسله الله يتكلم بكلام الله لأنه ليس بكيل يعطي الله الروح . الآب يحب الابن وقد دفع كل شيء في يده الذي يؤمن بالابن له حياة أبدية والذي لا يؤمن بالابن لن يري حياة بل يمكث عليه غضب الله (يو 3 : 26 – 36)" } },
      { kind: 'reading', text: { en: "While the people were waiting, and thinking in their hearts about John if he was the Christ, John answered, saying to them all, \"I indeed baptize you with water; but One mightier than I is coming, whose sandal strap I am not worthy to loose. He will baptize you with the Holy Spirit and with fire. His winnowing fan is in His hand, and He will thoroughly purge His threshing floor, and gather the wheat into His barn; but the chaff He will burn with unquenchable fire.\" (Luke 3:16-17)", ar: "ولما رأي يوحنا أن كثيرين من الفريسيين والصدوقيين يأتون إلى معموديته قال لهم : &quot; يا أولاد الأفاعي من أراكم أن تهربوا من الغضب الآتي . فاصنعوا أثمار تليق بالتوبة ولا تفتكروا أن تقولوا في أنفسكم لنا ابراهيم أبا لأني أقول لكم أن الله قادر أن يقيم من هذه الحجارة أولادا لإبراهيم . والآن قد وضعت الفأس علي أصل الشجرة فكل شجرة لا تصنع ثمرا جيدا تقطع وتلقي في النار ولما كان هيرودس أنتيباس بن هيرودس المدعو الكبير قد تزوج بهيروديا امرأة أخيه فيلبس ضد كل الشرائع ، فأتي إليه القديس يوحنا المعمدان موبخا إياه علي هذا الذنب وعلي كل الشر الذي كان يصنعه ، فأمر بناء علي تحريض هيروديا الفاجرة أن قبض علي يوحنا ويقيد بالسلاسل ويوضع في السجن داخل الحصن المدعو ماكرونده ." } },
      { kind: 'reading', text: { en: "Then . And John tried to prevent Him, saying, \"I have need to be baptized by You, and are You coming to me?\" But Jesus answered and said to him, \"Permit it to be so now, for thus it is fitting for us to fulfill all righteousness.\" Then he allowed Him. Then Jesus, when He had been baptized, came up immediately from the water; and behold, the heavens were opened to Him, and He saw the Spirit of God descending like a dove and alighting upon Him. And suddenly a voice came from heaven, saying, \"This is My beloved Son, in whom I am well pleased.\" (Matthew 3:13-17) (Luke 3:20-22)", ar: "واستمر يوحنا في هذا السجن مدة سنة كاملة دون أن يتمكن لهيرودس أن يقتله وكان تلاميذه يترددون بكل شجاعة علي معلمهم وهو في السجن ، كما أنه لم يهمل واجباته نحوهم مبرهنا لهم أن يسوع هو المسيح المنتظر وحينما شاع في كل مكان خبر العجائب التي كان مخلصنا يصنعها كان يوحنا يريد أن يكون تلاميذه شهود عيان لعجائب المسيح حتى يثبتوا علي الإيمان به ." } },
      { kind: 'reading', text: { en: "Then John's disciples came to him and said, \"Rabbi, He who was with you beyond the Jordan, to whom you have testified; behold, He is baptizing, and all are coming to Him!\" John answered and said, \"A man can receive nothing unless it has been given to him from heaven. You yourselves bear me witness, that I said, 'I am not the Christ,' but, 'I have been sent before Him.' He who has the bride is the bridegroom; but the friend of the bridegroom, who stands and hears him, rejoices greatly because of the bridegroom's voice. Therefore this joy of mine is fulfilled. He must increase, but I must decrease. He who comes from above is above all; he who is of the earth is earthly and speaks of the earth. He who comes from heaven is above all. And what He has seen and heard, that He testifies; and no one receives His testimony. He who has received His testimony has certified that God is true. For He whom God has sent speaks the words of God, for God does not give the Spirit by measure. The Father loves the Son, and has given all things into His hand. He who believes in the Son has everlasting life; and he who does not believe the Son shall not see life, but the wrath of God abides on him.\" (John 3:26-36)", ar: "فأرسل وهو في السجن اثنين من تلاميذه يقولان ليسوع &quot; هل أنت المسيح الآتي أم ننتظر آخر ؟ &quot; فأجاب يسوع وقال لهما &quot; اذهبا واعلما يوحنا بما سمعتما ورأيتما . العمي يبصرون والعرج يمشون والبرص يطهرون والصم يسمعون والموتي يقومون والمساكين يبشرون وطوبى لمن لا يشك في ثم قال يسوع للجموع عن يوحنا : &quot; ماذا خرجتم إلى البرية لتنظروا ؟ أانسانا لابسا ثيابا ناعمة ؟ هوذا الذين عليهم اللباس الناعم في بيوت الملوك . أم ماذا خرجتم لتنظروا ؟ أنبيا ؟ نعم أقول لكم وأفضل من نبي فان هذا هو الذي كتب عنه ها أنذا مرسل ملاكي أمام وجهك الذي يهيئ طريقك أمامك . الحق أقول لكم لم يقم بين مواليد النساء أعظم من يوحنا المعمدان ولكن الأصغر في ملكوت السموات أعظم منه ، ومن أيام يوحنا المعمدان إلى الآن ملكوت السموات يغصب والغاصبون يختطفونه لان جميع الأنبياء والناموس إلى يوحنا تنبأوا وأن أردتم أن تقبلوا فهذا هو ايليا المزمع أن يأتي . من له أذنان للسمع فليسمع . وبمن أشبه هذا الجيل . يشبه صبيانا جلوسا في السوق يصيحون بأصحابهم قائلين : زمرنا لكم فلم ترقصوا نحنا لكم فلم تلطموا . جاء يوحنا لا يأكل ولا يشرب فقالوا ان به شيطانا وجاء ابن البشر يأكل ويشرب فقالوا هوذا إنسان أكول وشريب خمر محب للعشارين والخطاة والحكمة تبررت من بينها (مت 11 : 7 – 19) ، كما قال السيد المسيح له المجد عن يوحنا المعمدان أيضا : كان هو السراج الموقد المنير وأنتم أردتم أن تبتهجوا بنوره ساعة ." } },
      { kind: 'reading', text: { en: "But when John saw many of the Pharisees and Sadducees coming to his baptism, he said to them, \"Brood of vipers! Who has warned you to flee from the wrath to come? Therefore bear fruits worthy of repentance, and do not think to say to yourselves, 'We have Abraham as our father.' For I say to you that God is able to raise up children to Abraham from these stones. And even now the ax is laid to the root of the trees. Therefore every tree which does not bear good fruit is cut down and thrown into the fire. (Matthew 3:7-10) (Luke 3:7-9)", ar: "وكانت هيروديا تريد التخلص من يوحنا المعمدان فدبرت مكيدتها في يوم الاحتفال بميلاد هيرودس فلما كان مولد هيرودس رقصت ابنة هيروديا في الوسط فأعجبت هيرودس ولذلك وعدها بقسم أن يعطيها كل ما تطلبه . فتلقنت من أمها ثم أتت وقالت &quot; أعطني ههنا رأس يوحنا المعمدان في طبق &quot; فحزن الملك ولكن من أجل اليمين والمتكئين معه أمر أن تعطاه . وأرسل فقطع رأس يوحنا في السجن وأتي بالرأس في طبق ودفع به إلى الصبية فجاءت بها إلى أمها . فجاء تلاميذه وأخذوا جسده ودفنوه وأتوا واخبروا يسوع فلما سمع مضي من هناك في سفينة إلى البرية وتبدل فرح الجمع بعيد هيرودس حزنا أما الرأس فطار من أيديهم وهو يصرخ قائلا : &quot; لا يحل لك أن تأخذ امرأة أخيك &quot;." } },
      { kind: 'reading', text: { en: "When Herod Antipas, the son of Herod the Great, married Herodias, the wife of his brother Philip, against all the Laws, St. John the Baptist came to him. He admonished him for his transgression and all the evil things that he was doing. So Herod ordered, according to the instigation of Herodias the adulterer, to seize John, chain him and imprison him in the fortress called Macronda.", ar: "وحدث موت القديس يوحنا المعمدان في أواخر السنة الحادية والثلاثين أو في بدء السنة الثانية والثلاثين للمسيح قد شابه هذا القديس الملائكة بسيرته الطاهرة وامتلأ من الروح القدس وهو في بطن أمه ومات شهيدا للحق (تذكار استشهاده يوم 2 توت) صلاته تكون معنا ولربنا المجد دائما . آمين" } },
      { kind: 'reading', text: { en: "John remained in this jail for a year, without Herod being able to slay him. His disciples visited their teacher, frequently and courageously, in prison. As he did not neglect his duties toward them, proving to them that Jesus was the expected Christ. When the news of the wonders that our Savior did noised everywhere, John wanted his disciples to be eye witnesses to the wonders of Christ, to be confirmed in their faith in him.", ar: "" } },
      { kind: 'reading', text: { en: "While he was in prison, , who said to Him, \"Are You the Coming One, or do we look for another?\" Jesus answered and said to them, \"Go and tell John the things which you hear and see: The blind receive their sight and the lame walk; the lepers are cleansed and the deaf hear; the dead are raised up and the poor have the gospel preached to them. And blessed is he who is not offended because of Me.\" (Matthew 11:2-6)", ar: "" } },
      { kind: 'reading', text: { en: "As they departed, Jesus began to say to the multitudes concerning John, \"What did you go out into the wilderness to see? A reed shaken by the wind? But what did you go out to see? A man clothed in soft garments? Indeed, those who wear soft clothing are in kings' houses. But what did you go out to see? A prophet? Yes, I say to you, and more than a prophet. For this is he of whom it is written: 'Behold, I send My messenger before Your face, who will prepare Your way before You.' Assuredly, I say to you, among those born of women there has not risen one greater than John the Baptist; but he who is least in the kingdom of heaven is greater than he. And from the days of John the Baptist until now the kingdom of heaven suffers violence, and the violent take it by force. For all the prophets and the law prophesied until John. And if you are willing to receive it, he is who is to come. He who has ears to hear, let him hear! But to what shall I liken this generation? It is like children sitting in the marketplaces and calling to their companions, and saying: 'We played the flute for you, And you did not dance; we mourned to you, And you did not lament.' For John came neither eating nor drinking, and they say, 'He has a demon.' The Son of Man came eating and drinking, and they say, 'Look, a gluttonous man and a winebibber, a friend of tax collectors and sinners!' But wisdom is justified by her children.\" (Matthew 11:7-19)", ar: "" } },
      { kind: 'reading', text: { en: "The Lord Christ, to Whom is the Glory, also said about John the Baptist: \"He was the burning and shining lamp, and you were willing for a time to rejoice in his light.\" (John 5:35)", ar: "" } },
      { kind: 'reading', text: { en: "Herodias desired to get rid of John the Baptist, so she executed her scheme during the celebration of Herod's birthday.", ar: "" } },
      { kind: 'reading', text: { en: "When Herod's birthday was celebrated, the daughter of Herodias danced before them and pleased Herod. Therefore he promised with an oath to give her whatever she might ask. So she, having been prompted by her mother, said, \"Give me John the Baptist's head here on a platter.\" And the king was sorry; nevertheless, because of the oaths and because of those who sat with him at the table, he commanded it to be given to her. So he sent and had John beheaded in prison. And his head was brought on a platter and given to the girl, and she brought it to her mother. Then his disciples came and took away the body and buried it, and went and told Jesus. When Jesus heard of it, he departed thence by ship into a desert place apart. (Matthew 14:2-13) The joy of the people celebrating Herod's birthday turned into sorrow. As of the head, it flew up from their hands and was crying out saying: \"It is not right for you to take your brother's wife.\" The martyrdom of St. John took place at the end of the thirty-first or at the beginning of the thirty-second year of the Christ. was like that of the angels in purity. He was filled with the Holy Spirit while he was in his mother's womb, and was martyred for his witnessing to the truth.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us and Glory be to God forever. Amen.", ar: "" } }
    ],
  }
];
